/// Native graph reads are intentionally bounded even when the immutable
/// history itself is unbounded.  These values mirror the durable journal
/// replay contract and are part of the v1 IPC projection contract.
pub const MAX_STATE_REVISION_GRAPH_PAGE_SIZE: u32 = 1_000;
pub const DEFAULT_STATE_REVISION_GRAPH_PAGE_SIZE: u32 = 250;
pub const MAX_STATE_REVISION_GRAPH_PARENTS_PER_REVISION: u32 = 256;
pub const MAX_STATE_REVISION_GRAPH_PAGE_BYTES: usize = 4 * 1024 * 1024;
const MAX_STATE_REVISION_GRAPH_CURSOR_BYTES: usize = 8 * 1024;
const STATE_REVISION_GRAPH_CURSOR_PREFIX: &str = "srgr1";
const STATE_REVISION_GRAPH_CURSOR_SCHEMA_VERSION: u32 = 1;
const MAX_PROJECT_NAME: usize = 200;
const MAX_BRANCH_NAME: usize = 120;
const MAX_PROJECT_DESCRIPTION: usize = 8_000;
const MAX_PROJECT_INSTRUCTIONS: usize = 256_000;
const MAX_CONVERSATION_TITLE: usize = 500;
pub(crate) const MAX_MESSAGE_BYTES: usize = 2 * 1024 * 1024;
const MAX_MODEL_ID: usize = 512;
const MAX_PARAMETER_JSON_BYTES: usize = 256 * 1024;
const MAX_STATE_REVISION_JSON_BYTES: usize = 256 * 1024;
const MAX_STATE_REVISION_IDEMPOTENCY_KEY_BYTES: usize = 512;
const MAX_STATE_REVISION_ID_BYTES: usize = 256;
const MAX_RUN_CONTROL_OPERATION_JSON_BYTES: usize = 256 * 1024;

const MAX_RUN_CONTROL_LIST_ITEMS: usize = 256;
const MAX_RUN_CONTROL_ITEM_ID_BYTES: usize = 256;
const MAX_RUN_CONTROL_REDACTION_CLASS_BYTES: usize = 120;
const MAX_GOAL_TITLE: usize = 500;
const MAX_GOAL_DESCRIPTION: usize = 16_000;
const MAX_GOAL_JSON_BYTES: usize = 256 * 1024;
const MAX_GOAL_REVISION_JSON_BYTES: usize = 512 * 1024;
const MAX_GOAL_IDEMPOTENCY_KEY_BYTES: usize = 512;
const MAX_GOAL_LIST_LIMIT: i64 = 256;
const MAX_TASK_TITLE: usize = 500;
const MAX_TASK_DESCRIPTION: usize = 16_000;
const MAX_TASK_METADATA_BYTES: usize = 256 * 1024;
const MAX_TASK_REVISION_BYTES: usize = 512 * 1024;

const MAX_TASK_LIST_LIMIT: i64 = 256;
const MAX_STARTER_WORKFLOW_NAME: usize = 200;
const MAX_STARTER_WORKFLOW_TITLE: usize = 500;
const MAX_STARTER_WORKFLOW_DESCRIPTION: usize = 16_000;
const MAX_STARTER_WORKFLOW_DEFINITION_BYTES: usize = 512 * 1024;
const MAX_STARTER_WORKFLOW_REVISION_BYTES: usize = 1024 * 1024;
const MAX_STARTER_WORKFLOW_IDEMPOTENCY_KEY_BYTES: usize = 512;
const MAX_STARTER_WORKFLOW_LIST_LIMIT: i64 = 256;
// Continuation envelopes are renderer input and are persisted as immutable
// facts. Keep every numeric/textual guard finite so a malformed request cannot
// turn canonicalisation, JSON decoding, or later scheduling into an
// unbounded operation. These are product-level safety ceilings, not provider
// capability claims.
const MAX_CONTINUATION_TOKENS: i64 = 1_000_000_000;
const MAX_CONTINUATION_COST_BYTES: usize = 128;
const MAX_CONTINUATION_DURATION_SECONDS: i64 = 31_536_000; // 365 days
const MAX_CONTINUATION_SEGMENTS: i64 = 1_000_000;

/// A single picker draft can contain multiple files. Keep the number of drafts
/// that can enter one run bounded so the bind transaction and later bridge
/// planner cannot be made unbounded by a renderer request.
const MAX_ATTACHMENT_DRAFTS_PER_RUN: usize = 32;

