/// Renderer-safe projection of one authoritative goal.  JSON manifests are
/// returned only after native canonicalisation and hash verification; no
/// provider payload, credential, cookie, prompt body, or filesystem path is
/// part of this contract.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct GoalRecord {
    pub id: String,
    pub profile_id: String,
    pub project_id: Option<String>,
    pub conversation_id: Option<String>,
    pub branch_id: Option<String>,
    pub current_revision_id: String,
    pub state_revision_id: Option<String>,
    pub status: String,
    pub title: String,
    pub description: Option<String>,
    pub acceptance_criteria_json: String,
    pub roadmap_json: String,
    pub metadata_json: String,
    pub canonical_payload_sha256: String,
    pub created_at_ms: i64,
    pub updated_at_ms: i64,
    pub deleted_at_ms: Option<i64>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct GoalRevisionRecord {
    pub revision_id: String,
    pub goal_id: String,
    pub revision_no: i64,
    pub payload_json: String,
    pub content_sha256: String,
    pub state_revision_id: Option<String>,
    pub created_at_ms: i64,
}

/// A goal read is intentionally preview-only until a typed goal execution
/// authority is introduced.  A row's existence must never be interpreted by
/// the renderer as permission to execute arbitrary work.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct GoalSnapshot {
    pub goal: GoalRecord,
    pub current_revision: GoalRevisionRecord,
    /// When a historical revision is requested (or a mutation receipt is
    /// replayed after a later revision exists), this carries the immutable
    /// selected revision separately from the authoritative current pointer.
    /// Keeping the two fields distinct prevents a mixed snapshot whose root
    /// projection describes one revision while `currentRevision` describes
    /// another.
    pub selected_revision: Option<GoalRevisionRecord>,
    pub execution_disposition: String,
    pub integrity: String,
    pub replayed: bool,
}

/// Bounded list projection for goals. Listing must not materialise the
/// potentially large roadmap, acceptance-criteria, or metadata manifests for
/// every row; callers can request one exact snapshot when those fields are
