/// Renderer-safe projection of one native starter workflow.  The workflow
/// definition is returned only after the native layer has verified its
/// canonical hash, immutable revision pointer, exact scope, and lifecycle.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct StarterWorkflowRecord {
    pub id: String,
    pub profile_id: String,
    pub project_id: Option<String>,
    pub conversation_id: Option<String>,
    pub branch_id: Option<String>,
    pub current_revision_id: String,
    pub state_revision_id: Option<String>,
    pub status: String,
    pub enabled: bool,
    pub name: String,
    pub title: String,
    pub description: Option<String>,
    pub definition_json: String,
    pub canonical_payload_sha256: String,
    pub created_at_ms: i64,
    pub updated_at_ms: i64,
    pub deleted_at_ms: Option<i64>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct StarterWorkflowRevisionRecord {
    pub revision_id: String,
    pub starter_workflow_id: String,
    pub revision_no: i64,
    pub definition_json: String,
    pub content_sha256: String,
    pub state_revision_id: Option<String>,
    pub created_at_ms: i64,
}

/// A workflow read is preview-only until a typed workflow execution authority,
/// approval policy, and lifecycle journal are complete.  A renderer must not
/// infer execution permission from this snapshot's existence.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct StarterWorkflowSnapshot {
    pub workflow: StarterWorkflowRecord,
    pub current_revision: StarterWorkflowRevisionRecord,
    /// When a historical revision is requested (or a mutation receipt is
    /// replayed after a later revision exists), this carries the immutable
    /// receipt-selected revision separately from the authoritative current
    /// pointer. Keeping these fields distinct prevents replay from silently
    /// returning a newer revision than the one committed by the receipt.
    pub selected_revision: Option<StarterWorkflowRevisionRecord>,
    pub execution_disposition: String,
    pub integrity: String,
    pub replayed: bool,
}

