/// Native request for one immutable state-revision mutation. The renderer is
/// allowed to provide only bounded JSON manifests; the native kernel resolves
/// the stream, observed head and branch sequence inside one SQLite
/// transaction. JSON values are intentionally retained as opaque, redacted
/// manifests and are never returned by the graph projection API.
#[derive(Clone, Debug, serde::Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct StateRevisionAppendRequest {
    pub conversation_id: String,
    pub branch_id: String,
    pub kind: String,
    pub status: String,
    pub expected_head_state_revision_id: Option<String>,
    pub idempotency_key: String,
    #[serde(default)]
    pub parent_state_revision_ids: Vec<String>,
    #[serde(default = "empty_json_object")]
    pub watermark_json: String,
    #[serde(default = "empty_json_object")]
    pub actor_json: String,
    #[serde(default = "empty_json_object")]
    pub causation_json: String,
    #[serde(default = "empty_json_object")]
    pub manifest_json: String,
    #[serde(default = "empty_json_object")]
    pub authority_json: String,
    #[serde(default = "empty_json_object")]
    pub routing_cache_json: String,
    pub state_digest: Option<String>,
    #[serde(default = "default_canonicalization_revision")]
    pub canonicalization_revision: String,
    pub edge_kind: Option<String>,
    pub operation_id: Option<String>,
    #[serde(default = "empty_json_object")]
    pub causal_cursor_json: String,
    #[serde(default = "default_policy_revision")]
    pub policy_revision_id: String,
}

fn default_canonicalization_revision() -> String {
    "state-revision-c14n-v1".to_owned()
}

fn default_policy_revision() -> String {
    "policy-local-default-v1".to_owned()
}

#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct StateRevisionMutationResult {
    pub outcome: String,
    pub stream_id: String,
    pub revision_id: Option<String>,
    pub accepted_head_state_revision_id: Option<String>,
    pub current_head_state_revision_id: Option<String>,
    pub expected_head_state_revision_id: Option<String>,
    pub branch_sequence: i64,
    pub canonical_payload_hash: String,
    pub safe_diff: Option<String>,
    /// Cursor of the state-revision journal fact committed with this
    /// mutation. Replay outcomes may expose the original cursor; conflict
    /// outcomes intentionally leave these fields empty because no new fact
    /// was appended.
    pub journal_epoch: Option<String>,
    pub journal_sequence: Option<i64>,
    pub journal_event_id: Option<String>,
}

#[derive(Clone, Debug)]
struct StateRevisionJournalEventCursor {
    journal_epoch: String,
    sequence: i64,
    event_id: String,
}

/// Native scope used while resolving a renderer cursor.  The renderer may
/// select a conversation/branch and optionally pin a source run, but it never
/// supplies the authority row itself.  Keeping this scope typed makes it
/// difficult to accidentally resolve a cursor through a similarly-shaped
/// projection table.
#[derive(Clone, Debug)]
struct CursorAuthorityScope<'a> {
    conversation_id: &'a str,
    branch_id: &'a str,
    run_id: Option<&'a str>,
}

/// Fixed watermark passed to the typed cursor resolver.  Values are captured
/// from the same SQLite transaction as the operation receipt; for a
/// historical state base the branch value is anchored to that revision's own
/// journal event, while a run value is the stored run cursor position.  A
/// cursor above one of these bounds is therefore never accepted merely
/// because it is numerically within a later mutable head.
#[derive(Clone, Copy, Debug, Default)]
struct CursorFixedWatermark {
    branch_sequence: Option<i64>,
    run_sequence: Option<i64>,
}

/// Native-owned cursor facts.  This is deliberately not a renderer DTO: the
/// event identity, lineage and payload hash are returned only after both
/// journal addresses have identified the same durable row.
#[derive(Clone, Debug, PartialEq, Eq)]
struct ResolvedCursorFact {
    stream_kind: RunControlStreamKind,
    stream_id: String,
    journal_epoch: String,
    sequence: i64,
    event_id: String,
    event_type: String,
    revision_id: Option<String>,
    run_id: Option<String>,
    attempt_id: Option<String>,
    committed_at_ms: i64,
    coverage: String,
    payload_hash: String,
}

const CURSOR_EVENT_CANONICALIZATION_REVISION: &str = "cursor-event-c14n-v1";

/// A journal event resolved through one of the two independent receipt
/// addresses.  Receipt replay resolves both `(stream_id, revision_id)` and
/// `(stream_id, sequence_no)`, then requires these complete envelopes to agree
/// before treating an idempotency receipt as durable evidence.  Keeping the
/// envelope private prevents this low-level validation shape from becoming an
/// IPC contract.
#[derive(Clone, Debug, PartialEq, Eq)]
struct StateRevisionReceiptJournalEvent {
    stream_id: String,
    journal_epoch: String,
    sequence: i64,
    event_id: String,
    revision_id: String,
    payload_json: String,
    schema_version: i64,
    event_type: String,
    source: String,
    visibility: String,
    sensitivity: String,
}

/// Private, immutable receipt persisted beside one state-revision
/// idempotency key.  This is deliberately separate from
/// `StateRevisionMutationResult`: the latter contains the live head observed
/// by the caller, while this receipt must remain a lossless record of the
/// original commit after later revisions advance the branch.
///
/// Journal cursor fields are optional only for databases migrated from v11.
/// Those databases may contain historical idempotency rows created before the
/// state-revision journal existed and therefore cannot be assigned a made-up
/// event.  Every receipt created by the v12 append path contains all three
/// cursor fields together.
#[derive(Clone, Debug, serde::Deserialize, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct StateRevisionReceipt {
    schema_version: i64,
    outcome: String,
    revision_id: String,
    stream_id: String,
    accepted_head_state_revision_id: Option<String>,
    expected_head_state_revision_id: Option<String>,
    branch_sequence: i64,
    canonical_payload_hash: String,
    #[serde(default)]
    journal_epoch: Option<String>,
    #[serde(default)]
    journal_sequence: Option<i64>,
    #[serde(default)]
    journal_event_id: Option<String>,
}

impl StateRevisionReceipt {
    /// Returns the immutable journal cursor carried by this receipt when all
    /// cursor components are present.  Receipt validation is responsible for
    /// rejecting partial cursors; keeping this accessor deliberately
    /// non-panicking lets the replay result remain a read-only projection even
    /// for legacy v11 receipts that predate the state-revision journal.
    fn journal_cursor(&self) -> Option<StateRevisionJournalEventCursor> {
        match (
            self.journal_epoch.as_ref(),
            self.journal_sequence,
            self.journal_event_id.as_ref(),
        ) {
            (Some(journal_epoch), Some(sequence), Some(event_id)) => {
                Some(StateRevisionJournalEventCursor {
                    journal_epoch: journal_epoch.clone(),
                    sequence,
                    event_id: event_id.clone(),
                })
            }
            _ => None,
        }
    }
}

