#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase")]
/// Bounded native IPC graph-read projection (runtime contract v1).
///
/// This deliberately redacted DTO is not the rich portable graph-export
/// schema in `docs/omnia-ultra/schemas/state-revision-graph.schema.json`.
/// Keeping the contracts separate prevents callers from treating omitted
/// authority, manifest, causation, cursor and diagnostic facts as if they
/// had been reconstructed. A future export adapter must read immutable facts
/// at one fixed watermark and fail closed when required coverage is absent.
pub struct StateRevisionGraphSnapshot {
    pub schema_version: i64,
    pub stream_id: String,
    pub conversation_id: String,
    pub branch_id: String,
    pub accepted_head_state_revision_id: Option<String>,
    pub accepted_head_branch_sequence: i64,
    pub through_branch_sequence: i64,
    pub revisions: Vec<StateRevisionProjection>,
    pub edges: Vec<StateRevisionEdgeProjection>,
    pub integrity: String,
    pub revisions_has_more: bool,
    pub edges_has_more: bool,
    pub next_revisions_cursor: Option<String>,
    pub next_edges_cursor: Option<String>,
    pub revisions_limit: u32,
    pub edges_limit: u32,
    pub response_bytes: u64,
}

