/// Upgrades the v9 bridge artifact table without rewriting provenance rows.
/// SQLite cannot alter a CHECK constraint in place, so the table is rebuilt in
/// the same migration transaction and its integrity triggers are recreated.
fn apply_v10(transaction: &Transaction<'_>) -> NativeResult<()> {
    const CURRENT_SCHEMA: &str = include_str!("../../docs/storage-schema.sql");
    let bridge_hardening_schema = split_multimodal_bridge_hardening_schema(CURRENT_SCHEMA)?;
    transaction.execute_batch(bridge_hardening_schema)?;
    let artifact_table_sql: String = transaction.query_row(
        "SELECT sql FROM sqlite_master
         WHERE type = 'table' AND name = 'multimodal_bridge_plan_artifacts'",
        [],
        |row| row.get(0),
    )?;
    if artifact_table_sql.contains("'unclassified'") {
        return Err(NativeError::new(
            "multimodal_bridge_schema_migration_failed",
            "The v10 bridge artifact table permits an unclassified modality",
        ));
    }
    let now = now_ms();
    transaction.execute(
        "UPDATE schema_meta
         SET schema_version = ?1, min_app_version = '0.9.0', updated_at_ms = ?2
         WHERE singleton = 1",
        params![10_i64, now],
    )?;
    transaction.execute(
        "INSERT INTO schema_migrations (
            migration_id, checksum_sha256, started_at_ms, completed_at_ms,
            duration_ms, app_version
         ) VALUES ('0010_multimodal_bridge_review_hardening', ?1, ?2, ?2, 0, '0.9.0')",
        params![sha256_hex(bridge_hardening_schema.as_bytes()), now],
    )?;
    Ok(())
}

