fn apply_v12(transaction: &Transaction<'_>) -> NativeResult<()> {
    const CURRENT_SCHEMA: &str = include_str!("../../docs/storage-schema.sql");
    let state_revision_journal_schema = split_state_revision_journal_schema(CURRENT_SCHEMA)?;
    transaction.execute_batch(state_revision_journal_schema)?;
    for table in ["state_revision_journals", "state_revision_events"] {
        if !table_exists_in_transaction(transaction, table)? {
            return Err(NativeError::new(
                "state_revision_journal_schema_migration_failed",
                format!("The state-revision journal table {table} was not installed"),
            ));
        }
    }

    // State-revision streams can predate this journal.  Mark those streams as
    // legacy-partial rather than fabricating historical events; all new
    // mutations are complete once this migration commits.
    let legacy_reason = "state-revision journal introduced after existing stream history";
    let mut existing_streams = transaction.prepare(
        "SELECT id, created_at_ms
         FROM state_revision_streams
         WHERE NOT EXISTS (
             SELECT 1 FROM state_revision_journals journal
             WHERE journal.stream_id = state_revision_streams.id
         )
         ORDER BY created_at_ms, id",
    )?;
    let streams = existing_streams
        .query_map([], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)?))
        })?
        .collect::<Result<Vec<_>, _>>()?;
    drop(existing_streams);
    for (stream_id, created_at_ms) in streams {
        let journal_epoch = format!("state_journal_epoch_{}", Uuid::new_v4().simple());
        transaction.execute(
            "INSERT INTO state_revision_journals (
                stream_id, schema_version, journal_epoch, coverage, coverage_reason,
                created_at_ms
             ) VALUES (?1, 1, ?2, 'legacy-partial', ?3, ?4)",
            params![
                stream_id,
                journal_epoch,
                legacy_reason,
                created_at_ms.max(1)
            ],
        )?;
    }

    let now = now_ms();
    transaction.execute(
        "UPDATE schema_meta
         SET schema_version = ?1, min_app_version = '0.11.0', updated_at_ms = ?2
         WHERE singleton = 1",
        params![12_i64, now],
    )?;
    transaction.execute(
        "INSERT INTO schema_migrations (
            migration_id, checksum_sha256, started_at_ms, completed_at_ms,
            duration_ms, app_version
         ) VALUES ('0012_state_revision_journal', ?1, ?2, ?2, 0, '0.11.0')",
        params![sha256_hex(state_revision_journal_schema.as_bytes()), now],
    )?;
    Ok(())
}

fn apply_v13(transaction: &Transaction<'_>) -> NativeResult<()> {
    const CURRENT_SCHEMA: &str = include_str!("../../docs/storage-schema.sql");
    let operation_fact_schema = split_state_revision_operation_fact_schema(CURRENT_SCHEMA)?;
    transaction.execute_batch(operation_fact_schema)?;
    if !table_exists_in_transaction(transaction, "state_revision_operation_facts")?
        || !table_has_column(transaction, "state_revision_operation_facts", "coverage")?
        || !table_has_column(
            transaction,
            "state_revision_operation_facts",
            "causal_cursor_json",
        )?
    {
        return Err(NativeError::new(
            "state_revision_operation_fact_schema_migration_failed",
            "The state-revision operation-fact table was not installed completely",
        ));
    }

    // Preserve historical truth.  Metadata is marked complete only when all
    // existing parent edges agree on one operation fact.  Roots and revisions
    // with no edges cannot be assigned invented values, so they remain
    // legacy-partial until a later repair/import supplies explicit evidence.
    let mut revisions = transaction.prepare(
        "SELECT revision.id
         FROM state_revisions revision
         WHERE NOT EXISTS (
             SELECT 1 FROM state_revision_operation_facts fact
             WHERE fact.revision_id = revision.id
         )
         ORDER BY revision.created_at_ms, revision.id",
    )?;
    let revision_ids = revisions
        .query_map([], |row| row.get::<_, String>(0))?
        .collect::<Result<Vec<_>, _>>()?;
    drop(revisions);
    for revision_id in revision_ids {
        let mut edges = transaction.prepare(
            "SELECT operation_id, causal_cursor_json, policy_revision_id
             FROM state_revision_edges
             WHERE from_revision_id = ?1
             ORDER BY created_at_ms, id",
        )?;
        let edge_rows = edges
            .query_map([&revision_id], |row| {
                Ok((
                    row.get::<_, Option<String>>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                ))
            })?
            .collect::<Result<Vec<_>, _>>()?;
        drop(edges);
        let recovered = edge_rows.first().and_then(|first| {
            if edge_rows.iter().all(|candidate| candidate == first)
                && !first.1.is_empty()
                && serde_json::from_str::<serde_json::Value>(&first.1)
                    .ok()
                    .is_some_and(|value| {
                        value.is_object() && value.to_string().as_str() == first.1.as_str()
                    })
                && !first.2.is_empty()
                && first.2.len() <= MAX_STATE_REVISION_ID_BYTES
            {
                Some(first.clone())
            } else {
                None
            }
        });
        let now = now_ms();
        if let Some((operation_id, causal_cursor_json, policy_revision_id)) = recovered {
            transaction.execute(
                "INSERT INTO state_revision_operation_facts (
                    revision_id, operation_id, causal_cursor_json,
                    policy_revision_id, coverage, created_at_ms
                 ) VALUES (?1, ?2, ?3, ?4, 'complete', ?5)",
                params![
                    revision_id,
                    operation_id,
                    causal_cursor_json,
                    policy_revision_id,
                    now.max(1)
                ],
            )?;
        } else {
            transaction.execute(
                "INSERT INTO state_revision_operation_facts (
                    revision_id, operation_id, causal_cursor_json,
                    policy_revision_id, coverage, created_at_ms
                 ) VALUES (?1, NULL, NULL, NULL, 'legacy-partial', ?2)",
                params![revision_id, now.max(1)],
            )?;
        }
    }

    let now = now_ms();
    transaction.execute(
        "UPDATE schema_meta
         SET schema_version = ?1, min_app_version = '0.12.0', updated_at_ms = ?2
         WHERE singleton = 1",
        params![13_i64, now],
    )?;
    transaction.execute(
        "INSERT INTO schema_migrations (
            migration_id, checksum_sha256, started_at_ms, completed_at_ms,
            duration_ms, app_version
         ) VALUES ('0013_state_revision_operation_facts', ?1, ?2, ?2, 0, '0.12.0')",
        params![sha256_hex(operation_fact_schema.as_bytes()), now],
    )?;
    Ok(())
}

