fn split_provider_attempt_lineage_schema(current_schema: &str) -> NativeResult<&str> {
    let lineage_schema = current_schema
        .split_once(PROVIDER_ATTEMPT_LINEAGE_SCHEMA_MARKER)
        .map(|(_, schema)| schema)
        .ok_or_else(|| {
            NativeError::new(
                "schema_definition_invalid",
                "The provider-attempt lineage storage migration marker is missing",
            )
        })?;

    // The v15 run-control block is appended to the schema after the v14
    // provider-attempt lineage block.  Keep the v14 migration bounded to the
    // lineage statements; otherwise a v14 database would attempt to execute
    // v15 DDL before its schema metadata/version transition.
    Ok(lineage_schema
        .split_once(RUN_CONTROL_SCHEMA_MARKER)
        .map(|(schema, _)| schema)
        .unwrap_or(lineage_schema))
}

