    fn table_exists(connection: &Connection, table_name: &str) -> bool {
        connection
            .query_row(
                "SELECT EXISTS(
                    SELECT 1 FROM sqlite_schema
                    WHERE type = 'table' AND name = ?1
                 )",
                [table_name],
                |row| row.get(0),
            )
            .expect("schema query should succeed")
    }

    fn foreign_key_violations(connection: &Connection) -> i64 {
        connection
            .query_row("SELECT COUNT(*) FROM pragma_foreign_key_check", [], |row| {
                row.get(0)
            })
            .expect("foreign-key check should succeed")
    }

    fn has_column(connection: &Connection, table_name: &str, column_name: &str) -> bool {
        let mut statement = connection
            .prepare(&format!("PRAGMA table_info({table_name})"))
            .expect("table-info query should prepare");
        statement
            .query_map([], |row| row.get::<_, String>(1))
            .expect("table-info query should run")
            .collect::<Result<Vec<_>, _>>()
            .expect("table-info rows should load")
            .iter()
            .any(|name| name == column_name)
    }

    fn create_test_provider(storage: &Storage, display_name: &str) -> ProviderProfileRecord {
        storage
            .save_provider_profile(NewProviderProfile {
                provider_type: "openai_compatible",
                display_name,
                normalized_base_url: "https://api.example.com/v1",
                auth_scheme: "bearer",
                organization_id: None,
                remote_project_id: None,
                credential_ref: Some("provider_secret_0123456789abcdef0123456789abcdef"),
                local_network_grant: false,
            })
            .expect("provider should be created")
    }

    /// Cursor authority failures cross the renderer boundary under the single
    /// stable `invalid_state_base` code; the specific fail-closed reason is the
    /// leading token of the diagnostic message.
    fn assert_cursor_authority_error(error: &NativeError, reason: &str) {
        assert_eq!(error.code, "invalid_state_base");
        assert!(
            error.message.starts_with(&format!("{reason}: ")),
            "expected cursor reason {reason}, got {}",
            error.message
        );
    }

    #[test]
    fn context_admission_is_frozen_into_provider_input_and_lineage() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let project = storage
            .create_project("Native context admission", None, None)
            .expect("project should be created");
        let root = std::env::current_dir().expect("current directory should resolve");
        let grant = storage
            .add_workspace_grant(Some(&project.id), &root)
            .expect("workspace grant should be created");
        let (_grant_project_id, grant_updated_at_ms, canonical_path_hash) = storage
            .workspace_grant_scope_for_read(&grant.id)
            .expect("grant scope should resolve");
        let conversation = storage
            .create_conversation(Some(&project.id), Some("Admission test"))
            .expect("conversation should be created");
        let provider = create_test_provider(&storage, "Admission provider");
        let run_id = "run_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        let attempt_id = "attempt_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        let user_message_id = "message_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        let assistant_message_id = "message_bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
        let content = "retrieved native context";
        let content_sha256 = sha256_hex(content.as_bytes());
        let context = ContextAdmissionDraft {
            grant_id: grant.id.clone(),
            grant_updated_at_ms,
            canonical_path_hash,
            query_sha256: sha256_hex(b"native context"),
            index_snapshot_id: "workspace_index_snapshot_test".to_owned(),
            index_snapshot_sha256: "a".repeat(64),
            indexer_version: "workspace-text-v1".to_owned(),
            scorer_version: "workspace-lexical-mmr-v1".to_owned(),
            token_budget: 100,
            consumed_tokens: 8,
            selected: vec![ContextAdmissionItem {
                chunk_id: "chunk_test_1".to_owned(),
                source_id: "source_test_1".to_owned(),
                relative_path: "notes.md".to_owned(),
                content: content.to_owned(),
                content_sha256,
                token_estimate: 8,
                rank: 1,
                score: 0.9,
                reasons: vec!["query_terms".to_owned()],
            }],
            omitted: Vec::new(),
        };
        storage
            .prepare_conversation_run_with_attachment_drafts_and_context(
                NewConversationRun {
                    conversation_id: &conversation.conversation.id,
                    branch_id: &conversation.conversation.active_branch_id,
                    run_id,
                    attempt_id,
                    user_message_id,
                    assistant_message_id,
                    prompt: "answer using context",
                    provider_profile_id: &provider.id,
                    model_id: "test-model",
                    request_parameters_json: "{}",
                },
                &[],
                Some(context),
            )
            .expect("context admission should prepare");

        let connection = storage.lock().expect("storage lock");
        let frozen_input = load_historical_provider_input_from_connection(
            &connection,
            &ReadProviderAttemptLineageRequest {
                conversation_id: conversation.conversation.id.clone(),
                branch_id: conversation.conversation.active_branch_id.clone(),
                run_id: run_id.to_owned(),
                attempt_id: attempt_id.to_owned(),
            },
        )
        .expect("historical input should load");
        assert_eq!(
            frozen_input.messages[frozen_input.messages.len() - 2].role,
            "developer"
        );
        assert!(frozen_input.messages[frozen_input.messages.len() - 2]
            .content
            .contains(content));
        assert_eq!(
            frozen_input.messages.last().unwrap().content,
            "answer using context"
        );
        let snapshot_state: (String, String) = connection
            .query_row(
                "SELECT state, snapshot_sha256 FROM context_snapshots WHERE run_id = ?1",
                [run_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("context snapshot should exist");
        assert_eq!(snapshot_state.0, "frozen");
        assert_eq!(snapshot_state.1.len(), 64);
        let lineage_context: (Option<String>, Option<String>) = connection
            .query_row(
                "SELECT context_manifest_id, context_manifest_sha256
                 FROM provider_attempt_lineage_facts WHERE run_id = ?1",
                [run_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("lineage context should exist");
        assert!(lineage_context.0.is_some());
        assert_eq!(
            lineage_context.1.as_deref(),
            Some(snapshot_state.1.as_str())
        );
    }

    #[test]
    fn provider_catalog_snapshot_is_durable_and_bound_to_prepared_lineage() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Catalog lineage provider");
        let models_json = r#"[{"id":"prepared-model","displayName":"Prepared model","capabilities":{"streaming":true,"source":"live"}}]"#;
        let snapshot_sha256 = sha256_hex(models_json.as_bytes());
        let snapshot_id = format!("catalog_snapshot_{}", &snapshot_sha256[..32]);
        storage
            .persist_provider_catalog_snapshot(
                &provider.id,
                &snapshot_id,
                &snapshot_sha256,
                models_json,
                now_ms(),
            )
            .expect("catalog snapshot should persist");
        storage
            .persist_provider_catalog_snapshot(
                &provider.id,
                &snapshot_id,
                &snapshot_sha256,
                models_json,
                now_ms() + 1,
            )
            .expect("identical catalog snapshot should be idempotent");

        let (_conversation_id, prepared) =
            prepare_test_run(&storage, &provider.id, 'e', "Catalog lineage request");
        let lineage: (Option<String>, Option<String>) = storage
            .with_connection(|connection| {
                connection
                    .query_row(
                        "SELECT catalog_snapshot_id, catalog_snapshot_sha256
                         FROM provider_attempt_lineage_facts
                         WHERE frozen_provider_input_id = ?1",
                        [&prepared.provider_input.id],
                        |row| Ok((row.get(0)?, row.get(1)?)),
                    )
                    .map_err(Into::into)
            })
            .expect("catalog lineage should be readable");
        assert_eq!(lineage.0.as_deref(), Some(snapshot_id.as_str()));
        assert_eq!(lineage.1.as_deref(), Some(snapshot_sha256.as_str()));

        let count: i64 = storage
            .with_connection(|connection| {
                connection
                    .query_row(
                        "SELECT COUNT(*) FROM provider_catalog_snapshots
                         WHERE provider_profile_id = ?1",
                        [&provider.id],
                        |row| row.get(0),
                    )
                    .map_err(Into::into)
            })
            .expect("catalog snapshot count should be readable");
        assert_eq!(count, 1, "same content hash must not duplicate snapshots");
    }

    #[test]
    fn provider_catalog_snapshot_rejects_hash_or_json_drift() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Catalog integrity provider");
        let models_json = r#"[{"id":"model-a"}]"#;
        let snapshot_id = "catalog_snapshot_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        let error = storage
            .persist_provider_catalog_snapshot(
                &provider.id,
                snapshot_id,
                &"b".repeat(64),
                models_json,
                now_ms(),
            )
            .expect_err("mismatched catalog hash must fail closed");
        assert_eq!(error.code, "provider_catalog_integrity_failed");
    }

    fn test_run_ids(suffix: char) -> (String, String, String, String) {
        let ids = suffix.to_string().repeat(32);
        let assistant_suffix = match suffix {
            '0'..='5' => char::from_u32(u32::from('a') + u32::from(suffix) - u32::from('0'))
                .expect("hex assistant suffix should exist"),
            '6'..='9' => char::from_u32(u32::from('0') + u32::from(suffix) - u32::from('6'))
                .expect("hex assistant suffix should exist"),
            'a'..='f' => char::from_u32(u32::from('0') + u32::from(suffix) - u32::from('a'))
                .expect("hex assistant suffix should exist"),
            _ => panic!("test suffix must be hexadecimal"),
        };
        (
            format!("run_{ids}"),
            format!("attempt_{ids}"),
            format!("message_{ids}"),
            format!("message_{}", assistant_suffix.to_string().repeat(32)),
        )
    }

    fn prepare_branch_run(
        storage: &Storage,
        provider_id: &str,
        conversation_id: &str,
        branch_id: &str,
        suffix: char,
        prompt: &str,
    ) -> NativeResult<PreparedConversationRun<ConversationSnapshot>> {
        prepare_branch_run_with_parameters(
            storage,
            provider_id,
            conversation_id,
            branch_id,
            suffix,
            prompt,
            r#"{"temperature":0.2}"#,
        )
    }

    fn prepare_branch_run_with_parameters(
        storage: &Storage,
        provider_id: &str,
        conversation_id: &str,
        branch_id: &str,
        suffix: char,
        prompt: &str,
        request_parameters_json: &str,
    ) -> NativeResult<PreparedConversationRun<ConversationSnapshot>> {
        let (run_id, attempt_id, user_message_id, assistant_message_id) = test_run_ids(suffix);
        storage.prepare_conversation_run(NewConversationRun {
            conversation_id,
            branch_id,
            run_id: &run_id,
            attempt_id: &attempt_id,
            user_message_id: &user_message_id,
            assistant_message_id: &assistant_message_id,
            prompt,
            provider_profile_id: provider_id,
            model_id: "prepared-model",
            request_parameters_json,
        })
    }

    fn prepare_test_run(
        storage: &Storage,
        provider_id: &str,
        suffix: char,
        prompt: &str,
    ) -> (String, PreparedConversationRun<ConversationSnapshot>) {
        let conversation = storage
            .create_conversation(None, None)
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let prepared = prepare_branch_run(
            storage,
            provider_id,
            &conversation_id,
            &branch_id,
            suffix,
            prompt,
        )
        .expect("run should prepare");
        (conversation_id, prepared)
    }

