    fn state_revision_counts(storage: &Storage, stream_id: &str) -> (i64, i64, i64, i64, i64) {
        storage
            .with_connection(|connection| {
                connection
                    .query_row(
                        "SELECT
                            (SELECT COUNT(*) FROM state_revisions WHERE stream_id = ?1),
                            (SELECT COUNT(*)
                             FROM state_revision_parents parent
                             JOIN state_revisions revision
                               ON revision.id = parent.revision_id
                             WHERE revision.stream_id = ?1),
                            (SELECT COUNT(*)
                             FROM state_revision_edges edge
                             JOIN state_revisions revision
                               ON revision.id = edge.from_revision_id
                             WHERE revision.stream_id = ?1),
                             (SELECT COUNT(*) FROM state_revision_idempotency WHERE stream_id = ?1),
                             (SELECT COUNT(*)
                              FROM state_revision_operation_facts fact
                              JOIN state_revisions revision
                                ON revision.id = fact.revision_id
                              WHERE revision.stream_id = ?1)",
                        [stream_id],
                        |row| {
                            Ok((
                                row.get(0)?,
                                row.get(1)?,
                                row.get(2)?,
                                row.get(3)?,
                                row.get(4)?,
                            ))
                        },
                    )
                    .map_err(NativeError::from)
            })
            .expect("state-revision counts should be readable")
    }

