    fn set_continuation_task_status(storage: &Storage, task_id: &str, status: &str) {
        storage
            .with_transaction(|transaction| {
                transaction.execute(
                    "UPDATE tasks
                     SET status = ?1, updated_at_ms = updated_at_ms + 1
                     WHERE id = ?2",
                    params![status, task_id],
                )?;
                Ok(())
            })
            .expect("continuation task status should update");
    }

    fn mark_continuation_task_deleted(storage: &Storage, task_id: &str) {
        storage
            .with_transaction(|transaction| {
                transaction.execute(
                    "UPDATE tasks
                     SET deleted_at_ms = updated_at_ms + 1,
                         updated_at_ms = updated_at_ms + 1
                     WHERE id = ?1",
                    [task_id],
                )?;
                Ok(())
            })
            .expect("continuation task deletion marker should update");
    }

    /// Inserts the smallest valid native goal graph used by continuation-root
    /// regression tests.  The production root writers are still being wired
    /// behind their public command surface; these fixtures deliberately use
    /// the same SQLite constraints and current-revision ordering as that
    /// writer contract so tests exercise native scope rather than renderer
    /// shortcuts.
    fn insert_goal_root_fixture(
        storage: &Storage,
        conversation_id: &str,
        branch_id: &str,
        state_revision_id: &str,
        suffix: char,
        status: &str,
    ) -> String {
        let id_suffix = suffix.to_string().repeat(32);
        let hash = suffix.to_string().repeat(64);
        let goal_id = format!("goal_{id_suffix}");
        let revision_id = format!("goal_revision_{id_suffix}");
        let now = now_ms();
        storage
            .with_transaction(|transaction| {
                transaction.execute(
                    "INSERT INTO goals (
                        id, profile_id, project_id, conversation_id, branch_id,
                        current_revision_id, state_revision_id, status, title,
                        description, acceptance_criteria_json, roadmap_json,
                        metadata_json, canonical_payload_sha256, created_at_ms,
                        updated_at_ms, deleted_at_ms
                     ) VALUES (
                        ?1, ?2, NULL, ?3, ?4, NULL, ?5, ?6, ?7, ?8,
                        '[]', '{}', '{}', ?9, ?10, ?10, NULL
                     )",
                    params![
                        goal_id,
                        DEFAULT_PROFILE_ID,
                        conversation_id,
                        branch_id,
                        state_revision_id,
                        status,
                        format!("Goal fixture {suffix}"),
                        format!("Goal fixture description {suffix}"),
                        hash,
                        now,
                    ],
                )?;
                transaction.execute(
                    "INSERT INTO goal_revisions (
                        revision_id, goal_id, revision_no, payload_json,
                        content_sha256, state_revision_id, created_at_ms
                     ) VALUES (?1, ?2, 1, ?3, ?4, ?5, ?6)",
                    params![
                        revision_id,
                        goal_id,
                        format!(r#"{{"title":"Goal fixture {suffix}"}}"#),
                        hash,
                        state_revision_id,
                        now,
                    ],
                )?;
                transaction.execute(
                    "UPDATE goals
                     SET current_revision_id = ?1, updated_at_ms = ?2
                     WHERE id = ?3",
                    params![revision_id, now, goal_id],
                )?;
                Ok(())
            })
            .expect("goal fixture should satisfy native schema guards");
        goal_id
    }

