    #[test]
    fn native_historical_revision_replay_preserves_immutable_revision_and_live_head() {
        let goal_storage = Storage::in_memory().expect("Goal storage should initialize");
        let goal = goal_storage
            .create_goal(valid_goal_request(
                "immutable-replay-goal-create",
                "Immutable replay Goal",
                "draft",
            ))
            .expect("Goal should be created");
        let goal_a_request = goal_revision_request(
            &goal.goal.id,
            "immutable-replay-goal-a",
            "Goal revision A",
            "draft",
            None,
        );
        let goal_a = goal_storage
            .create_goal_revision(goal_a_request.clone())
            .expect("Goal revision A should be created");
        let goal_a_before = goal_storage
            .read_goal_revision(ReadGoalRevisionRequest {
                goal_id: goal.goal.id.clone(),
                revision_id: goal_a.current_revision.revision_id.clone(),
            })
            .expect("Goal revision A should be readable before replay");
        let goal_b = goal_storage
            .create_goal_revision(goal_revision_request(
                &goal.goal.id,
                "immutable-replay-goal-b",
                "Goal revision B",
                "draft",
                None,
            ))
            .expect("Goal revision B should be created");
        let goal_counts_before_replay = goal_counts(&goal_storage);
        let goal_replay = goal_storage
            .create_goal_revision(goal_a_request)
            .expect("historical Goal replay should succeed");
        assert!(goal_replay.replayed);
        assert_eq!(
            goal_replay.current_revision.revision_id,
            goal_b.current_revision.revision_id
        );
        assert_eq!(
            goal_replay
                .selected_revision
                .as_ref()
                .expect("Goal replay should select A")
                .revision_id,
            goal_a.current_revision.revision_id
        );
        assert_eq!(goal_counts(&goal_storage), goal_counts_before_replay);
        let goal_a_after = goal_storage
            .read_goal_revision(ReadGoalRevisionRequest {
                goal_id: goal.goal.id.clone(),
                revision_id: goal_a.current_revision.revision_id.clone(),
            })
            .expect("Goal revision A should be readable after replay");
        assert_goal_revision_immutable(&goal_a_before, &goal_a_after);
        let goal_live = goal_storage
            .read_goal(ReadGoalRequest {
                goal_id: goal.goal.id.clone(),
            })
            .expect("Goal projection should remain readable after replay");
        assert_eq!(
            goal_live.current_revision.revision_id,
            goal_b.current_revision.revision_id
        );

        let task_storage = Storage::in_memory().expect("Task storage should initialize");
        let task_goal = task_storage
            .create_goal(valid_goal_request(
                "immutable-replay-task-goal",
                "Immutable replay Task Goal",
                "draft",
            ))
            .expect("Task fixture Goal should be created");
        let task = task_storage
            .create_task(valid_task_request(
                &task_goal,
                "immutable-replay-task-create",
                "Immutable replay Task",
                "pending",
            ))
            .expect("Task should be created");
        let task_a_request = task_revision_request(
            &task.task.id,
            "immutable-replay-task-a",
            "Task revision A",
            "ready",
            None,
        );
        let task_a = task_storage
            .create_task_revision(task_a_request.clone())
            .expect("Task revision A should be created");
        let task_a_before = task_storage
            .read_task_revision(ReadTaskRevisionRequest {
                task_id: task.task.id.clone(),
                revision_id: task_a.current_revision.revision_id.clone(),
            })
            .expect("Task revision A should be readable before replay");
        let task_b = task_storage
            .create_task_revision(task_revision_request(
                &task.task.id,
                "immutable-replay-task-b",
                "Task revision B",
                "in_progress",
                None,
            ))
            .expect("Task revision B should be created");
        let task_counts_before_replay = task_counts(&task_storage);
        let task_replay = task_storage
            .create_task_revision(task_a_request)
            .expect("historical Task replay should succeed");
        assert!(task_replay.replayed);
        assert_eq!(
            task_replay.current_revision.revision_id,
            task_b.current_revision.revision_id
        );
        assert_eq!(
            task_replay
                .selected_revision
                .as_ref()
                .expect("Task replay should select A")
                .revision_id,
            task_a.current_revision.revision_id
        );
        assert_eq!(task_counts(&task_storage), task_counts_before_replay);
        let task_a_after = task_storage
            .read_task_revision(ReadTaskRevisionRequest {
                task_id: task.task.id.clone(),
                revision_id: task_a.current_revision.revision_id.clone(),
            })
            .expect("Task revision A should be readable after replay");
        assert_task_revision_immutable(&task_a_before, &task_a_after);
        let task_live = task_storage
            .read_task(ReadTaskRequest {
                task_id: task.task.id.clone(),
            })
            .expect("Task projection should remain readable after replay");
        assert_eq!(
            task_live.current_revision.revision_id,
            task_b.current_revision.revision_id
        );

        let workflow_storage = Storage::in_memory().expect("workflow storage should initialize");
        let workflow = workflow_storage
            .create_starter_workflow(valid_starter_workflow_request(
                "immutable-replay-workflow-create",
                "Immutable replay Workflow",
                "draft",
                false,
                r#"{"steps":[{"id":"immutable-replay-one","kind":"message"}]}"#,
            ))
            .expect("Starter Workflow should be created");
        let workflow_a_request = starter_workflow_revision_request(
            &workflow.workflow.id,
            "immutable-replay-workflow-a",
            r#"{"steps":[{"id":"immutable-replay-two","kind":"message"}]}"#,
        );
        let workflow_a = workflow_storage
            .create_starter_workflow_revision(workflow_a_request.clone())
            .expect("workflow revision A should be created");
        let workflow_a_before = workflow_storage
            .read_starter_workflow_revision(ReadStarterWorkflowRevisionRequest {
                starter_workflow_id: workflow.workflow.id.clone(),
                revision_id: workflow_a.current_revision.revision_id.clone(),
            })
            .expect("workflow revision A should be readable before replay");
        let workflow_b = workflow_storage
            .create_starter_workflow_revision(starter_workflow_revision_request(
                &workflow.workflow.id,
                "immutable-replay-workflow-b",
                r#"{"steps":[{"id":"immutable-replay-three","kind":"message"}]}"#,
            ))
            .expect("workflow revision B should be created");
        let workflow_counts_before_replay = starter_workflow_counts(&workflow_storage);
        let workflow_replay = workflow_storage
            .create_starter_workflow_revision(workflow_a_request)
            .expect("historical workflow replay should succeed");
        assert!(workflow_replay.replayed);
        assert_eq!(
            workflow_replay.current_revision.revision_id,
            workflow_b.current_revision.revision_id
        );
        assert_eq!(
            workflow_replay
                .selected_revision
                .as_ref()
                .expect("workflow replay should select A")
                .revision_id,
            workflow_a.current_revision.revision_id
        );
        assert_eq!(
            starter_workflow_counts(&workflow_storage),
            workflow_counts_before_replay
        );
        let workflow_a_after = workflow_storage
            .read_starter_workflow_revision(ReadStarterWorkflowRevisionRequest {
                starter_workflow_id: workflow.workflow.id.clone(),
                revision_id: workflow_a.current_revision.revision_id.clone(),
            })
            .expect("workflow revision A should be readable after replay");
        assert_workflow_revision_immutable(&workflow_a_before, &workflow_a_after);
        let workflow_live = workflow_storage
            .read_starter_workflow(ReadStarterWorkflowRequest {
                starter_workflow_id: workflow.workflow.id.clone(),
            })
            .expect("workflow projection should remain readable after replay");
        assert_eq!(
            workflow_live.current_revision.revision_id,
            workflow_b.current_revision.revision_id
        );
    }

    #[test]
    fn native_goal_revision_cas_is_stale_safe_and_historical_replay_preserves_selection() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let created = storage
            .create_goal(valid_goal_request(
                "goal-cas-create",
                "Initial Goal",
                "draft",
            ))
            .expect("Goal should be created");

        let mut first_request = goal_revision_request(
            &created.goal.id,
            "goal-cas-first",
            "First CAS revision",
            "draft",
            None,
        );
        first_request.expected_current_revision_id =
            Some(created.current_revision.revision_id.clone());
        let first = storage
            .create_goal_revision(first_request.clone())
            .expect("matching Goal revision head should succeed");
        assert_eq!(first.current_revision.revision_no, 2);

        let before_stale = goal_counts(&storage);
        let mut stale_request = goal_revision_request(
            &created.goal.id,
            "goal-cas-stale",
            "Stale CAS revision",
            "draft",
            None,
        );
        stale_request.expected_current_revision_id =
            Some(created.current_revision.revision_id.clone());
        let stale = storage
            .create_goal_revision(stale_request)
            .expect_err("stale Goal revision head must be rejected");
        assert_eq!(stale.code, "stale_revision_head");
        assert_eq!(goal_counts(&storage), before_stale);
        let after_stale = storage
            .read_goal(ReadGoalRequest {
                goal_id: created.goal.id.clone(),
            })
            .expect("Goal should remain readable after stale CAS");
        assert_eq!(
            after_stale.current_revision.revision_id,
            first.current_revision.revision_id
        );

        let mut second_request = goal_revision_request(
            &created.goal.id,
            "goal-cas-second",
            "Second CAS revision",
            "draft",
            None,
        );
        second_request.expected_current_revision_id =
            Some(first.current_revision.revision_id.clone());
        let second = storage
            .create_goal_revision(second_request)
            .expect("the current Goal revision head should satisfy CAS");
        assert_eq!(second.current_revision.revision_no, 3);

        let replay = storage
            .create_goal_revision(first_request.clone())
            .expect("exact Goal revision replay should remain valid after a later revision");
        assert!(replay.replayed);
        assert_eq!(
            replay.current_revision.revision_id,
            second.current_revision.revision_id
        );
        assert_eq!(
            replay
                .selected_revision
                .as_ref()
                .expect("replay should expose the historical selected revision")
                .revision_id,
            first.current_revision.revision_id
        );

        let mut expected_head_drift = first_request;
        expected_head_drift.expected_current_revision_id =
            Some(second.current_revision.revision_id.clone());
        let drift = storage
            .create_goal_revision(expected_head_drift)
            .expect_err("changing only the CAS precondition must report payload drift");
        assert_eq!(drift.code, "payload_drift");
        assert_eq!(goal_counts(&storage), (1, 3, 3));

        let no_head = storage
            .create_goal_revision(goal_revision_request(
                &created.goal.id,
                "goal-cas-omitted-head",
                "Omitted CAS revision",
                "draft",
                None,
            ))
            .expect("omitting the optional CAS head remains backward compatible");
        assert_eq!(no_head.current_revision.revision_no, 4);

        let mut invalid_prefix = goal_revision_request(
            &created.goal.id,
            "goal-cas-invalid-prefix",
            "Invalid prefix revision",
            "draft",
            None,
        );
        invalid_prefix.expected_current_revision_id =
            Some(format!("task_revision_{}", "a".repeat(32)));
        let invalid = storage
            .create_goal_revision(invalid_prefix)
            .expect_err("a Task revision identifier cannot be a Goal CAS head");
        assert_eq!(invalid.code, "invalid_input");
        assert_eq!(goal_counts(&storage), (1, 4, 4));

        let legacy_storage =
            Storage::in_memory().expect("legacy fixture storage should initialize");
        let legacy_goal = legacy_storage
            .create_goal(valid_goal_request(
                "goal-cas-legacy-create",
                "Legacy Goal",
                "draft",
            ))
            .expect("legacy Goal should be created");
        let legacy_request = goal_revision_request(
            &legacy_goal.goal.id,
            "goal-cas-legacy-revision",
            "Legacy revision",
            "draft",
            None,
        );
        legacy_storage
            .create_goal_revision(legacy_request.clone())
            .expect("legacy four-field receipt should be created");
        let mut legacy_replay_with_head = legacy_request;
        legacy_replay_with_head.expected_current_revision_id =
            Some(legacy_goal.current_revision.revision_id);
        let legacy_error = legacy_storage
            .create_goal_revision(legacy_replay_with_head)
            .expect_err("a CAS request must not replay a legacy receipt without a CAS scope");
        assert_eq!(legacy_error.code, "payload_drift");
        assert_eq!(goal_counts(&legacy_storage), (1, 2, 2));
    }

