    #[test]
    fn native_starter_workflow_create_and_revision_replay_remain_historical_safe() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let definition_one = r#"{"steps":[{"id":"step-one","kind":"message"}]}"#;
        let definition_two = r#"{"steps":[{"id":"step-two","kind":"message"}]}"#;
        let definition_three = r#"{"steps":[{"id":"step-three","kind":"message"}]}"#;
        let create_request = valid_starter_workflow_request(
            "starter-workflow-create-replay",
            "Native Starter Workflow",
            "draft",
            false,
            definition_one,
        );

        let created = storage
            .create_starter_workflow(create_request.clone())
            .expect("Starter Workflow should be created");
        assert!(created.workflow.id.starts_with("starter_workflow_"));
        assert!(created
            .current_revision
            .revision_id
            .starts_with("starter_workflow_revision_"));
        assert_eq!(created.current_revision.revision_no, 1);
        assert!(created.selected_revision.is_none());
        assert_eq!(created.execution_disposition, "preview-only");
        assert_eq!(created.integrity, "valid");
        assert!(!created.replayed);

        let create_replay = storage
            .create_starter_workflow(create_request)
            .expect("exact Starter Workflow replay should succeed");
        assert!(create_replay.replayed);
        assert_eq!(create_replay.workflow.id, created.workflow.id);
        assert_eq!(create_replay.current_revision.revision_no, 1);
        assert_eq!(starter_workflow_counts(&storage), (1, 1, 1));
        assert_eq!(
            create_replay
                .selected_revision
                .as_ref()
                .expect("create replay should expose the receipt-selected revision")
                .revision_id,
            created.current_revision.revision_id
        );

        let revision_two = storage
            .create_starter_workflow_revision(starter_workflow_revision_request(
                &created.workflow.id,
                "starter-workflow-revision-two",
                definition_two,
            ))
            .expect("second Starter Workflow revision should succeed");
        assert_eq!(revision_two.current_revision.revision_no, 2);
        assert!(revision_two.selected_revision.is_none());

        let revision_two_replay = storage
            .create_starter_workflow_revision(starter_workflow_revision_request(
                &created.workflow.id,
                "starter-workflow-revision-two",
                definition_two,
            ))
            .expect("exact Starter Workflow revision replay should succeed");
        assert!(revision_two_replay.replayed);
        assert_eq!(
            revision_two_replay.current_revision.revision_id,
            revision_two.current_revision.revision_id
        );
        assert_eq!(
            revision_two_replay
                .selected_revision
                .as_ref()
                .expect("revision replay should expose the receipt-selected revision")
                .revision_id,
            revision_two.current_revision.revision_id
        );

        let revision_three = storage
            .create_starter_workflow_revision(starter_workflow_revision_request(
                &created.workflow.id,
                "starter-workflow-revision-three",
                definition_three,
            ))
            .expect("third Starter Workflow revision should succeed");
        assert_eq!(revision_three.current_revision.revision_no, 3);

        let historical_revision_replay = storage
            .create_starter_workflow_revision(starter_workflow_revision_request(
                &created.workflow.id,
                "starter-workflow-revision-two",
                definition_two,
            ))
            .expect("historical Starter Workflow revision replay should succeed");
        assert!(historical_revision_replay.replayed);
        assert_eq!(
            historical_revision_replay.current_revision.revision_id,
            revision_three.current_revision.revision_id
        );
        let selected = historical_revision_replay
            .selected_revision
            .as_ref()
            .expect("historical revision replay should expose its selected revision");
        assert_eq!(
            selected.revision_id,
            revision_two.current_revision.revision_id
        );
        assert_eq!(selected.revision_no, 2);
        assert_eq!(
            selected.definition_json,
            revision_two.current_revision.definition_json
        );
        assert_eq!(starter_workflow_counts(&storage), (1, 3, 3));

        let historical_create_replay = storage
            .create_starter_workflow(valid_starter_workflow_request(
                "starter-workflow-create-replay",
                "Native Starter Workflow",
                "draft",
                false,
                definition_one,
            ))
            .expect("historical create replay should succeed after later revisions");
        assert!(historical_create_replay.replayed);
        assert_eq!(
            historical_create_replay.current_revision.revision_id,
            revision_three.current_revision.revision_id
        );
        assert_eq!(
            historical_create_replay
                .selected_revision
                .as_ref()
                .expect("historical create replay should expose its selected revision")
                .revision_id,
            created.current_revision.revision_id
        );
    }

    #[test]
    fn native_starter_workflow_status_and_enabled_replays_use_receipt_values_after_later_mutations()
    {
        let storage = Storage::in_memory().expect("storage should initialize");
        let created = storage
            .create_starter_workflow(valid_starter_workflow_request(
                "starter-workflow-status-create",
                "Lifecycle Starter Workflow",
                "draft",
                false,
                r#"{"steps":[{"id":"lifecycle-one","kind":"message"}]}"#,
            ))
            .expect("Starter Workflow should be created");

        let activate_request = UpdateStarterWorkflowStatusRequest {
            starter_workflow_id: created.workflow.id.clone(),
            status: "active".to_owned(),
            enabled: None,
            expected_updated_at_ms: Some(created.workflow.updated_at_ms),
            idempotency_key: "starter-workflow-status-active".to_owned(),
        };
        let active = storage
            .update_starter_workflow_status(activate_request.clone())
            .expect("draft to active should succeed");
        assert_eq!(active.workflow.status, "active");
        assert!(!active.workflow.enabled);
        assert_eq!(active.current_revision.revision_no, 2);
        let active_receipt = test_mutation_receipt(
            &storage,
            "starter-workflow-status-active",
            "starter-workflow",
            "starter-workflow.status.update",
        );
        let active_receipt_result: serde_json::Value =
            serde_json::from_str(&active_receipt.result_json)
                .expect("receipt result should decode");
        assert_eq!(
            active_receipt_result
                .get("mutationShape")
                .and_then(serde_json::Value::as_str),
            Some("status-only")
        );
        assert_eq!(
            active_receipt_result
                .get("expectedUpdatedAtMs")
                .and_then(serde_json::Value::as_i64),
            Some(created.workflow.updated_at_ms)
        );

        let status_shape_drift = storage
            .update_starter_workflow_status(UpdateStarterWorkflowStatusRequest {
                starter_workflow_id: created.workflow.id.clone(),
                status: "active".to_owned(),
                enabled: Some(false),
                expected_updated_at_ms: Some(active.workflow.updated_at_ms),
                idempotency_key: "starter-workflow-status-active".to_owned(),
            })
            .expect_err("status-only receipt must not replay as status+enabled");
        assert_eq!(status_shape_drift.code, "payload_drift");
        assert_eq!(starter_workflow_counts(&storage), (1, 2, 2));

        let later_revision = storage
            .create_starter_workflow_revision(starter_workflow_revision_request(
                &created.workflow.id,
                "starter-workflow-status-later-revision",
                r#"{"steps":[{"id":"lifecycle-two","kind":"message"}]}"#,
            ))
            .expect("later active revision should succeed");
        assert_eq!(later_revision.current_revision.revision_no, 3);

        let active_replay = storage
            .update_starter_workflow_status(UpdateStarterWorkflowStatusRequest {
                expected_updated_at_ms: Some(later_revision.workflow.updated_at_ms),
                ..activate_request
            })
            .expect("historical status replay should succeed after a later revision");
        assert!(active_replay.replayed);
        assert_eq!(active_replay.workflow.status, "active");
        assert_eq!(
            active_replay.current_revision.revision_id,
            later_revision.current_revision.revision_id
        );
        assert_eq!(
            active_replay
                .selected_revision
                .as_ref()
                .expect("status replay should expose its selected revision")
                .revision_no,
            2
        );

        let enable_request = UpdateStarterWorkflowEnabledRequest {
            starter_workflow_id: created.workflow.id.clone(),
            enabled: true,
            expected_updated_at_ms: Some(later_revision.workflow.updated_at_ms),
            idempotency_key: "starter-workflow-enabled-on".to_owned(),
        };
        let enabled = storage
            .update_starter_workflow_enabled(enable_request.clone())
            .expect("active Starter Workflow should become enabled");
        assert!(enabled.workflow.enabled);
        assert_eq!(enabled.workflow.status, "active");
        assert_eq!(enabled.current_revision.revision_no, 4);
        let enabled_receipt = test_mutation_receipt(
            &storage,
            "starter-workflow-enabled-on",
            "starter-workflow",
            "starter-workflow.status.update",
        );
        let enabled_receipt_result: serde_json::Value =
            serde_json::from_str(&enabled_receipt.result_json)
                .expect("receipt result should decode");
        assert_eq!(
            enabled_receipt_result
                .get("mutationShape")
                .and_then(serde_json::Value::as_str),
            Some("enabled-only")
        );

        let enabled_shape_drift = storage
            .update_starter_workflow_status(UpdateStarterWorkflowStatusRequest {
                starter_workflow_id: created.workflow.id.clone(),
                status: "active".to_owned(),
                enabled: Some(true),
                expected_updated_at_ms: Some(enabled.workflow.updated_at_ms),
                idempotency_key: "starter-workflow-enabled-on".to_owned(),
            })
            .expect_err("enabled-only receipt must not replay as status+enabled");
        assert_eq!(enabled_shape_drift.code, "payload_drift");
        assert_eq!(starter_workflow_counts(&storage), (1, 4, 4));

        let disabled = storage
            .update_starter_workflow_enabled(UpdateStarterWorkflowEnabledRequest {
                starter_workflow_id: created.workflow.id.clone(),
                enabled: false,
                expected_updated_at_ms: Some(enabled.workflow.updated_at_ms),
                idempotency_key: "starter-workflow-enabled-off".to_owned(),
            })
            .expect("active Starter Workflow should become disabled");
        assert!(!disabled.workflow.enabled);
        assert_eq!(disabled.current_revision.revision_no, 5);

        let archived = storage
            .update_starter_workflow_status(UpdateStarterWorkflowStatusRequest {
                starter_workflow_id: created.workflow.id.clone(),
                status: "archived".to_owned(),
                enabled: None,
                expected_updated_at_ms: Some(disabled.workflow.updated_at_ms),
                idempotency_key: "starter-workflow-status-archived".to_owned(),
            })
            .expect("disabled active Starter Workflow should archive");
        assert_eq!(archived.workflow.status, "archived");
        assert!(!archived.workflow.enabled);
        assert_eq!(archived.current_revision.revision_no, 6);

        let counts_before_lifecycle_drift = starter_workflow_counts(&storage);
        let status_drift = storage
            .update_starter_workflow_status(UpdateStarterWorkflowStatusRequest {
                starter_workflow_id: created.workflow.id.clone(),
                status: "archived".to_owned(),
                enabled: None,
                expected_updated_at_ms: None,
                idempotency_key: "starter-workflow-status-active".to_owned(),
            })
            .expect_err("reusing a status idempotency key with a different value must fail");
        assert_eq!(status_drift.code, "payload_drift");
        assert_eq!(
            starter_workflow_counts(&storage),
            counts_before_lifecycle_drift
        );

        let enabled_drift = storage
            .update_starter_workflow_enabled(UpdateStarterWorkflowEnabledRequest {
                starter_workflow_id: created.workflow.id.clone(),
                enabled: false,
                expected_updated_at_ms: None,
                idempotency_key: "starter-workflow-enabled-on".to_owned(),
            })
            .expect_err("reusing an enabled idempotency key with a different value must fail");
        assert_eq!(enabled_drift.code, "payload_drift");
        assert_eq!(
            starter_workflow_counts(&storage),
            counts_before_lifecycle_drift
        );

        let enabled_replay = storage
            .update_starter_workflow_enabled(UpdateStarterWorkflowEnabledRequest {
                expected_updated_at_ms: Some(archived.workflow.updated_at_ms),
                ..enable_request
            })
            .expect("historical enabled replay should succeed after later lifecycle mutations");
        assert!(enabled_replay.replayed);
        assert_eq!(enabled_replay.workflow.status, "archived");
        assert!(!enabled_replay.workflow.enabled);
        assert_eq!(
            enabled_replay.current_revision.revision_id,
            archived.current_revision.revision_id
        );
        assert_eq!(
            enabled_replay
                .selected_revision
                .as_ref()
                .expect("enabled replay should expose its selected revision")
                .revision_no,
            4
        );
        assert_eq!(starter_workflow_counts(&storage), (1, 6, 6));
    }

    #[test]
    fn native_starter_workflow_reads_and_replays_fail_closed_when_root_revision_or_receipt_is_tampered(
    ) {
        let root_storage = Storage::in_memory().expect("storage should initialize");
        let root_created = root_storage
            .create_starter_workflow(valid_starter_workflow_request(
                "starter-workflow-tamper-root",
                "Tamper root",
                "draft",
                false,
                r#"{"steps":[{"id":"tamper-root","kind":"message"}]}"#,
            ))
            .expect("Starter Workflow should be created");
        root_storage
            .with_transaction(|transaction| {
                transaction.execute(
                    "UPDATE starter_workflows SET canonical_payload_sha256 = ?1 WHERE id = ?2",
                    params!["0".repeat(64), root_created.workflow.id],
                )?;
                Ok(())
            })
            .expect("test-only root tampering should execute");
        let root_error = root_storage
            .read_starter_workflow(ReadStarterWorkflowRequest {
                starter_workflow_id: root_created.workflow.id,
            })
            .expect_err("tampered Starter Workflow projection must fail closed");
        assert_eq!(root_error.code, "starter_workflow_integrity_failed");

        let revision_storage = Storage::in_memory().expect("storage should initialize");
        let revision_created = revision_storage
            .create_starter_workflow(valid_starter_workflow_request(
                "starter-workflow-tamper-revision",
                "Tamper revision",
                "draft",
                false,
                r#"{"steps":[{"id":"tamper-revision","kind":"message"}]}"#,
            ))
            .expect("Starter Workflow should be created");
        revision_storage
            .with_transaction(|transaction| {
                transaction.execute_batch("DROP TRIGGER starter_workflow_revisions_immutable_update")?;
                transaction.execute(
                    "UPDATE starter_workflow_revisions SET content_sha256 = ?1 WHERE revision_id = ?2",
                    params!["f".repeat(64), revision_created.current_revision.revision_id],
                )?;
                Ok(())
            })
            .expect("test-only revision tampering should execute");
        let revision_error = revision_storage
            .read_starter_workflow(ReadStarterWorkflowRequest {
                starter_workflow_id: revision_created.workflow.id,
            })
            .expect_err("tampered immutable Starter Workflow revision must fail closed");
        assert_eq!(revision_error.code, "starter_workflow_integrity_failed");

        let receipt_storage = Storage::in_memory().expect("storage should initialize");
        let receipt_request = valid_starter_workflow_request(
            "starter-workflow-tamper-receipt",
            "Tamper receipt",
            "draft",
            false,
            r#"{"steps":[{"id":"tamper-receipt","kind":"message"}]}"#,
        );
        let receipt_created = receipt_storage
            .create_starter_workflow(receipt_request.clone())
            .expect("Starter Workflow should be created");
        receipt_storage
            .with_transaction(|transaction| {
                transaction
                    .execute_batch("DROP TRIGGER authoritative_root_receipts_immutable_update")?;
                transaction.execute(
                    "UPDATE authoritative_root_mutation_receipts
                     SET result_json = ?1
                     WHERE profile_id = ?2
                       AND idempotency_key_hash = ?3
                       AND root_kind = 'starter-workflow'",
                    params![
                        "{}",
                        DEFAULT_PROFILE_ID,
                        sha256_hex(b"starter-workflow-tamper-receipt"),
                    ],
                )?;
                Ok(())
            })
            .expect("test-only receipt tampering should execute");
        let receipt_error = receipt_storage
            .create_starter_workflow(receipt_request)
            .expect_err("tampered immutable Starter Workflow receipt must fail closed");
        assert_eq!(receipt_error.code, "root_integrity_failed");
        assert_eq!(receipt_created.workflow.status, "draft");
    }

    #[test]
    fn native_goal_create_read_list_and_exact_replay_are_idempotent() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let request = valid_goal_request("goal-create-replay", "Native Goal", "draft");

        let created = storage
            .create_goal(request.clone())
            .expect("Goal should be created");
        assert!(created.goal.id.starts_with("goal_"));
        assert!(created
            .current_revision
            .revision_id
            .starts_with("goal_revision_"));
        assert_eq!(created.current_revision.revision_no, 1);
        assert_eq!(
            created
                .selected_revision
                .as_ref()
                .map(|row| row.revision_id.as_str()),
            Some(created.current_revision.revision_id.as_str())
        );
        assert_eq!(created.execution_disposition, "preview-only");
        assert_eq!(created.integrity, "valid");
        assert!(!created.replayed);

        let replay = storage
            .create_goal(request)
            .expect("exact Goal replay should succeed");
        assert!(replay.replayed);
        assert_eq!(replay.goal.id, created.goal.id);
        assert_eq!(
            replay.current_revision.revision_id,
            created.current_revision.revision_id
        );
        let replay_selected = replay
            .selected_revision
            .as_ref()
            .expect("replay should select the receipt revision");
        let created_selected = created
            .selected_revision
            .as_ref()
            .expect("create should select its first revision");
        assert_eq!(replay_selected.revision_id, created_selected.revision_id);
        assert_eq!(replay_selected.goal_id, created_selected.goal_id);
        assert_eq!(replay_selected.revision_no, created_selected.revision_no);
        assert_eq!(replay_selected.payload_json, created_selected.payload_json);
        assert_eq!(
            replay_selected.content_sha256,
            created_selected.content_sha256
        );
        assert_eq!(
            replay_selected.state_revision_id,
            created_selected.state_revision_id
        );
        assert_eq!(
            replay_selected.created_at_ms,
            created_selected.created_at_ms
        );
        assert_eq!(goal_counts(&storage), (1, 1, 1));

        let read = storage
            .read_goal(ReadGoalRequest {
                goal_id: created.goal.id.clone(),
            })
            .expect("Goal should be readable");
        assert!(!read.replayed);
        assert!(read.selected_revision.is_none());
        assert_eq!(
            read.current_revision.revision_id,
            created.current_revision.revision_id
        );
        assert_eq!(
            read.current_revision.goal_id,
            created.current_revision.goal_id
        );
        assert_eq!(
            read.current_revision.revision_no,
            created.current_revision.revision_no
        );
        assert_eq!(
            read.current_revision.payload_json,
            created.current_revision.payload_json
        );
        assert_eq!(
            read.current_revision.content_sha256,
            created.current_revision.content_sha256
        );
        assert_eq!(
            read.current_revision.state_revision_id,
            created.current_revision.state_revision_id
        );
        assert_eq!(
            read.current_revision.created_at_ms,
            created.current_revision.created_at_ms
        );

        let historical = storage
            .read_goal_revision(ReadGoalRevisionRequest {
                goal_id: created.goal.id.clone(),
                revision_id: created.current_revision.revision_id.clone(),
            })
            .expect("first Goal revision should be readable");
        assert_eq!(historical.revision_id, created.current_revision.revision_id);
        assert_eq!(historical.goal_id, created.current_revision.goal_id);
        assert_eq!(historical.revision_no, created.current_revision.revision_no);
        assert_eq!(
            historical.payload_json,
            created.current_revision.payload_json
        );
        assert_eq!(
            historical.content_sha256,
            created.current_revision.content_sha256
        );
        assert_eq!(
            historical.state_revision_id,
            created.current_revision.state_revision_id
        );
        assert_eq!(
            historical.created_at_ms,
            created.current_revision.created_at_ms
        );

        let listed = storage
            .list_goals(ListGoalsRequest {
                project_id: None,
                conversation_id: None,
                branch_id: None,
                status: Some("draft".to_owned()),
                include_archived: None,
                limit: Some(10),
            })
            .expect("Goal should be listed");
        assert_eq!(listed.len(), 1);
        assert_eq!(listed[0].id, created.goal.id);
        assert_eq!(
            listed[0].current_revision_id,
            created.current_revision.revision_id
        );
        assert_eq!(
            listed[0].canonical_payload_sha256,
            created.current_revision.content_sha256
        );
    }

    #[test]
    fn native_goal_create_rejects_payload_drift_without_partial_rows() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let request = valid_goal_request("goal-create-drift", "Original title", "draft");
        let created = storage
            .create_goal(request.clone())
            .expect("Goal should be created");
        let mut drifted = request;
        drifted.title = "Changed title".to_owned();

        let error = storage
            .create_goal(drifted)
            .expect_err("same idempotency key with changed payload must fail");
        assert_eq!(error.code, "payload_drift");
        assert_eq!(goal_counts(&storage), (1, 1, 1));
        let read = storage
            .read_goal(ReadGoalRequest {
                goal_id: created.goal.id,
            })
            .expect("original Goal should remain readable");
        assert_eq!(read.goal.title, "Original title");
    }

    #[test]
    fn native_goal_create_rejects_invalid_json_components_and_oversized_payloads() {
        let cases = [
            ("acceptanceCriteria", r#"{}"#, "must be a JSON array"),
            ("roadmap", r#"[]"#, "must be a JSON object"),
            ("metadata", r#"[]"#, "must be a JSON object"),
        ];
        for (index, (field, value, message)) in cases.into_iter().enumerate() {
            let storage = Storage::in_memory().expect("storage should initialize");
            let mut request =
                valid_goal_request(&format!("goal-invalid-json-{index}"), "Invalid", "draft");
            match field {
                "acceptanceCriteria" => request.acceptance_criteria_json = value.to_owned(),
                "roadmap" => request.roadmap_json = value.to_owned(),
                "metadata" => request.metadata_json = value.to_owned(),
                _ => unreachable!(),
            }
            let error = storage
                .create_goal(request)
                .expect_err("invalid Goal JSON component must fail");
            assert_eq!(error.code, "invalid_input");
            assert!(error.message.contains(message));
            assert_eq!(goal_counts(&storage), (0, 0, 0));
        }

        let storage = Storage::in_memory().expect("storage should initialize");
        let mut oversized = valid_goal_request("goal-oversized", "Oversized", "draft");
        oversized.metadata_json = format!("{{\"blob\":\"{}\"}}", "x".repeat(MAX_GOAL_JSON_BYTES));
        let error = storage
            .create_goal(oversized)
            .expect_err("oversized Goal metadata must fail");
        assert_eq!(error.code, "invalid_input");
        assert_eq!(goal_counts(&storage), (0, 0, 0));
    }

    #[test]
    fn native_goal_scope_requires_matching_project_conversation_branch_and_state_anchor() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let project = storage
            .create_project("Goal scope project", None, None)
            .expect("project should be created");
        let other_project = storage
            .create_project("Other project", None, None)
            .expect("second project should be created");
        let conversation = storage
            .create_conversation(Some(&project.id), Some("Goal scope conversation"))
            .expect("conversation should be created");
        let other_conversation = storage
            .create_conversation(Some(&project.id), Some("Other conversation"))
            .expect("second conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let other_conversation_id = other_conversation.conversation.id.clone();
        let other_branch_id = other_conversation.conversation.active_branch_id.clone();

        let mut valid = valid_goal_request("goal-scope-valid", "Scoped Goal", "draft");
        valid.project_id = Some(project.id.clone());
        valid.conversation_id = Some(conversation_id.clone());
        valid.branch_id = Some(branch_id.clone());
        let created = storage
            .create_goal(valid)
            .expect("matching Goal scope should succeed");
        assert_eq!(
            created.goal.project_id.as_deref(),
            Some(project.id.as_str())
        );

        let mut wrong_project =
            valid_goal_request("goal-scope-project-drift", "Wrong project", "draft");
        wrong_project.project_id = Some(other_project.id);
        wrong_project.conversation_id = Some(conversation_id.clone());
        wrong_project.branch_id = Some(branch_id.clone());
        assert_eq!(
            storage
                .create_goal(wrong_project)
                .expect_err("cross-project Goal must fail")
                .code,
            "goal_scope_conflict"
        );

        let mut wrong_conversation = valid_goal_request(
            "goal-scope-conversation-drift",
            "Wrong conversation",
            "draft",
        );
        wrong_conversation.project_id = Some(project.id.clone());
        wrong_conversation.conversation_id = Some(other_conversation_id);
        wrong_conversation.branch_id = Some(branch_id.clone());
        assert_eq!(
            storage
                .create_goal(wrong_conversation)
                .expect_err("cross-conversation branch must fail")
                .code,
            "goal_scope_conflict"
        );

        let mut branch_without_conversation = valid_goal_request(
            "goal-scope-branch-without-conversation",
            "Branch only",
            "draft",
        );
        branch_without_conversation.branch_id = Some(branch_id.clone());
        assert_eq!(
            storage
                .create_goal(branch_without_conversation)
                .expect_err("branch without conversation must fail")
                .code,
            "goal_scope_conflict"
        );

        let mut state_without_exact_scope =
            valid_goal_request("goal-scope-state-without-scope", "State only", "draft");
        state_without_exact_scope.state_revision_id = Some("state_revision_missing".to_owned());
        assert_eq!(
            storage
                .create_goal(state_without_exact_scope)
                .expect_err("state anchor without scope must fail")
                .code,
            "goal_scope_conflict"
        );

        let state = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &conversation.conversation.active_branch_id,
                "root",
                "accepted",
                None,
                "goal-scope-state-root",
                Vec::new(),
            ))
            .expect("state root should be appended");
        let state_revision_id = state.revision_id.expect("state revision should exist");
        let mut anchored = valid_goal_request("goal-scope-anchored", "Anchored Goal", "draft");
        anchored.project_id = Some(project.id);
        anchored.conversation_id = Some(conversation_id);
        anchored.branch_id = Some(other_branch_id);
        anchored.state_revision_id = Some(state_revision_id);
        assert_eq!(
            storage
                .create_goal(anchored)
                .expect_err("cross-branch state anchor must fail")
                .code,
            "goal_scope_conflict"
        );

        assert_eq!(goal_counts(&storage), (1, 1, 1));
        assert_eq!(created.goal.branch_id.as_deref(), Some(branch_id.as_str()));
    }

    #[test]
    fn native_goal_revision_create_is_monotonic_canonical_and_historical_replay_is_unmixed() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let created = storage
            .create_goal(valid_goal_request(
                "goal-revision-create",
                "Revision one",
                "draft",
            ))
            .expect("Goal should be created");

        let mut revision_request = goal_revision_request(
            &created.goal.id,
            "goal-revision-two",
            "Revision two",
            "draft",
            None,
        );
        // Renderer requests may be semantically valid JSON without already
        // being canonical.  Native storage owns the canonical form persisted
        // in the immutable revision and content hash.
        let parsed_payload: serde_json::Value =
            serde_json::from_str(&revision_request.payload_json).expect("payload should parse");
        revision_request.payload_json =
            serde_json::to_string_pretty(&parsed_payload).expect("payload should pretty-print");
        let revision_two = storage
            .create_goal_revision(revision_request.clone())
            .expect("same-status content revision should succeed");
        assert_eq!(revision_two.current_revision.revision_no, 2);
        assert_eq!(revision_two.goal.status, "draft");
        assert_eq!(
            revision_two.current_revision.payload_json,
            canonical_goal_payload_json(
                &serde_json::from_str::<CanonicalGoalPayload>(
                    &revision_two.current_revision.payload_json,
                )
                .expect("stored revision should decode")
            )
            .expect("stored revision should remain canonical")
        );
        assert_eq!(
            revision_two.goal.canonical_payload_sha256,
            revision_two.current_revision.content_sha256
        );

        let revision_two_replay = storage
            .create_goal_revision(revision_request)
            .expect("exact revision replay should succeed");
        assert!(revision_two_replay.replayed);
        assert_eq!(
            revision_two_replay.current_revision.revision_id,
            revision_two.current_revision.revision_id
        );
        assert_eq!(
            revision_two_replay
                .selected_revision
                .as_ref()
                .expect("replay should select the immutable revision")
                .revision_id,
            revision_two.current_revision.revision_id
        );
        assert_eq!(goal_counts(&storage), (1, 2, 2));

        let revision_three = storage
            .create_goal_revision(goal_revision_request(
                &created.goal.id,
                "goal-revision-three",
                "Revision three",
                "draft",
                None,
            ))
            .expect("third same-status revision should succeed");
        assert_eq!(revision_three.current_revision.revision_no, 3);
        assert_ne!(
            revision_three.current_revision.revision_id,
            revision_two.current_revision.revision_id
        );

        let historical_replay = storage
            .create_goal_revision(goal_revision_request(
                &created.goal.id,
                "goal-revision-two",
                "Revision two",
                "draft",
                None,
            ))
            .expect("historical revision replay should succeed after later revisions");
        assert!(historical_replay.replayed);
        assert_eq!(
            historical_replay.current_revision.revision_id,
            revision_three.current_revision.revision_id
        );
        let selected = historical_replay
            .selected_revision
            .as_ref()
            .expect("historical replay should expose its selected revision");
        assert_eq!(
            selected.revision_id,
            revision_two.current_revision.revision_id
        );
        assert_eq!(selected.revision_no, 2);
        assert_eq!(historical_replay.goal.title, "Revision three");
        assert_eq!(
            selected.payload_json,
            revision_two.current_revision.payload_json
        );
        assert_eq!(goal_counts(&storage), (1, 3, 3));
    }

    #[test]
    fn native_goal_revision_cas_rejects_stale_heads_and_replays_exact_preconditions() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let created = storage
            .create_goal(valid_goal_request(
                "goal-revision-cas-create",
                "CAS Goal",
                "draft",
            ))
            .expect("Goal should be created");
        let initial_head = created.current_revision.revision_id.clone();
        let cas_request = goal_revision_request_with_expected(
            &created.goal.id,
            "goal-revision-cas-one",
            "CAS revision one",
            "draft",
            None,
            Some(&initial_head),
        );
        let first = storage
            .create_goal_revision(cas_request.clone())
            .expect("matching Goal revision head should succeed");
        assert!(!first.replayed);
        assert_eq!(first.current_revision.revision_no, 2);
        assert_eq!(goal_counts(&storage), (1, 2, 2));

        let stale = storage
            .create_goal_revision(goal_revision_request_with_expected(
                &created.goal.id,
                "goal-revision-cas-stale",
                "CAS stale writer",
                "draft",
                None,
                Some(&initial_head),
            ))
            .expect_err("stale Goal revision head must fail");
        assert_eq!(stale.code, "stale_revision_head");
        assert_eq!(goal_counts(&storage), (1, 2, 2));
        let after_stale = storage
            .read_goal(ReadGoalRequest {
                goal_id: created.goal.id.clone(),
            })
            .expect("Goal should remain readable after stale CAS rejection");
        assert_eq!(
            after_stale.current_revision.revision_id,
            first.current_revision.revision_id
        );

        let later = storage
            .create_goal_revision(goal_revision_request(
                &created.goal.id,
                "goal-revision-cas-later",
                "CAS revision later",
                "draft",
                None,
            ))
            .expect("later Goal revision should succeed");
        let replay = storage
            .create_goal_revision(cas_request.clone())
            .expect("exact CAS replay should remain valid after a later revision");
        assert!(replay.replayed);
        assert_eq!(
            replay.current_revision.revision_id,
            later.current_revision.revision_id
        );
        assert_eq!(
            replay
                .selected_revision
                .as_ref()
                .expect("CAS replay should expose its receipt-selected revision")
                .revision_id,
            first.current_revision.revision_id
        );

        let mut changed_precondition = cas_request;
        changed_precondition.expected_current_revision_id =
            Some(later.current_revision.revision_id.clone());
        let drift = storage
            .create_goal_revision(changed_precondition)
            .expect_err("changing only the CAS precondition must be payload drift");
        assert_eq!(drift.code, "payload_drift");
        assert_eq!(goal_counts(&storage), (1, 3, 3));
    }

