    #[test]
    fn native_goal_revision_rejects_invalid_transition_and_payload_drift_atomically() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let created = storage
            .create_goal(valid_goal_request(
                "goal-revision-invalid",
                "Draft goal",
                "draft",
            ))
            .expect("Goal should be created");

        let invalid = storage
            .create_goal_revision(goal_revision_request(
                &created.goal.id,
                "goal-revision-invalid-transition",
                "Completed too early",
                "completed",
                None,
            ))
            .expect_err("draft Goals cannot jump directly to completed");
        assert_eq!(invalid.code, "goal_status_transition_invalid");
        assert_eq!(goal_counts(&storage), (1, 1, 1));

        let active = storage
            .create_goal_revision(goal_revision_request(
                &created.goal.id,
                "goal-revision-active",
                "Active goal",
                "active",
                None,
            ))
            .expect("draft to active should succeed");
        assert_eq!(active.goal.status, "active");
        assert_eq!(active.current_revision.revision_no, 2);
        assert_eq!(goal_counts(&storage), (1, 2, 2));

        let mut drifted = goal_revision_request(
            &created.goal.id,
            "goal-revision-active",
            "Different title",
            "active",
            None,
        );
        let mut drifted_payload: CanonicalGoalPayload =
            serde_json::from_str(&drifted.payload_json).expect("goal payload should deserialize");
        drifted_payload.description = None;
        drifted.payload_json = canonical_goal_payload_json(&drifted_payload)
            .expect("drifted goal payload should canonicalize");
        let drift = storage
            .create_goal_revision(drifted)
            .expect_err("reusing a revision idempotency key with changed payload must fail");
        assert_eq!(drift.code, "payload_drift");
        assert_eq!(goal_counts(&storage), (1, 2, 2));

        let read = storage
            .read_goal(ReadGoalRequest {
                goal_id: created.goal.id,
            })
            .expect("Goal should remain readable after rejected revision");
        assert_eq!(read.goal.status, "active");
        assert_eq!(read.current_revision.revision_no, 2);
    }

    #[test]
    fn native_goal_status_lifecycle_is_exact_and_status_replay_is_historical_safe() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let created = storage
            .create_goal(valid_goal_request(
                "goal-status-lifecycle",
                "Lifecycle goal",
                "draft",
            ))
            .expect("Goal should be created");

        let activate_request = UpdateGoalStatusRequest {
            goal_id: created.goal.id.clone(),
            status: "active".to_owned(),
            expected_updated_at_ms: Some(created.goal.updated_at_ms),
            idempotency_key: "goal-status-active".to_owned(),
        };
        let active = storage
            .update_goal_status(activate_request.clone())
            .expect("draft to active should succeed");
        assert_eq!(active.goal.status, "active");
        assert_eq!(active.current_revision.revision_no, 2);

        let active_replay = storage
            .update_goal_status(activate_request)
            .expect("exact status replay should succeed");
        assert!(active_replay.replayed);
        assert_eq!(active_replay.current_revision.revision_no, 2);
        assert_eq!(
            active_replay
                .selected_revision
                .as_ref()
                .expect("status replay should select its immutable revision")
                .revision_no,
            2
        );

        let stale = storage
            .update_goal_status(UpdateGoalStatusRequest {
                goal_id: created.goal.id.clone(),
                status: "paused".to_owned(),
                expected_updated_at_ms: Some(active.goal.updated_at_ms.saturating_add(1)),
                idempotency_key: "goal-status-stale".to_owned(),
            })
            .expect_err("stale status update must fail before creating a revision");
        assert_eq!(stale.code, "goal_conflict");
        assert_eq!(goal_counts(&storage), (1, 2, 2));

        let paused = storage
            .update_goal_status(UpdateGoalStatusRequest {
                goal_id: created.goal.id.clone(),
                status: "paused".to_owned(),
                expected_updated_at_ms: Some(active.goal.updated_at_ms),
                idempotency_key: "goal-status-paused".to_owned(),
            })
            .expect("active to paused should succeed");
        assert_eq!(paused.goal.status, "paused");

        let resumed = storage
            .update_goal_status(UpdateGoalStatusRequest {
                goal_id: created.goal.id.clone(),
                status: "active".to_owned(),
                expected_updated_at_ms: Some(paused.goal.updated_at_ms),
                idempotency_key: "goal-status-resumed".to_owned(),
            })
            .expect("paused to active should succeed");
        assert_eq!(resumed.goal.status, "active");

        let completed = storage
            .update_goal_status(UpdateGoalStatusRequest {
                goal_id: created.goal.id.clone(),
                status: "completed".to_owned(),
                expected_updated_at_ms: Some(resumed.goal.updated_at_ms),
                idempotency_key: "goal-status-completed".to_owned(),
            })
            .expect("active to completed should succeed");
        assert_eq!(completed.goal.status, "completed");

        let archived = storage
            .update_goal_status(UpdateGoalStatusRequest {
                goal_id: created.goal.id.clone(),
                status: "archived".to_owned(),
                expected_updated_at_ms: Some(completed.goal.updated_at_ms),
                idempotency_key: "goal-status-archived".to_owned(),
            })
            .expect("completed to archived should succeed");
        assert_eq!(archived.goal.status, "archived");
        assert_eq!(goal_counts(&storage), (1, 6, 6));

        let reverse = storage
            .update_goal_status(UpdateGoalStatusRequest {
                goal_id: created.goal.id.clone(),
                status: "active".to_owned(),
                expected_updated_at_ms: Some(archived.goal.updated_at_ms),
                idempotency_key: "goal-status-reverse".to_owned(),
            })
            .expect_err("archived Goals are terminal");
        assert_eq!(reverse.code, "goal_status_transition_invalid");

        let revision_after_terminal = storage
            .create_goal_revision(goal_revision_request(
                &created.goal.id,
                "goal-after-archive",
                "No revision after archive",
                "archived",
                None,
            ))
            .expect_err("archived Goals cannot receive revisions");
        assert_eq!(revision_after_terminal.code, "goal_terminal");

        let historical_replay = storage
            .update_goal_status(UpdateGoalStatusRequest {
                goal_id: created.goal.id,
                status: "active".to_owned(),
                expected_updated_at_ms: Some(archived.goal.updated_at_ms),
                idempotency_key: "goal-status-active".to_owned(),
            })
            .expect("replaying a historical status receipt must remain safe");
        assert!(historical_replay.replayed);
        assert_eq!(historical_replay.goal.status, "archived");
        assert_eq!(
            historical_replay.current_revision.revision_no,
            archived.current_revision.revision_no
        );
        assert_eq!(
            historical_replay
                .selected_revision
                .as_ref()
                .expect("historical status replay should select active revision")
                .revision_no,
            2
        );
    }

    #[test]
    fn native_goal_status_idempotency_is_bound_to_goal_and_payload() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let first = storage
            .create_goal(valid_goal_request(
                "goal-status-drift-first",
                "First",
                "draft",
            ))
            .expect("first Goal should be created");
        let second = storage
            .create_goal(valid_goal_request(
                "goal-status-drift-second",
                "Second",
                "draft",
            ))
            .expect("second Goal should be created");

        storage
            .update_goal_status(UpdateGoalStatusRequest {
                goal_id: first.goal.id.clone(),
                status: "active".to_owned(),
                expected_updated_at_ms: Some(first.goal.updated_at_ms),
                idempotency_key: "goal-status-bound".to_owned(),
            })
            .expect("first status update should succeed");

        let status_drift = storage
            .update_goal_status(UpdateGoalStatusRequest {
                goal_id: first.goal.id.clone(),
                status: "cancelled".to_owned(),
                expected_updated_at_ms: None,
                idempotency_key: "goal-status-bound".to_owned(),
            })
            .expect_err("same status key with a different status must fail");
        assert_eq!(status_drift.code, "payload_drift");

        let goal_drift = storage
            .update_goal_status(UpdateGoalStatusRequest {
                goal_id: second.goal.id,
                status: "active".to_owned(),
                expected_updated_at_ms: Some(second.goal.updated_at_ms),
                idempotency_key: "goal-status-bound".to_owned(),
            })
            .expect_err("same status key cannot be reused for another Goal");
        assert_eq!(goal_drift.code, "payload_drift");
        assert_eq!(goal_counts(&storage), (2, 3, 3));
    }

    #[test]
    fn native_goal_revision_requires_exact_state_anchor_scope_and_rolls_back_on_failure() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let project = storage
            .create_project("Goal revision anchor project", None, None)
            .expect("project should be created");
        let conversation = storage
            .create_conversation(Some(&project.id), Some("Goal revision anchor conversation"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let root = append_current_state_root(
            &storage,
            &conversation_id,
            &branch_id,
            "goal-revision-anchor-root",
        );
        let root_revision_id = root.revision_id.expect("root state revision should exist");

        let mut request =
            valid_goal_request("goal-revision-anchor-create", "Anchored Goal", "draft");
        request.project_id = Some(project.id.clone());
        request.conversation_id = Some(conversation_id.clone());
        request.branch_id = Some(branch_id.clone());
        request.state_revision_id = Some(root_revision_id.clone());
        let created = storage
            .create_goal(request)
            .expect("anchored Goal should be created");

        let next_root = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "continuation",
                "accepted",
                Some(&root_revision_id),
                "goal-revision-anchor-next",
                vec![root_revision_id.clone()],
            ))
            .expect("second state revision should be appended");
        let next_revision_id = next_root
            .revision_id
            .expect("second state revision should exist");

        let anchored_revision = storage
            .create_goal_revision(goal_revision_request(
                &created.goal.id,
                "goal-revision-anchor-valid",
                "Anchored revision",
                "draft",
                Some(&next_revision_id),
            ))
            .expect("revision with the exact branch anchor should succeed");
        assert_eq!(
            anchored_revision.goal.state_revision_id.as_deref(),
            Some(next_revision_id.as_str())
        );
        assert_eq!(
            anchored_revision
                .current_revision
                .state_revision_id
                .as_deref(),
            Some(next_revision_id.as_str())
        );
        assert_eq!(goal_counts(&storage), (1, 2, 2));

        let other_conversation = storage
            .create_conversation(None, Some("Other anchor conversation"))
            .expect("second conversation should be created");
        let other_branch_id = other_conversation.conversation.active_branch_id.clone();
        let other_root = append_current_state_root(
            &storage,
            &other_conversation.conversation.id,
            &other_branch_id,
            "goal-revision-anchor-other-root",
        );
        let other_revision_id = other_root
            .revision_id
            .expect("other state revision should exist");
        let cross_scope = storage
            .create_goal_revision(goal_revision_request(
                &created.goal.id,
                "goal-revision-anchor-cross-scope",
                "Cross scope revision",
                "draft",
                Some(&other_revision_id),
            ))
            .expect_err("revision anchor from another branch must fail");
        assert_eq!(cross_scope.code, "goal_scope_conflict");
        assert_eq!(goal_counts(&storage), (1, 2, 2));
        let read = storage
            .read_goal(ReadGoalRequest {
                goal_id: created.goal.id,
            })
            .expect("Goal should remain unchanged after rejected anchor");
        assert_eq!(read.current_revision.revision_no, 2);
        assert_eq!(
            read.goal.state_revision_id.as_deref(),
            Some(next_revision_id.as_str())
        );
    }

    #[test]
    fn native_goal_reads_fail_closed_when_root_revision_or_receipt_is_tampered() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let created = storage
            .create_goal(valid_goal_request(
                "goal-tamper-root",
                "Tamper root",
                "draft",
            ))
            .expect("Goal should be created");
        storage
            .with_transaction(|transaction| {
                transaction.execute(
                    "UPDATE goals SET canonical_payload_sha256 = ?1 WHERE id = ?2",
                    params!["0".repeat(64), created.goal.id],
                )?;
                Ok(())
            })
            .expect("test-only root tampering should execute");
        let root_error = storage
            .read_goal(ReadGoalRequest {
                goal_id: created.goal.id.clone(),
            })
            .expect_err("tampered root projection must fail closed");
        assert_eq!(root_error.code, "goal_integrity_failed");

        let revision_storage = Storage::in_memory().expect("storage should initialize");
        let revision_created = revision_storage
            .create_goal(valid_goal_request(
                "goal-tamper-revision",
                "Tamper revision",
                "draft",
            ))
            .expect("Goal should be created");
        revision_storage
            .with_transaction(|transaction| {
                transaction.execute_batch("DROP TRIGGER goal_revisions_immutable_update")?;
                transaction.execute(
                    "UPDATE goal_revisions SET content_sha256 = ?1 WHERE revision_id = ?2",
                    params![
                        "f".repeat(64),
                        revision_created.current_revision.revision_id
                    ],
                )?;
                Ok(())
            })
            .expect("test-only revision tampering should execute");
        let revision_error = revision_storage
            .read_goal(ReadGoalRequest {
                goal_id: revision_created.goal.id,
            })
            .expect_err("tampered immutable revision must fail closed");
        assert_eq!(revision_error.code, "goal_integrity_failed");

        let receipt_storage = Storage::in_memory().expect("storage should initialize");
        let receipt_request = valid_goal_request("goal-tamper-receipt", "Tamper receipt", "draft");
        let receipt_created = receipt_storage
            .create_goal(receipt_request.clone())
            .expect("Goal should be created");
        receipt_storage
            .with_transaction(|transaction| {
                transaction
                    .execute_batch("DROP TRIGGER authoritative_root_receipts_immutable_update")?;
                transaction.execute(
                    "UPDATE authoritative_root_mutation_receipts
                     SET result_json = ?1
                     WHERE profile_id = ?2
                       AND idempotency_key_hash = ?3
                       AND root_kind = 'goal'",
                    params!["{}", DEFAULT_PROFILE_ID, sha256_hex(b"goal-tamper-receipt")],
                )?;
                Ok(())
            })
            .expect("test-only receipt tampering should execute");
        let receipt_error = receipt_storage
            .create_goal(receipt_request)
            .expect_err("tampered immutable receipt must fail closed");
        assert_eq!(receipt_error.code, "goal_integrity_failed");
        assert_eq!(receipt_created.goal.status, "draft");
    }

    fn insert_task_root_fixture(
        storage: &Storage,
        conversation_id: &str,
        branch_id: &str,
        state_revision_id: &str,
        goal_id: &str,
        suffix: char,
        status: &str,
    ) -> String {
        let id_suffix = suffix.to_string().repeat(32);
        let hash = suffix.to_string().repeat(64);
        let task_id = format!("task_{id_suffix}");
        let revision_id = format!("task_revision_{id_suffix}");
        let now = now_ms();
        storage
            .with_transaction(|transaction| {
                transaction.execute(
                    "INSERT INTO tasks (
                        id, profile_id, goal_id, project_id, conversation_id,
                        branch_id, current_revision_id, state_revision_id, status,
                        title, description, metadata_json, canonical_payload_sha256,
                        created_at_ms, updated_at_ms, deleted_at_ms
                     ) VALUES (
                        ?1, ?2, ?3, NULL, ?4, ?5, NULL, ?6, ?7, ?8, ?9,
                        '{}', ?10, ?11, ?11, NULL
                     )",
                    params![
                        task_id,
                        DEFAULT_PROFILE_ID,
                        goal_id,
                        conversation_id,
                        branch_id,
                        state_revision_id,
                        status,
                        format!("Task fixture {suffix}"),
                        format!("Task fixture description {suffix}"),
                        hash,
                        now,
                    ],
                )?;
                transaction.execute(
                    "INSERT INTO task_revisions (
                        revision_id, task_id, revision_no, payload_json,
                        content_sha256, state_revision_id, created_at_ms
                     ) VALUES (?1, ?2, 1, ?3, ?4, ?5, ?6)",
                    params![
                        revision_id,
                        task_id,
                        format!(r#"{{"title":"Task fixture {suffix}"}}"#),
                        hash,
                        state_revision_id,
                        now,
                    ],
                )?;
                transaction.execute(
                    "UPDATE tasks
                     SET current_revision_id = ?1, updated_at_ms = ?2
                     WHERE id = ?3",
                    params![revision_id, now, task_id],
                )?;
                Ok(())
            })
            .expect("task fixture should satisfy native schema guards");
        task_id
    }

    fn insert_task_dependency_fixture(
        storage: &Storage,
        suffix: char,
        from_task_id: &str,
        to_task_id: &str,
        dependency_kind: &str,
    ) -> String {
        let dependency_id = format!("task_dependency_{}", suffix.to_string().repeat(32));
        storage
            .with_transaction(|transaction| {
                // The schema only admits dependency edges between live,
                // non-terminal tasks (the insertion guard hardens new writes
                // without rewriting history).  Fixtures that need an edge to an
                // already-terminal task model a later transition: insert the
                // immutable edge while the endpoint is still open, then
                // restore the terminal status.
                let mut restore: Vec<(String, String)> = Vec::new();
                for task_id in [from_task_id, to_task_id] {
                    let status: Option<String> = transaction
                        .query_row("SELECT status FROM tasks WHERE id = ?1", [task_id], |row| {
                            row.get(0)
                        })
                        .optional()?;
                    if let Some(status) = status {
                        if matches!(status.as_str(), "completed" | "cancelled" | "archived") {
                            transaction.execute(
                                "UPDATE tasks SET status = 'ready' WHERE id = ?1",
                                [task_id],
                            )?;
                            restore.push((task_id.to_owned(), status));
                        }
                    }
                }
                transaction.execute(
                    "INSERT INTO task_dependencies (
                        id, profile_id, from_task_id, to_task_id,
                        dependency_kind, created_at_ms
                     ) VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
                    params![
                        dependency_id,
                        DEFAULT_PROFILE_ID,
                        from_task_id,
                        to_task_id,
                        dependency_kind,
                        now_ms(),
                    ],
                )?;
                for (task_id, status) in restore {
                    transaction.execute(
                        "UPDATE tasks SET status = ?1 WHERE id = ?2",
                        params![status, task_id],
                    )?;
                }
                Ok(())
            })
            .expect("task dependency fixture should satisfy native schema guards");
        dependency_id
    }

