    #[test]
    fn continuation_goal_preview_allows_draft_and_paused_but_execute_requires_active() {
        for (suffix, status) in [('a', "draft"), ('b', "paused")] {
            let storage = Storage::in_memory().expect("storage should initialize");
            let conversation = storage
                .create_conversation(None, Some("Continuation goal lifecycle"))
                .expect("conversation should be created");
            let conversation_id = conversation.conversation.id.clone();
            let branch_id = conversation.conversation.active_branch_id.clone();
            let state_revision = append_current_state_root(
                &storage,
                &conversation_id,
                &branch_id,
                &format!("continuation-goal-{suffix}-root"),
            );
            let state_revision_id = state_revision
                .revision_id
                .expect("goal state revision should exist");
            let goal_id = insert_goal_root_fixture(
                &storage,
                &conversation_id,
                &branch_id,
                &state_revision_id,
                suffix,
                status,
            );

            let preview = storage
                .resolve_continuation_intent(continuation_root_request(
                    &conversation_id,
                    &branch_id,
                    &state_revision_id,
                    "goal",
                    &goal_id,
                    "preview",
                    &format!("continuation-goal-{suffix}-preview"),
                ))
                .expect("draft and paused goals remain previewable");
            assert_eq!(preview.root_kind, "goal");
            assert_eq!(preview.root_id, goal_id);
            assert_eq!(preview.execution_mode, "preview");

            let error = storage
                .resolve_continuation_intent(continuation_root_request(
                    &conversation_id,
                    &branch_id,
                    &state_revision_id,
                    "goal",
                    &goal_id,
                    "execute",
                    &format!("continuation-goal-{suffix}-execute"),
                ))
                .expect_err("only active goals may authorize execution");
            assert_eq!(error.code, "continuation_root_not_executable");
        }
    }

