    #[test]
    fn continuation_dependency_integrity_rejects_missing_target_profile_mismatch_and_malformed_id()
    {
        // A restored database may contain a dependency whose target row was
        // lost while the immutable edge survived.  Foreign-key enforcement is
        // disabled only while constructing this test-only damaged fixture;
        // the executable gate must still fail closed when the target lookup
        // returns no row.
        {
            let storage = Storage::in_memory().expect("storage should initialize");
            let conversation = storage
                .create_conversation(None, Some("Continuation missing dependency target"))
                .expect("conversation should be created");
            let conversation_id = conversation.conversation.id.clone();
            let branch_id = conversation.conversation.active_branch_id.clone();
            let state_revision = append_current_state_root(
                &storage,
                &conversation_id,
                &branch_id,
                "continuation-missing-dependency-root",
            );
            let state_revision_id = state_revision
                .revision_id
                .expect("missing-target state revision should exist");
            let goal_id = insert_goal_root_fixture(
                &storage,
                &conversation_id,
                &branch_id,
                &state_revision_id,
                'a',
                "active",
            );
            let source_task_id = insert_task_root_fixture(
                &storage,
                &conversation_id,
                &branch_id,
                &state_revision_id,
                &goal_id,
                'b',
                "ready",
            );
            let missing_target_id = format!("task_{}", "c".repeat(32));
            storage
                .with_connection(|connection| {
                    connection.execute_batch(
                        "PRAGMA foreign_keys = OFF;
                         DROP TRIGGER task_dependencies_scope_guard_insert;",
                    )?;
                    connection.execute(
                        "INSERT INTO task_dependencies (
                            id, profile_id, from_task_id, to_task_id,
                            dependency_kind, created_at_ms
                         ) VALUES (?1, ?2, ?3, ?4, 'blocks', ?5)",
                        params![
                            "task_dependency_cccccccccccccccccccccccccccccccc",
                            DEFAULT_PROFILE_ID,
                            source_task_id,
                            missing_target_id,
                            now_ms(),
                        ],
                    )?;
                    connection.execute_batch("PRAGMA foreign_keys = ON;")?;
                    Ok(())
                })
                .expect("test-only missing-target dependency should insert");

            let error = storage
                .resolve_continuation_intent(continuation_root_request(
                    &conversation_id,
                    &branch_id,
                    &state_revision_id,
                    "task",
                    &source_task_id,
                    "execute",
                    "continuation-missing-dependency-execute",
                ))
                .expect_err("missing dependency targets must fail closed");
            assert_eq!(error.code, "continuation_task_dependency_integrity_failed");
        }

        // A dependency row carrying another profile address is not a
        // non-blocking edge.  It is an integrity violation even when the
        // source and target task rows happen to be otherwise valid.
        {
            let storage = Storage::in_memory().expect("storage should initialize");
            let conversation = storage
                .create_conversation(None, Some("Continuation dependency profile mismatch"))
                .expect("conversation should be created");
            let conversation_id = conversation.conversation.id.clone();
            let branch_id = conversation.conversation.active_branch_id.clone();
            let state_revision = append_current_state_root(
                &storage,
                &conversation_id,
                &branch_id,
                "continuation-profile-mismatch-root",
            );
            let state_revision_id = state_revision
                .revision_id
                .expect("profile-mismatch state revision should exist");
            let goal_id = insert_goal_root_fixture(
                &storage,
                &conversation_id,
                &branch_id,
                &state_revision_id,
                'd',
                "active",
            );
            let source_task_id = insert_task_root_fixture(
                &storage,
                &conversation_id,
                &branch_id,
                &state_revision_id,
                &goal_id,
                'e',
                "ready",
            );
            let target_task_id = insert_task_root_fixture(
                &storage,
                &conversation_id,
                &branch_id,
                &state_revision_id,
                &goal_id,
                'f',
                "completed",
            );
            storage
                .with_transaction(|transaction| {
                    transaction.execute(
                        "INSERT INTO app_profiles (
                            id, display_name, created_at_ms, updated_at_ms, settings_json
                         ) VALUES (?1, ?2, ?3, ?3, '{}')",
                        params![
                            "profile_dependency_other",
                            "Other dependency profile",
                            now_ms()
                        ],
                    )?;
                    Ok(())
                })
                .expect("alternate profile should insert");
            storage
                .with_connection(|connection| {
                    connection
                        .execute_batch("DROP TRIGGER task_dependencies_scope_guard_insert;")?;
                    connection.execute(
                        "INSERT INTO task_dependencies (
                            id, profile_id, from_task_id, to_task_id,
                            dependency_kind, created_at_ms
                         ) VALUES (?1, ?2, ?3, ?4, 'blocks', ?5)",
                        params![
                            "task_dependency_dddddddddddddddddddddddddddddddd",
                            "profile_dependency_other",
                            source_task_id,
                            target_task_id,
                            now_ms(),
                        ],
                    )?;
                    Ok(())
                })
                .expect("test-only profile-mismatch dependency should insert");

            let error = storage
                .resolve_continuation_intent(continuation_root_request(
                    &conversation_id,
                    &branch_id,
                    &state_revision_id,
                    "task",
                    &source_task_id,
                    "execute",
                    "continuation-profile-mismatch-execute",
                ))
                .expect_err("cross-profile dependencies must fail closed");
            assert_eq!(error.code, "continuation_task_dependency_integrity_failed");
        }

        // The schema only requires a dependency identifier to have the
        // task_dependency_ prefix and a bounded length.  Native validation is
        // stricter and rejects non-hex suffixes before evaluating readiness.
        {
            let storage = Storage::in_memory().expect("storage should initialize");
            let conversation = storage
                .create_conversation(None, Some("Continuation malformed dependency id"))
                .expect("conversation should be created");
            let conversation_id = conversation.conversation.id.clone();
            let branch_id = conversation.conversation.active_branch_id.clone();
            let state_revision = append_current_state_root(
                &storage,
                &conversation_id,
                &branch_id,
                "continuation-malformed-dependency-root",
            );
            let state_revision_id = state_revision
                .revision_id
                .expect("malformed-id state revision should exist");
            let goal_id = insert_goal_root_fixture(
                &storage,
                &conversation_id,
                &branch_id,
                &state_revision_id,
                'a',
                "active",
            );
            let source_task_id = insert_task_root_fixture(
                &storage,
                &conversation_id,
                &branch_id,
                &state_revision_id,
                &goal_id,
                'b',
                "ready",
            );
            let target_task_id = insert_task_root_fixture(
                &storage,
                &conversation_id,
                &branch_id,
                &state_revision_id,
                &goal_id,
                'c',
                "completed",
            );
            storage
                .with_connection(|connection| {
                    // New edges to terminal tasks are rejected by the insert
                    // guard, so model a later completion: open the target,
                    // insert the edge, then restore the terminal status.
                    connection.execute(
                        "UPDATE tasks SET status = 'ready' WHERE id = ?1",
                        [&target_task_id],
                    )?;
                    connection.execute(
                        "INSERT INTO task_dependencies (
                            id, profile_id, from_task_id, to_task_id,
                            dependency_kind, created_at_ms
                         ) VALUES (?1, ?2, ?3, ?4, 'blocks', ?5)",
                        params![
                            "task_dependency_gggggggggggggggggggggggggggggggg",
                            DEFAULT_PROFILE_ID,
                            source_task_id,
                            target_task_id,
                            now_ms(),
                        ],
                    )?;
                    connection.execute(
                        "UPDATE tasks SET status = 'completed' WHERE id = ?1",
                        [&target_task_id],
                    )?;
                    Ok(())
                })
                .expect("test-only malformed dependency id should insert");

            let error = storage
                .resolve_continuation_intent(continuation_root_request(
                    &conversation_id,
                    &branch_id,
                    &state_revision_id,
                    "task",
                    &source_task_id,
                    "execute",
                    "continuation-malformed-dependency-id-execute",
                ))
                .expect_err("malformed dependency identifiers must fail closed");
            assert_eq!(error.code, "continuation_task_dependency_integrity_failed");
        }
    }

    #[test]
    fn continuation_task_replay_rechecks_dependency_state_and_remains_idempotent() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("Continuation dependency replay"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let state_revision = append_current_state_root(
            &storage,
            &conversation_id,
            &branch_id,
            "continuation-dependency-replay-root",
        );
        let state_revision_id = state_revision
            .revision_id
            .expect("dependency replay state revision should exist");
        let goal_id = insert_goal_root_fixture(
            &storage,
            &conversation_id,
            &branch_id,
            &state_revision_id,
            'a',
            "active",
        );
        let source_task_id = insert_task_root_fixture(
            &storage,
            &conversation_id,
            &branch_id,
            &state_revision_id,
            &goal_id,
            'b',
            "ready",
        );
        let target_task_id = insert_task_root_fixture(
            &storage,
            &conversation_id,
            &branch_id,
            &state_revision_id,
            &goal_id,
            'c',
            "completed",
        );
        insert_task_dependency_fixture(&storage, 'd', &source_task_id, &target_task_id, "blocks");

        let request = continuation_root_request(
            &conversation_id,
            &branch_id,
            &state_revision_id,
            "task",
            &source_task_id,
            "execute",
            "continuation-dependency-replay-key",
        );
        let first = storage
            .resolve_continuation_intent(request.clone())
            .expect("completed blocking dependency should authorize execution");

        set_continuation_task_status(&storage, &target_task_id, "pending");
        let unresolved = storage
            .resolve_continuation_intent(request.clone())
            .expect_err("replay must re-check dependency readiness");
        assert_eq!(unresolved.code, "continuation_task_dependencies_unresolved");

        set_continuation_task_status(&storage, &target_task_id, "completed");
        let replay = storage
            .resolve_continuation_intent(request)
            .expect("restored dependency readiness should permit exact replay");
        assert_eq!(replay, first);

        let count = storage
            .with_connection(|connection| {
                connection
                    .query_row(
                        "SELECT COUNT(*)
                         FROM continuation_intents
                         WHERE conversation_id = ?1 AND branch_id = ?2",
                        params![conversation_id, branch_id],
                        |row| row.get::<_, i64>(0),
                    )
                    .map_err(NativeError::from)
            })
            .expect("dependency replay intent count should be readable");
        assert_eq!(count, 1);
    }

