    #[test]
    fn continuation_rejects_corrupt_accepted_head_projections_fail_closed() {
        fn tamper_head(
            storage: &Storage,
            stream_id: &str,
            accepted_revision_id: Option<&str>,
            branch_sequence: i64,
        ) {
            storage
                .with_connection(|connection| {
                    // The head's accepted_revision_id is a real foreign key, so
                    // modelling a restored database that points at a missing
                    // revision requires suspending enforcement for this
                    // test-only write (as the cross-goal fixture does).
                    connection.execute_batch(
                        "PRAGMA foreign_keys = OFF;
                         DROP TRIGGER state_revision_heads_scope_guard_update;",
                    )?;
                    connection.execute(
                        "UPDATE state_revision_heads
                         SET accepted_revision_id = ?1, branch_sequence = ?2
                         WHERE stream_id = ?3",
                        params![accepted_revision_id, branch_sequence, stream_id],
                    )?;
                    connection.execute_batch("PRAGMA foreign_keys = ON;")?;
                    Ok(())
                })
                .expect("test-only accepted-head tamper should succeed");
        }

        // A valid accepted revision is enough to prove that a null projection
        // is corruption rather than a candidate-only stream.
        {
            let storage = Storage::in_memory().expect("storage should initialize");
            let conversation = storage
                .create_conversation(None, Some("Continuation null head tamper"))
                .expect("conversation should be created");
            let conversation_id = conversation.conversation.id.clone();
            let branch_id = conversation.conversation.active_branch_id.clone();
            let root = storage
                .append_state_revision(state_revision_request(
                    &conversation_id,
                    &branch_id,
                    "root",
                    "accepted",
                    None,
                    "continuation-tamper-null-root",
                    Vec::new(),
                ))
                .expect("root should append");
            let root_id = root.revision_id.clone().expect("root id should exist");
            tamper_head(&storage, &root.stream_id, None, 0);
            let error = storage
                .resolve_continuation_intent(continuation_request(
                    &conversation_id,
                    &branch_id,
                    &root_id,
                    "execute",
                    "continuation-tamper-null-intent",
                ))
                .expect_err("null head with accepted fact must fail closed");
            assert_eq!(error.code, "state_revision_integrity_failed");
        }

        // A nonzero empty head is invalid even when the stream has no
        // accepted revision yet.
        {
            let storage = Storage::in_memory().expect("storage should initialize");
            let conversation = storage
                .create_conversation(None, Some("Continuation empty head sequence"))
                .expect("conversation should be created");
            let conversation_id = conversation.conversation.id.clone();
            let branch_id = conversation.conversation.active_branch_id.clone();
            let candidate = storage
                .append_state_revision(state_revision_request(
                    &conversation_id,
                    &branch_id,
                    "root",
                    "candidate",
                    None,
                    "continuation-tamper-empty-sequence",
                    Vec::new(),
                ))
                .expect("candidate should append");
            let candidate_id = candidate.revision_id.expect("candidate id should exist");
            tamper_head(&storage, &candidate.stream_id, None, 1);
            let error = storage
                .resolve_continuation_intent(continuation_request(
                    &conversation_id,
                    &branch_id,
                    &candidate_id,
                    "preview",
                    "continuation-tamper-empty-sequence-intent",
                ))
                .expect_err("empty head with nonzero sequence must fail closed");
            assert_eq!(error.code, "state_revision_integrity_failed");
        }

        // The projection cannot point at a candidate revision.
        {
            let storage = Storage::in_memory().expect("storage should initialize");
            let conversation = storage
                .create_conversation(None, Some("Continuation candidate head tamper"))
                .expect("conversation should be created");
            let conversation_id = conversation.conversation.id.clone();
            let branch_id = conversation.conversation.active_branch_id.clone();
            let root = storage
                .append_state_revision(state_revision_request(
                    &conversation_id,
                    &branch_id,
                    "root",
                    "accepted",
                    None,
                    "continuation-tamper-candidate-root",
                    Vec::new(),
                ))
                .expect("root should append");
            let root_id = root.revision_id.clone().expect("root id should exist");
            let candidate = storage
                .append_state_revision(state_revision_request(
                    &conversation_id,
                    &branch_id,
                    "checkpoint",
                    "candidate",
                    Some(&root_id),
                    "continuation-tamper-candidate-fact",
                    vec![root_id.clone()],
                ))
                .expect("candidate should append");
            let candidate_id = candidate.revision_id.expect("candidate id should exist");
            tamper_head(
                &storage,
                &root.stream_id,
                Some(&candidate_id),
                candidate.branch_sequence,
            );
            let error = storage
                .resolve_continuation_intent(continuation_request(
                    &conversation_id,
                    &branch_id,
                    &root_id,
                    "execute",
                    "continuation-tamper-candidate-intent",
                ))
                .expect_err("candidate accepted-head projection must fail closed");
            assert_eq!(error.code, "state_revision_integrity_failed");
        }

        // A head from a sibling stream is not a valid projection for this
        // branch, even when both revisions are accepted and at sequence zero.
        {
            let storage = Storage::in_memory().expect("storage should initialize");
            let conversation_a = storage
                .create_conversation(None, Some("Continuation cross-stream head A"))
                .expect("conversation A should be created");
            let conversation_a_id = conversation_a.conversation.id.clone();
            let branch_a = conversation_a.conversation.active_branch_id.clone();
            let root_a = storage
                .append_state_revision(state_revision_request(
                    &conversation_a_id,
                    &branch_a,
                    "root",
                    "accepted",
                    None,
                    "continuation-tamper-cross-root-a",
                    Vec::new(),
                ))
                .expect("root A should append");
            let root_a_id = root_a.revision_id.clone().expect("root A id should exist");
            let conversation_b = storage
                .create_conversation(None, Some("Continuation cross-stream head B"))
                .expect("conversation B should be created");
            let conversation_b_id = conversation_b.conversation.id.clone();
            let branch_b = conversation_b.conversation.active_branch_id.clone();
            let root_b = storage
                .append_state_revision(state_revision_request(
                    &conversation_b_id,
                    &branch_b,
                    "root",
                    "accepted",
                    None,
                    "continuation-tamper-cross-root-b",
                    Vec::new(),
                ))
                .expect("root B should append");
            let root_b_id = root_b.revision_id.expect("root B id should exist");
            tamper_head(&storage, &root_a.stream_id, Some(&root_b_id), 0);
            let error = storage
                .resolve_continuation_intent(continuation_request(
                    &conversation_a_id,
                    &branch_a,
                    &root_a_id,
                    "execute",
                    "continuation-tamper-cross-intent",
                ))
                .expect_err("cross-stream accepted head must fail closed");
            assert_eq!(error.code, "state_revision_integrity_failed");
        }

        // A missing head revision and a mismatched watermark are distinct
        // corruptions but both must fail before eligibility is evaluated.
        for (suffix, accepted_revision_id, branch_sequence) in [
            (
                "missing",
                Some("state_rev_missing_0123456789abcdef0123456789abcdef"),
                0,
            ),
            ("sequence", None, 99),
        ] {
            let storage = Storage::in_memory().expect("storage should initialize");
            let conversation = storage
                .create_conversation(None, Some("Continuation head mismatch"))
                .expect("conversation should be created");
            let conversation_id = conversation.conversation.id.clone();
            let branch_id = conversation.conversation.active_branch_id.clone();
            let root = storage
                .append_state_revision(state_revision_request(
                    &conversation_id,
                    &branch_id,
                    "root",
                    "accepted",
                    None,
                    &format!("continuation-tamper-{suffix}-root"),
                    Vec::new(),
                ))
                .expect("root should append");
            let root_id = root.revision_id.clone().expect("root id should exist");
            let head_id = accepted_revision_id.or(Some(root_id.as_str()));
            tamper_head(&storage, &root.stream_id, head_id, branch_sequence);
            let error = storage
                .resolve_continuation_intent(continuation_request(
                    &conversation_id,
                    &branch_id,
                    &root_id,
                    "execute",
                    &format!("continuation-tamper-{suffix}-intent"),
                ))
                .expect_err("corrupt accepted head must fail closed");
            assert_eq!(error.code, "state_revision_integrity_failed");
        }
    }

    #[test]
    fn continuation_checkpoint_root_binds_exact_state_revision() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Continuation checkpoint provider");
        let (conversation_id, prepared) =
            prepare_test_run(&storage, &provider.id, '8', "Continuation checkpoint root");
        let branch_id = storage
            .get_conversation(&conversation_id)
            .expect("conversation should remain readable")
            .conversation
            .active_branch_id;
        let root = append_current_state_root(
            &storage,
            &conversation_id,
            &branch_id,
            "continuation-checkpoint-root",
        );
        let root_id = root.revision_id.clone().expect("root id should exist");
        let checkpoint = storage
            .create_run_checkpoint(checkpoint_request(
                &prepared.provider_input.run_id,
                Some(&prepared.provider_input.attempt_id),
                &root_id,
                "continuation-checkpoint-idempotency",
            ))
            .expect("checkpoint should be created");

        let mut valid = continuation_request(
            &conversation_id,
            &branch_id,
            &root_id,
            "execute",
            "continuation-checkpoint-valid",
        );
        valid.root_kind = "checkpoint".to_owned();
        valid.root_id = checkpoint.checkpoint_id.clone();
        let resolved = storage
            .resolve_continuation_intent(valid)
            .expect("checkpoint root should resolve for its exact revision");
        assert_eq!(resolved.root_kind, "checkpoint");
        assert_eq!(resolved.root_id, checkpoint.checkpoint_id);
        assert_eq!(resolved.state_revision_id, root_id);

        let newer = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "continuation",
                "accepted",
                Some(&root_id),
                "continuation-checkpoint-newer",
                vec![root_id.clone()],
            ))
            .expect("newer accepted revision should append");
        let newer_id = newer.revision_id.expect("newer id should exist");
        let mut mismatched = continuation_request(
            &conversation_id,
            &branch_id,
            &newer_id,
            "execute",
            "continuation-checkpoint-mismatch",
        );
        mismatched.root_kind = "checkpoint".to_owned();
        mismatched.root_id = checkpoint.checkpoint_id;
        let error = storage
            .resolve_continuation_intent(mismatched)
            .expect_err("checkpoint must not authorize another state revision");
        assert_eq!(error.code, "continuation_root_not_found");
    }

    #[test]
    fn continuation_replay_is_immutable_and_payload_drift_creates_no_second_intent() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("Continuation replay"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let root = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "root",
                "accepted",
                None,
                "continuation-replay-root",
                Vec::new(),
            ))
            .expect("root should append");
        let root_id = root.revision_id.expect("root id should exist");
        let request = continuation_request(
            &conversation_id,
            &branch_id,
            &root_id,
            "execute",
            "continuation-replay-key",
        );
        let first = storage
            .resolve_continuation_intent(request.clone())
            .expect("continuation should resolve");
        let replay = storage
            .resolve_continuation_intent(request.clone())
            .expect("exact continuation replay should return original intent");
        assert_eq!(replay, first);

        let count = storage
            .with_connection(|connection| {
                connection
                    .query_row(
                        "SELECT COUNT(*) FROM continuation_intents
                         WHERE conversation_id = ?1 AND branch_id = ?2",
                        params![conversation_id, branch_id],
                        |row| row.get::<_, i64>(0),
                    )
                    .map_err(NativeError::from)
            })
            .expect("continuation intent count should be readable");
        assert_eq!(count, 1);

        let mut drifted = request;
        drifted.execution_mode = Some("preview".to_owned());
        let error = storage
            .resolve_continuation_intent(drifted)
            .expect_err("same idempotency key with changed payload must fail");
        assert_eq!(error.code, "payload_drift");
        let count_after_drift = storage
            .with_connection(|connection| {
                connection
                    .query_row(
                        "SELECT COUNT(*) FROM continuation_intents
                         WHERE conversation_id = ?1 AND branch_id = ?2",
                        params![conversation_id, branch_id],
                        |row| row.get::<_, i64>(0),
                    )
                    .map_err(NativeError::from)
            })
            .expect("continuation intent count should remain readable");
        assert_eq!(count_after_drift, 1);
    }

    #[test]
    fn continuation_replay_fails_closed_when_referenced_state_revision_becomes_ineligible() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("Continuation replay state drift"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();

        let root = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "root",
                "accepted",
                None,
                "continuation-replay-state-drift-root",
                Vec::new(),
            ))
            .expect("root revision should append");
        let root_id = root.revision_id.expect("root id should exist");

        // Advance the accepted head first.  This keeps the head projection
        // internally consistent after the test-only mutation below, so the
        // replay reaches the selected revision's eligibility check instead of
        // being classified as a corrupt accepted-head projection.
        storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "continuation",
                "accepted",
                Some(&root_id),
                "continuation-replay-state-drift-child",
                vec![root_id.clone()],
            ))
            .expect("accepted child revision should append");

        let request = continuation_request(
            &conversation_id,
            &branch_id,
            &root_id,
            "execute",
            "continuation-replay-state-drift-key",
        );
        let first = storage
            .resolve_continuation_intent(request.clone())
            .expect("continuation should resolve before state drift");
        assert_eq!(first.state_revision_id, root_id);

        // Simulate a restored or partially trusted database that bypassed the
        // immutable state-revision trigger.  The continuation receipt remains
        // immutable, but its referenced state fact is no longer executable.
        storage
            .with_transaction(|transaction| {
                transaction.execute_batch("DROP TRIGGER state_revisions_immutable_update;")?;
                transaction.execute(
                    "UPDATE state_revisions SET status = 'candidate' WHERE id = ?1",
                    params![root_id],
                )?;
                Ok(())
            })
            .expect("test-only state-revision mutation should succeed");

        let error = storage
            .resolve_continuation_intent(request)
            .expect_err("replay must fail closed after state eligibility drift");
        assert_eq!(error.code, "continuation_state_revision_not_eligible");

        let count = storage
            .with_connection(|connection| {
                connection
                    .query_row(
                        "SELECT COUNT(*) FROM continuation_intents
                         WHERE conversation_id = ?1 AND branch_id = ?2",
                        params![conversation_id, branch_id],
                        |row| row.get::<_, i64>(0),
                    )
                    .map_err(NativeError::from)
            })
            .expect("continuation intent count should remain readable");
        assert_eq!(count, 1);
    }

