    fn resolved_continue_operation(
        conversation_id: &str,
        branch_id: &str,
        root: &StateRevisionMutationResult,
        operation_id: &str,
        idempotency_key: &str,
    ) -> crate::run_control::ResolvedRunControlOperation {
        let root_id = root
            .revision_id
            .clone()
            .expect("root mutation should return a revision identifier");
        RunControlOperationRequest {
            schema_version: Some(RUN_CONTROL_OPERATION_SCHEMA_VERSION),
            operation_id: operation_id.to_owned(),
            kind: RunControlKind::Continue,
            conversation_id: conversation_id.to_owned(),
            branch_id: branch_id.to_owned(),
            source_run_id: None,
            source_attempt_id: None,
            source_message_id: None,
            source_prompt_revision_id: None,
            state_base: RunControlStateBase {
                mode: RunControlStateBaseMode::CurrentState,
                source_state_revision_id: Some(root_id.clone()),
                requested_head_state_revision_id: Some(root_id.clone()),
                resolved_state_revision_id: root_id,
                resolved_state_digest: StateDigest {
                    algorithm: StateDigestAlgorithm::Sha256,
                    canonicalization_revision: "state-revision-c14n-v1".to_owned(),
                    value: root.canonical_payload_hash.clone(),
                },
                selected_delta_ids: Vec::new(),
                context_manifest_id: None,
                resolution_reason: RunControlStateBaseReason::CurrentBranchHead,
                resolved_at: "2026-09-11T00:00:00Z".to_owned(),
                resolved_at_cursors: vec![RunControlCursor {
                    stream_kind: RunControlStreamKind::Conversation,
                    stream_id: conversation_id.to_owned(),
                    journal_epoch: None,
                    sequence: 1,
                    event_id: None,
                    payload_hash: None,
                }],
            },
            edit_revision_id: None,
            continuation_intent: ContinuationIntentKind::UnfinishedAnswer,
            active_run_policy: RunControlActiveRunPolicy::NotApplicable,
            expected_active_run_id: None,
            expected_conversation_version: None,
            expected_branch_cursor: None,
            compare_state_revision_ids: Vec::new(),
            merge_state_revision_ids: Vec::new(),
            actor: RunControlActor {
                kind: RunControlActorKind::User,
                id: "user_local".to_owned(),
            },
            idempotency_key: idempotency_key.to_owned(),
            created_at: "2026-09-11T00:00:00Z".to_owned(),
        }
        .resolve()
        .expect("continue operation should resolve")
    }

    fn resolved_projection_operation(
        conversation_id: &str,
        branch_id: &str,
        root: &StateRevisionMutationResult,
        operation_id: &str,
        idempotency_key: &str,
    ) -> crate::run_control::ResolvedRunControlOperation {
        let mut operation = resolved_continue_operation(
            conversation_id,
            branch_id,
            root,
            operation_id,
            idempotency_key,
        );
        operation.kind = RunControlKind::Copy;
        operation.canonical_payload_hash = operation
            .recompute_canonical_payload_hash()
            .expect("projection operation should rehash");
        operation
    }

    #[test]
    fn run_control_projection_apply_replays_without_state_mutation() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("Run-control projection apply"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let root = append_current_state_root(
            &storage,
            &conversation_id,
            &branch_id,
            "run-control-projection-root",
        );
        let root_id = root
            .revision_id
            .clone()
            .expect("root revision should have an identifier");
        let operation_id = "operation_projection_apply_0123456789abcdef0123456789abcdef";
        let persisted = storage
            .persist_run_control_resolution(resolved_projection_operation(
                &conversation_id,
                &branch_id,
                &root,
                operation_id,
                "run-control-projection-apply",
            ))
            .expect("resolved projection operation should persist");

        let before_state = state_revision_counts(&storage, &root.stream_id);
        let before_journal = state_revision_journal_counts(&storage, &root.stream_id);
        let before_metadata = state_revision_metadata_counts(&storage);
        let before_head = accepted_head_snapshot(&storage, &root.stream_id);
        assert_eq!(run_control_event_counts(&storage, operation_id), (1, 1, 0));

        let request = crate::run_control::RunControlApplyRequest {
            operation_id: persisted.operation_id.clone(),
            idempotency_key: persisted.idempotency_key.clone(),
            expected_operation_state: Some(RunControlOperationState::Resolved),
            expected_head_state_revision_id: Some(root_id),
        };
        let first = storage
            .apply_run_control(request.clone())
            .expect("first projection apply should commit");
        assert_eq!(
            first.operation.operation_state,
            RunControlOperationState::Applied
        );
        assert!(first.durable);
        assert!(!first.replayed);
        assert!(first.state_revision_id.is_none());
        assert!(first
            .operation
            .result
            .as_ref()
            .is_some_and(|result| result.result_state_revision_id.is_none()));
        assert_eq!(
            state_revision_counts(&storage, &root.stream_id),
            before_state
        );
        assert_eq!(
            state_revision_journal_counts(&storage, &root.stream_id),
            before_journal
        );
        assert_eq!(state_revision_metadata_counts(&storage), before_metadata);
        assert_eq!(
            accepted_head_snapshot(&storage, &root.stream_id),
            before_head
        );
        assert_eq!(run_control_event_counts(&storage, operation_id), (2, 1, 1));

        let replay = storage
            .apply_run_control(request)
            .expect("projection terminal result should replay");
        assert!(replay.durable);
        assert!(replay.replayed);
        assert_eq!(replay.state_revision_id, None);
        assert_eq!(replay.operation, first.operation);
        assert_eq!(
            state_revision_counts(&storage, &root.stream_id),
            before_state
        );
        assert_eq!(
            state_revision_journal_counts(&storage, &root.stream_id),
            before_journal
        );
        assert_eq!(state_revision_metadata_counts(&storage), before_metadata);
        assert_eq!(
            accepted_head_snapshot(&storage, &root.stream_id),
            before_head
        );
        assert_eq!(run_control_event_counts(&storage, operation_id), (2, 1, 1));
    }

    #[test]
    fn run_control_lifecycle_append_reports_exact_receipt_replay() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("Run-control lifecycle race"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let root = append_current_state_root(
            &storage,
            &conversation_id,
            &branch_id,
            "run-control-lifecycle-race-root",
        );
        let operation_id = "operation_projection_race_0123456789abcdef0123456789abcdef";
        let persisted = storage
            .persist_run_control_resolution(resolved_projection_operation(
                &conversation_id,
                &branch_id,
                &root,
                operation_id,
                "run-control-projection-race",
            ))
            .expect("resolved projection operation should persist");
        let applied = persisted.clone().with_applied_projection();

        // Two callers may both miss the non-terminal read before one writer
        // commits.  The lifecycle append primitive must expose which caller
        // won the immutable receipt assignment so the loser can report a
        // replay instead of claiming a fresh apply.
        let first_inserted = storage
            .append_run_control_operation_event(
                &persisted.operation_id,
                RunControlOperationState::Applied,
                &applied,
            )
            .expect("first lifecycle append should insert");
        assert!(first_inserted);

        let second_inserted = storage
            .append_run_control_operation_event(
                &persisted.operation_id,
                RunControlOperationState::Applied,
                &applied,
            )
            .expect("second identical lifecycle append should replay");
        assert!(!second_inserted);
        assert_eq!(run_control_event_counts(&storage, operation_id), (2, 1, 1));
    }

    #[test]
    fn run_control_apply_lifecycle_failure_rolls_back_state_mutation() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("Atomic run-control apply"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let root = append_current_state_root(
            &storage,
            &conversation_id,
            &branch_id,
            "run-control-atomic-root",
        );
        let root_id = root
            .revision_id
            .clone()
            .expect("root revision should exist");
        let operation_id = "operation_atomic_apply_0123456789abcdef0123456789abcdef";
        let persisted = storage
            .persist_run_control_resolution(resolved_continue_operation(
                &conversation_id,
                &branch_id,
                &root,
                operation_id,
                "run-control-atomic-apply",
            ))
            .expect("resolved operation should persist");

        let before_state = state_revision_counts(&storage, &root.stream_id);
        let before_journal = state_revision_journal_counts(&storage, &root.stream_id);
        let before_metadata = state_revision_metadata_counts(&storage);
        let before_head = accepted_head_snapshot(&storage, &root.stream_id);
        assert_eq!(run_control_event_counts(&storage, operation_id), (1, 1, 0));

        // Fail only the terminal lifecycle insert. The state-revision append,
        // CAS head update, operation fact, journal event and idempotency
        // receipt must all roll back with the same outer transaction.
        storage
            .with_transaction(|transaction| {
                transaction.execute_batch(
                    "CREATE TRIGGER test_fail_run_control_applied
                     BEFORE INSERT ON run_control_operation_events
                     WHEN NEW.operation_state = 'applied'
                     BEGIN
                         SELECT RAISE(ABORT, 'test lifecycle failure');
                     END;",
                )?;
                Ok(())
            })
            .expect("test trigger should install");

        let error = storage
            .apply_run_control(RunControlApplyRequest {
                operation_id: persisted.operation_id.clone(),
                idempotency_key: persisted.idempotency_key.clone(),
                expected_operation_state: Some(RunControlOperationState::Resolved),
                expected_head_state_revision_id: Some(root_id),
            })
            .expect_err("lifecycle insertion failure should abort the apply");
        assert_eq!(error.code, "storage_failed");

        assert_eq!(
            state_revision_counts(&storage, &root.stream_id),
            before_state
        );
        assert_eq!(
            state_revision_journal_counts(&storage, &root.stream_id),
            before_journal
        );
        assert_eq!(state_revision_metadata_counts(&storage), before_metadata);
        assert_eq!(
            accepted_head_snapshot(&storage, &root.stream_id),
            before_head
        );
        assert_eq!(run_control_event_counts(&storage, operation_id), (1, 1, 0));

        storage
            .with_transaction(|transaction| {
                transaction.execute_batch("DROP TRIGGER test_fail_run_control_applied;")?;
                Ok(())
            })
            .expect("test trigger should be removed");
    }

