    #[test]
    fn run_control_apply_repairs_missing_terminal_event_without_second_revision() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("Run-control lifecycle repair"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let root = append_current_state_root(
            &storage,
            &conversation_id,
            &branch_id,
            "run-control-repair-root",
        );
        let root_id = root
            .revision_id
            .clone()
            .expect("root revision should have an identifier");
        let operation_id = "operation_lifecycle_repair_0123456789abcdef0123456789abcdef";
        let persisted = storage
            .persist_run_control_resolution(resolved_continue_operation(
                &conversation_id,
                &branch_id,
                &root,
                operation_id,
                "run-control-lifecycle-repair",
            ))
            .expect("resolved operation should persist");

        // Simulate a process crash after the native state-revision receipt was
        // committed but before the terminal lifecycle event was written.
        let mut append_request = persisted
            .to_state_revision_append_request()
            .expect("resolved operation should map to a state revision request");
        append_request.status = "accepted".to_owned();
        let pre_repair = storage
            .append_state_revision(append_request)
            .expect("the orphaned state-revision receipt should seed");
        assert_eq!(pre_repair.outcome, "applied");
        let facts_before = state_revision_counts(&storage, &root.stream_id);
        let journal_before = state_revision_journal_counts(&storage, &root.stream_id);
        let head_before = accepted_head_snapshot(&storage, &root.stream_id);
        assert_eq!(run_control_event_counts(&storage, operation_id), (1, 1, 0));

        let repaired = storage
            .apply_run_control(crate::run_control::RunControlApplyRequest {
                operation_id: persisted.operation_id.clone(),
                idempotency_key: persisted.idempotency_key.clone(),
                expected_operation_state: Some(
                    crate::run_control::RunControlOperationState::Resolved,
                ),
                expected_head_state_revision_id: Some(root_id),
            })
            .expect("apply should repair the missing terminal lifecycle event");
        assert!(repaired.replayed);
        assert_eq!(
            repaired.state_revision_id.as_deref(),
            pre_repair.revision_id.as_deref()
        );
        assert_eq!(
            state_revision_counts(&storage, &root.stream_id),
            facts_before
        );
        assert_eq!(
            state_revision_journal_counts(&storage, &root.stream_id),
            journal_before
        );
        assert_eq!(
            accepted_head_snapshot(&storage, &root.stream_id),
            head_before
        );
        assert_eq!(run_control_event_counts(&storage, operation_id), (2, 1, 1));
    }

    /// Seeds one native-owned, conversation-scoped draft without exposing a
    /// filesystem path. The helper exercises the same SQLite lifecycle guards
    /// used by the picker; the payload is synthetic because this is a storage
    /// lineage test rather than a content-store test.
    fn seed_open_attachment_draft(
        storage: &Storage,
        conversation_id: &str,
        branch_id: &str,
        suffix: char,
        created_at_ms: i64,
        expires_at_ms: i64,
    ) -> (String, String) {
        seed_open_attachment_draft_with_media_type(
            storage,
            conversation_id,
            branch_id,
            suffix,
            created_at_ms,
            expires_at_ms,
            "image/png",
        )
    }

    fn seed_open_attachment_draft_with_media_type(
        storage: &Storage,
        conversation_id: &str,
        branch_id: &str,
        suffix: char,
        created_at_ms: i64,
        expires_at_ms: i64,
        media_type: &str,
    ) -> (String, String) {
        let suffixes = suffix.to_string().repeat(32);
        let draft_id = format!("attachment_draft_{suffixes}");
        let attachment_id = format!("attachment_{suffixes}");
        let blob_id = sha256_hex(format!("native-admission-test-{suffix}").as_bytes());
        storage
            .with_transaction(|transaction| {
                transaction.execute(
                    "INSERT INTO blob_objects (
                        id, cipher_version, key_version, wrapped_dek, nonce,
                        media_type, plaintext_size, ciphertext_size,
                        storage_relpath, created_at_ms
                     ) VALUES (?1, 1, 1, X'01', X'000000000000000000000000',
                               ?2, 4, 20, ?3, ?4)",
                    params![
                        blob_id,
                        media_type,
                        format!("v1/test/{suffix}"),
                        created_at_ms
                    ],
                )?;
                transaction.execute(
                    "INSERT INTO attachment_drafts (
                        id, profile_id, conversation_id, branch_id, state,
                        expires_at_ms, created_at_ms, updated_at_ms, metadata_json
                     ) VALUES (?1, ?2, ?3, ?4, 'open', ?5, ?6, ?6, '{}')",
                    params![
                        draft_id,
                        DEFAULT_PROFILE_ID,
                        conversation_id,
                        branch_id,
                        expires_at_ms,
                        created_at_ms,
                    ],
                )?;
                transaction.execute(
                    "INSERT INTO attachments (
                        id, profile_id, draft_id, blob_id, filename, media_type,
                        byte_size, extraction_status, created_at_ms, metadata_json
                     ) VALUES (?1, ?2, ?3, ?4, 'native-admission.bin', ?5,
                               4, 'pending', ?6, '{}')",
                    params![
                        attachment_id,
                        DEFAULT_PROFILE_ID,
                        draft_id,
                        blob_id,
                        media_type,
                        created_at_ms,
                    ],
                )?;
                Ok(())
            })
            .expect("test attachment draft should seed");
        (draft_id, attachment_id)
    }

