    #[test]
    fn run_control_replay_rejects_conflicting_terminal_events() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("Conflicting run-control events"))
            .expect("conversation should be created");
        let operation_id = "operation_0123456789abcdef0123456789abcdef";
        let canonical_payload_hash = "a".repeat(64);

        // Seed a valid operation receipt, then deliberately append two distinct
        // terminal states. The schema enforces one event per state, but it does
        // not permit contradictory outcomes to be represented as one state.
        // Recovery must therefore fail closed instead of choosing by row order.
        storage
            .with_transaction(|transaction| {
                transaction.execute(
                    "INSERT INTO run_control_operations (
                        operation_id, profile_id, conversation_id, branch_id,
                        idempotency_key_hash, canonical_payload_hash, operation_json,
                        operation_state, created_at_ms
                     ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, '{}', 'resolved', 1)",
                    params![
                        operation_id,
                        DEFAULT_PROFILE_ID,
                        &conversation.conversation.id,
                        &conversation.conversation.active_branch_id,
                        "b".repeat(64),
                        &canonical_payload_hash,
                    ],
                )?;
                transaction.execute(
                    "INSERT INTO run_control_operation_events (
                        event_id, operation_id, operation_state, result_json, created_at_ms
                     ) VALUES (?1, ?2, 'applied', '{}', 2)",
                    params![
                        "run_control_event_applied_0123456789abcdef0123456789abcdef",
                        operation_id,
                    ],
                )?;
                transaction.execute(
                    "INSERT INTO run_control_operation_events (
                        event_id, operation_id, operation_state, result_json, created_at_ms
                     ) VALUES (?1, ?2, 'blocked', '{}', 3)",
                    params![
                        "run_control_event_blocked_0123456789abcdef0123456789abcdef",
                        operation_id,
                    ],
                )?;
                Ok(())
            })
            .expect("conflicting terminal events should be seedable for the test");

        let error = storage
            .read_terminal_run_control_event(operation_id, &canonical_payload_hash)
            .expect_err("conflicting terminal events must fail closed");
        assert_eq!(error.code, "run_control_integrity_failed");
        assert_eq!(
            error.message,
            "The run-control operation has conflicting terminal lifecycle events"
        );

        let (event_count, state_revision_count): (i64, i64) = storage
            .with_connection(|connection| {
                connection
                    .query_row(
                        "SELECT
                            (SELECT COUNT(*) FROM run_control_operation_events
                             WHERE operation_id = ?1),
                            (SELECT COUNT(*) FROM state_revisions)",
                        [operation_id],
                        |row| Ok((row.get(0)?, row.get(1)?)),
                    )
                    .map_err(NativeError::from)
            })
            .expect("run-control rows should remain readable");
        assert_eq!(event_count, 2);
        assert_eq!(state_revision_count, 0);
    }

    #[test]
    fn run_control_replay_rejects_result_revision_owned_by_another_operation() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("Run-control lineage replay"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();

        let owner_operation_id = "operation_fact_owner_0123456789abcdef0123456789abcdef".to_owned();
        let mut root_request = state_revision_request(
            &conversation_id,
            &branch_id,
            "root",
            "accepted",
            None,
            "run-control-lineage-root",
            Vec::new(),
        );
        // The root revision is intentionally created by operation A.  It has
        // no parent edge, so the revision-keyed operation fact is the only
        // durable lineage address available to terminal replay.
        root_request.operation_id = Some(owner_operation_id.clone());
        let root = storage
            .append_state_revision(root_request)
            .expect("operation A root revision should append");
        let root_revision_id = root
            .revision_id
            .clone()
            .expect("root revision id should exist");

        let replay_operation_id =
            "operation_replay_owner_0123456789abcdef0123456789abcdef".to_owned();
        let operation_request = RunControlOperationRequest {
            schema_version: Some(RUN_CONTROL_OPERATION_SCHEMA_VERSION),
            operation_id: replay_operation_id.clone(),
            kind: RunControlKind::Branch,
            conversation_id: conversation_id.clone(),
            branch_id: branch_id.clone(),
            source_run_id: None,
            source_attempt_id: None,
            source_message_id: None,
            source_prompt_revision_id: None,
            state_base: RunControlStateBase {
                mode: RunControlStateBaseMode::CurrentState,
                source_state_revision_id: Some(root_revision_id.clone()),
                requested_head_state_revision_id: Some(root_revision_id.clone()),
                resolved_state_revision_id: root_revision_id.clone(),
                resolved_state_digest: StateDigest {
                    algorithm: StateDigestAlgorithm::Sha256,
                    canonicalization_revision: "state-revision-c14n-v1".to_owned(),
                    value: "0123456789abcdef0123456789abcdef".to_owned(),
                },
                selected_delta_ids: Vec::new(),
                context_manifest_id: None,
                resolution_reason: RunControlStateBaseReason::CurrentBranchHead,
                resolved_at: "2026-09-11T00:00:00Z".to_owned(),
                resolved_at_cursors: vec![RunControlCursor {
                    stream_kind: RunControlStreamKind::Branch,
                    stream_id: branch_id.clone(),
                    journal_epoch: None,
                    sequence: 1,
                    event_id: None,
                    payload_hash: None,
                }],
            },
            edit_revision_id: None,
            continuation_intent: ContinuationIntentKind::None,
            active_run_policy: RunControlActiveRunPolicy::NotApplicable,
            expected_active_run_id: None,
            expected_conversation_version: None,
            expected_branch_cursor: None,
            compare_state_revision_ids: Vec::new(),
            merge_state_revision_ids: Vec::new(),
            actor: RunControlActor {
                kind: RunControlActorKind::User,
                id: "user_local".to_owned(),
            },
            idempotency_key: "run-control-lineage-replay".to_owned(),
            created_at: "2026-09-11T00:00:00Z".to_owned(),
        };
        let resolved = operation_request
            .resolve()
            .expect("operation B should resolve into a valid envelope");
        let canonical_payload_hash = resolved.canonical_payload_hash.clone();
        let operation_json =
            serde_json::to_string(&resolved).expect("resolved operation should serialize");
        let applied = resolved.with_applied_revision(root_revision_id.clone());
        let result_json = serde_json::to_string(&serde_json::json!({
            "operation": &applied,
            "canonicalPayloadHash": &canonical_payload_hash,
        }))
        .expect("terminal event should serialize");

        // Seed the native operation row and a syntactically valid terminal
        // event directly.  The event is branch-scoped and hash-valid, but its
        // result revision was created by operation A, not operation B.
        storage
            .with_transaction(|transaction| {
                transaction.execute(
                    "INSERT INTO run_control_operations (
                        operation_id, profile_id, conversation_id, branch_id,
                        idempotency_key_hash, canonical_payload_hash, operation_json,
                        operation_state, created_at_ms
                     ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, 'resolved', 1)",
                    params![
                        &replay_operation_id,
                        DEFAULT_PROFILE_ID,
                        &conversation_id,
                        &branch_id,
                        sha256_hex(b"run-control-lineage-replay"),
                        &canonical_payload_hash,
                        &operation_json,
                    ],
                )?;
                transaction.execute(
                    "INSERT INTO run_control_operation_events (
                        event_id, operation_id, operation_state, result_json, created_at_ms
                     ) VALUES (?1, ?2, 'applied', ?3, 2)",
                    params![
                        "run_control_event_lineage_mismatch_0123456789abcdef0123456789abcdef",
                        &replay_operation_id,
                        &result_json,
                    ],
                )?;
                Ok(())
            })
            .expect("the mismatched terminal event should be seedable");

        let error = storage
            .read_terminal_run_control_event(&replay_operation_id, &canonical_payload_hash)
            .expect_err("a revision owned by another operation must fail closed");
        assert_eq!(error.code, "run_control_integrity_failed");
        assert_eq!(
            error.message,
            "The terminal run-control result operation lineage does not match its operation"
        );
    }

    #[test]
    fn v8_profiles_migrate_to_current_without_losing_telemetry_or_integrity() {
        let mut connection = Connection::open_in_memory().expect("database should open");
        configure(&connection).expect("database should configure");
        {
            let transaction = connection.transaction().expect("transaction should open");
            const CURRENT_SCHEMA: &str = include_str!("../../docs/storage-schema.sql");
            let (schema_through_v3, schema_v4, schema_v5, schema_v6, schema_v7) =
                split_current_schema(CURRENT_SCHEMA).expect("schema should split through v7");
            transaction
                .execute_batch(schema_through_v3)
                .expect("v3 schema should apply");
            transaction
                .execute_batch(schema_v4)
                .expect("v4 schema should apply");
            transaction
                .execute_batch(schema_v5)
                .expect("v5 schema should apply");
            transaction
                .execute_batch(schema_v6)
                .expect("v6 schema should apply");
            transaction
                .execute_batch(schema_v7)
                .expect("v7 schema should apply");
            transaction
                .execute_batch(
                    split_telemetry_schema(CURRENT_SCHEMA)
                        .expect("v8 schema should exclude the v9 bridge schema"),
                )
                .expect("v8 telemetry schema should apply");

            let now = now_ms();
            transaction
                .execute(
                    "INSERT INTO schema_meta (
                        singleton, schema_version, min_app_version, created_at_ms,
                        updated_at_ms, profile_id, encryption_key_version
                     ) VALUES (1, 8, '0.7.0', ?1, ?1, ?2, 1)",
                    params![now, DEFAULT_PROFILE_ID],
                )
                .expect("v8 schema meta should insert");
            transaction
                .execute(
                    "INSERT INTO schema_migrations (
                        migration_id, checksum_sha256, started_at_ms, completed_at_ms,
                        duration_ms, app_version
                     ) VALUES ('0008_local_first_telemetry', ?1, ?2, ?2, 0, '0.7.0')",
                    params![sha256_hex(b"v8-telemetry"), now],
                )
                .expect("v8 migration marker should insert");
            transaction
                .execute(
                    "INSERT INTO app_profiles (
                        id, display_name, created_at_ms, updated_at_ms, settings_json
                     ) VALUES (?1, ?2, ?3, ?3, '{}')",
                    params![DEFAULT_PROFILE_ID, DEFAULT_PROFILE_NAME, now],
                )
                .expect("default profile should insert");
            transaction
                .execute(
                    "INSERT INTO telemetry_daily_rollups (
                        id, schema_version, profile_id, day_utc, provider_type,
                        model_bucket, operation_kind, outcome, sample_count,
                        created_at_ms, updated_at_ms
                     ) VALUES (
                        'telemetry_rollup_v8_fixture', 1, ?1, '2026-08-15',
                        'openai_compatible', 'fixture-model', 'chat', 'complete',
                        3, ?2, ?2
                     )",
                    params![DEFAULT_PROFILE_ID, now],
                )
                .expect("v8 telemetry fixture should insert");
            transaction
                .pragma_update(None, "user_version", 8)
                .expect("v8 user version should set");
            transaction.commit().expect("v8 fixture should commit");
        }

        assert!(!table_exists(&connection, "multimodal_bridge_plans"));
        migrate(&mut connection).expect("v8 database should migrate to current");

        let user_version: i64 = connection
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .expect("user version should load");
        let schema_version: i64 = connection
            .query_row(
                "SELECT schema_version FROM schema_meta WHERE singleton = 1",
                [],
                |row| row.get(0),
            )
            .expect("schema meta should load");
        let marker_count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM schema_migrations
                 WHERE migration_id = '0009_multimodal_bridge_receipts'",
                [],
                |row| row.get(0),
            )
            .expect("migration marker should load");
        let telemetry_count: i64 = connection
            .query_row(
                "SELECT sample_count FROM telemetry_daily_rollups
                 WHERE id = 'telemetry_rollup_v8_fixture'",
                [],
                |row| row.get(0),
            )
            .expect("v8 telemetry should survive migration");

        assert_eq!(user_version, SCHEMA_VERSION);
        assert_eq!(schema_version, SCHEMA_VERSION);
        assert_eq!(marker_count, 1);
        assert_eq!(telemetry_count, 3);
        assert!(table_exists(&connection, "multimodal_bridge_plans"));
        assert!(table_exists(
            &connection,
            "multimodal_bridge_plan_artifacts"
        ));
        assert!(table_exists(
            &connection,
            "multimodal_bridge_stage_receipts"
        ));
        let v10_marker_count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM schema_migrations
                 WHERE migration_id = '0010_multimodal_bridge_review_hardening'",
                [],
                |row| row.get(0),
            )
            .expect("v10 migration marker should load");
        assert_eq!(v10_marker_count, 1);
        assert_eq!(foreign_key_violations(&connection), 0);
        let integrity: String = connection
            .query_row("PRAGMA quick_check", [], |row| row.get(0))
            .expect("quick check should run");
        assert_eq!(integrity, "ok");
    }

