    #[test]
    fn v5_migration_rolls_back_all_schema_changes_on_conflict() {
        let mut connection = Connection::open_in_memory().expect("database should open");
        configure(&connection).expect("database should configure");
        {
            let transaction = connection.transaction().expect("transaction should open");
            const CURRENT_SCHEMA: &str = include_str!("../../docs/storage-schema.sql");
            let (schema_through_v3, schema_v4, _, _, _) =
                split_current_schema(CURRENT_SCHEMA).expect("prepared input marker should exist");
            transaction
                .execute_batch(schema_through_v3)
                .expect("v3 schema should apply");
            transaction
                .execute_batch(schema_v4)
                .expect("v4 schema should apply");
            let now = now_ms();
            transaction
                .execute(
                    "INSERT INTO schema_meta (
                        singleton, schema_version, min_app_version, created_at_ms,
                        updated_at_ms, profile_id, encryption_key_version
                     ) VALUES (1, 4, '0.3.0', ?1, ?1, ?2, 1)",
                    params![now, DEFAULT_PROFILE_ID],
                )
                .unwrap();
            transaction
                .execute(
                    "INSERT INTO app_profiles (
                        id, display_name, created_at_ms, updated_at_ms, settings_json
                     ) VALUES (?1, ?2, ?3, ?3, '{}')",
                    params![DEFAULT_PROFILE_ID, DEFAULT_PROFILE_NAME, now],
                )
                .unwrap();
            transaction.pragma_update(None, "user_version", 4).unwrap();
            transaction.commit().unwrap();
        }
        connection
            .execute(
                "CREATE TABLE frozen_provider_inputs (id TEXT PRIMARY KEY) STRICT",
                [],
            )
            .expect("conflicting v5 table should be installed");

        assert!(migrate(&mut connection).is_err());

        assert_eq!(
            connection
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i64>(0))
                .unwrap(),
            4
        );
        assert_eq!(
            connection
                .query_row(
                    "SELECT schema_version FROM schema_meta WHERE singleton = 1",
                    [],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            4
        );
        assert!(!has_column(
            &connection,
            "frozen_provider_inputs",
            "dispatch_started_at_ms"
        ));
        assert_eq!(
            connection
                .query_row(
                    "SELECT COUNT(*) FROM sqlite_schema
                     WHERE type IN ('index', 'trigger')
                       AND name IN (
                           'frozen_provider_inputs_run_idx',
                           'frozen_provider_inputs_scope_guard_insert',
                           'frozen_provider_inputs_body_immutable',
                           'frozen_provider_inputs_dispatch_guard'
                       )",
                    [],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            0
        );
        assert_eq!(
            connection
                .query_row(
                    "SELECT COUNT(*) FROM schema_migrations
                     WHERE migration_id = '0005_frozen_provider_inputs'",
                    [],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            0
        );
        assert_eq!(foreign_key_violations(&connection), 0);
    }

