    #[test]
    fn project_metadata_update_is_trimmed_and_uses_optimistic_concurrency() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let project = storage
            .create_project("Initial", Some("Description"), Some("Instructions"))
            .expect("project should be created");

        let updated = storage
            .update_project_metadata(
                &project.id,
                "  Updated  ",
                Some(" New description "),
                Some(" New instructions "),
                project.updated_at_ms,
            )
            .expect("metadata update should succeed");
        assert_eq!(updated.id, project.id);
        assert_eq!(updated.name, "Updated");
        assert_eq!(updated.description.as_deref(), Some("New description"));
        assert_eq!(updated.instructions.as_deref(), Some("New instructions"));
        assert!(updated.updated_at_ms > project.updated_at_ms);

        let error = storage
            .update_project_metadata(&project.id, "Another", None, None, project.updated_at_ms)
            .expect_err("stale metadata update must be rejected");
        assert_eq!(error.code, "project_conflict");
    }

    #[test]
    fn project_metadata_update_is_idempotent_for_an_unchanged_snapshot() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let project = storage
            .create_project("Stable", None, None)
            .expect("project should be created");

        let unchanged = storage
            .update_project_metadata(
                &project.id,
                &project.name,
                project.description.as_deref(),
                project.instructions.as_deref(),
                project.updated_at_ms,
            )
            .expect("unchanged metadata should be accepted");
        assert_eq!(unchanged.updated_at_ms, project.updated_at_ms);
        let listed = storage
            .list_projects()
            .expect("project should remain listed");
        assert_eq!(listed.len(), 1);
        assert_eq!(listed[0].id, unchanged.id);
        assert_eq!(listed[0].updated_at_ms, unchanged.updated_at_ms);
    }

    #[test]
    fn project_metadata_update_rejects_invalid_precondition_and_missing_project() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let project = storage
            .create_project("Validation", None, None)
            .expect("project should be created");

        let invalid_timestamp = storage
            .update_project_metadata(&project.id, "Validation", None, None, 0)
            .expect_err("zero precondition must be rejected");
        assert_eq!(invalid_timestamp.code, "invalid_input");

        let missing = storage
            .update_project_metadata(
                "project_22222222222222222222222222222222",
                "Missing",
                None,
                None,
                project.updated_at_ms,
            )
            .expect_err("missing project must be rejected");
        assert_eq!(missing.code, "project_not_found");
    }

