    #[test]
    fn startup_recovery_marks_dispatched_attempts_outcome_unknown() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = storage
            .save_provider_profile(NewProviderProfile {
                provider_type: "openai_compatible",
                display_name: "Recovery provider",
                normalized_base_url: "https://api.example.com/v1",
                auth_scheme: "bearer",
                organization_id: None,
                remote_project_id: None,
                credential_ref: Some("provider_secret_0123456789abcdef0123456789abcdef"),
                local_network_grant: false,
            })
            .unwrap();
        let conversation = storage.create_conversation(None, None).unwrap();
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let prepared = storage
            .prepare_conversation_run(NewConversationRun {
                conversation_id: &conversation_id,
                branch_id: &branch_id,
                run_id: "run_44444444444444444444444444444444",
                attempt_id: "attempt_44444444444444444444444444444444",
                user_message_id: "message_44444444444444444444444444444444",
                assistant_message_id: "message_55555555555555555555555555555555",
                prompt: "Recover safely",
                provider_profile_id: &provider.id,
                model_id: "recovery-model",
                request_parameters_json: "{}",
            })
            .unwrap();
        let dispatch = StartPreparedAttemptRequest {
            attempt_id: prepared.provider_input.attempt_id,
            frozen_provider_input_id: prepared.provider_input.id,
        };
        storage
            .mark_prepared_attempt_dispatching(&dispatch)
            .unwrap();
        storage
            .append_assistant_delta(
                "run_44444444444444444444444444444444",
                "Partial before restart",
            )
            .unwrap();

        {
            let mut connection = storage.lock().unwrap();
            recover_incomplete_runs(&mut connection).unwrap();
        }
        let recovered = storage.get_conversation(&conversation_id).unwrap();
        assert_eq!(recovered.messages[1].status, "failed");
        assert_eq!(recovered.messages[1].content_text, "Partial before restart");
        assert_eq!(recovered.runs[0].state, "failed");
        assert_eq!(
            recovered.runs[0].error_code.as_deref(),
            Some("app_restarted")
        );
        assert_eq!(recovered.attempts[0].state, "outcome_unknown");
        assert_eq!(recovered.attempts[0].accepted_by_provider, "unknown");

        let journal = storage
            .read_run_journal(&ReadRunJournalRequest {
                run_id: "run_44444444444444444444444444444444".into(),
                journal_epoch: None,
                after_sequence: None,
                after_event_id: None,
                through_sequence: None,
                through_event_id: None,
                limit: Some(1_000),
            })
            .expect("recovery facts should be replayable");
        let event_types = journal
            .events
            .iter()
            .map(|event| event.event_type.as_str())
            .collect::<Vec<_>>();
        assert_eq!(
            event_types,
            vec![
                "run.created",
                "attempt.created",
                "run.dispatching",
                "attempt.dispatch_started",
                "attempt.accepted",
                "run.started",
                "message.text_delta",
                "run.recovered",
                "attempt.outcome_unknown",
                "run.failed",
            ]
        );
        assert!(journal.complete);

        // Recovery is idempotent: once the run and its attempt are terminal,
        // a second startup pass must return the same immutable journal/result
        // rather than appending another recovery or failure fact.
        let partial_text = recovered.messages[1].content_text.clone();
        {
            let mut connection = storage.lock().unwrap();
            recover_incomplete_runs(&mut connection).expect("terminal recovery should be a no-op");
        }
        let replayed = storage
            .read_run_journal(&ReadRunJournalRequest {
                run_id: "run_44444444444444444444444444444444".into(),
                journal_epoch: None,
                after_sequence: None,
                after_event_id: None,
                through_sequence: None,
                through_event_id: None,
                limit: Some(1_000),
            })
            .expect("the idempotent recovery journal should remain readable");
        assert_eq!(replayed.events.len(), journal.events.len());
        assert_eq!(
            replayed
                .events
                .iter()
                .filter(|event| event.event_type == "run.recovered")
                .count(),
            1
        );
        assert_eq!(
            replayed
                .events
                .iter()
                .filter(|event| event.event_type == "run.failed")
                .count(),
            1
        );
        let replayed_snapshot = storage.get_conversation(&conversation_id).unwrap();
        assert_eq!(replayed_snapshot.messages[1].content_text, partial_text);
        assert_eq!(replayed_snapshot.messages[1].status, "failed");
        assert_eq!(replayed_snapshot.runs[0].state, "failed");
        assert_eq!(replayed_snapshot.attempts[0].state, "outcome_unknown");
    }

    #[test]
    fn startup_recovery_rejects_ambiguous_active_attempts_atomically() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = storage
            .save_provider_profile(NewProviderProfile {
                provider_type: "openai_compatible",
                display_name: "Ambiguous recovery provider",
                normalized_base_url: "https://api.example.com/v1",
                auth_scheme: "bearer",
                organization_id: None,
                remote_project_id: None,
                credential_ref: Some("provider_secret_0123456789abcdef0123456789abcdef"),
                local_network_grant: false,
            })
            .unwrap();
        let conversation = storage.create_conversation(None, None).unwrap();
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let prepared = storage
            .prepare_conversation_run(NewConversationRun {
                conversation_id: &conversation_id,
                branch_id: &branch_id,
                run_id: "run_55555555555555555555555555555555",
                attempt_id: "attempt_55555555555555555555555555555555",
                user_message_id: "message_55555555555555555555555555555555",
                assistant_message_id: "message_66666666666666666666666666666666",
                prompt: "Do not choose between active attempts",
                provider_profile_id: &provider.id,
                model_id: "ambiguous-recovery-model",
                request_parameters_json: "{}",
            })
            .unwrap();
        storage
            .mark_prepared_attempt_dispatching(&StartPreparedAttemptRequest {
                attempt_id: prepared.provider_input.attempt_id.clone(),
                frozen_provider_input_id: prepared.provider_input.id.clone(),
            })
            .unwrap();
        storage
            .append_assistant_delta(
                "run_55555555555555555555555555555555",
                "Partial before ambiguous recovery",
            )
            .unwrap();

        let before = storage.get_conversation(&conversation_id).unwrap();
        let before_events = storage
            .with_connection(|connection| {
                let mut statement = connection.prepare(
                    "SELECT event_type FROM run_events
                     WHERE run_id = ?1 ORDER BY sequence_no",
                )?;
                let events = statement
                    .query_map(["run_55555555555555555555555555555555"], |row| {
                        row.get::<_, String>(0)
                    })?
                    .collect::<Result<Vec<_>, _>>()?;
                Ok(events)
            })
            .unwrap();

        {
            let connection = storage.lock().unwrap();
            connection
                .execute(
                    "INSERT INTO run_attempts (
                         id, generation_id, ordinal, provider_profile_id, model_id,
                         state, accepted_by_provider, idempotency_supported, created_at_ms
                     ) VALUES (?1, ?2, 2, ?3, ?4, 'streaming', 'true', 0, ?5)",
                    params![
                        "attempt_77777777777777777777777777777777",
                        "run_55555555555555555555555555555555",
                        provider.id,
                        "ambiguous-recovery-model",
                        now_ms()
                    ],
                )
                .unwrap();
        }

        let error = {
            let mut connection = storage.lock().unwrap();
            recover_incomplete_runs(&mut connection)
                .expect_err("multiple active attempts must fail closed")
        };
        assert_eq!(error.code, "run_recovery_ambiguous");

        let after = storage.get_conversation(&conversation_id).unwrap();
        assert_eq!(after.runs[0].state, before.runs[0].state);
        assert_eq!(after.runs[0].error_code, before.runs[0].error_code);
        assert_eq!(after.messages[1].status, before.messages[1].status);
        assert_eq!(
            after.messages[1].content_text,
            before.messages[1].content_text
        );
        assert_eq!(after.attempts.len(), before.attempts.len() + 1);
        assert_eq!(after.attempts[0].state, before.attempts[0].state);
        assert_eq!(after.attempts[1].ordinal, 2);
        assert_eq!(after.attempts[1].state, "streaming");

        let after_events = storage
            .with_connection(|connection| {
                let mut statement = connection.prepare(
                    "SELECT event_type FROM run_events
                     WHERE run_id = ?1 ORDER BY sequence_no",
                )?;
                let events = statement
                    .query_map(["run_55555555555555555555555555555555"], |row| {
                        row.get::<_, String>(0)
                    })?
                    .collect::<Result<Vec<_>, _>>()?;
                Ok(events)
            })
            .unwrap();
        assert_eq!(after_events, before_events);
        assert!(!after_events.iter().any(|event| event == "run.recovered"));
        assert!(!after_events.iter().any(|event| event == "run.failed"));
    }

    #[test]
    fn startup_recovery_rejects_a_run_without_an_active_attempt_atomically() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Missing recovery attempt provider");
        let conversation = storage
            .create_conversation(None, None)
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let (run_id, attempt_id, user_message_id, assistant_message_id) = test_run_ids('9');
        storage
            .prepare_conversation_run(NewConversationRun {
                conversation_id: &conversation_id,
                branch_id: &branch_id,
                run_id: &run_id,
                attempt_id: &attempt_id,
                user_message_id: &user_message_id,
                assistant_message_id: &assistant_message_id,
                prompt: "Do not infer a recoverable attempt",
                provider_profile_id: &provider.id,
                model_id: "missing-recovery-attempt-model",
                request_parameters_json: "{}",
            })
            .expect("run should prepare");
        {
            let connection = storage.lock().unwrap();
            connection
                .execute(
                    "UPDATE run_attempts
                     SET state = 'failed', error_code = 'test'
                     WHERE id = ?1",
                    [&attempt_id],
                )
                .unwrap();
        }
        let before = storage.get_conversation(&conversation_id).unwrap();
        let before_events = storage
            .with_connection(|connection| {
                let count: i64 = connection.query_row(
                    "SELECT COUNT(*) FROM run_events WHERE run_id = ?1",
                    [&run_id],
                    |row| row.get(0),
                )?;
                Ok(count)
            })
            .unwrap();

        let error = {
            let mut connection = storage.lock().unwrap();
            recover_incomplete_runs(&mut connection)
                .expect_err("a queued run without an active attempt must fail closed")
        };
        assert_eq!(error.code, "run_recovery_ambiguous");

        let after = storage.get_conversation(&conversation_id).unwrap();
        assert_eq!(after.runs[0].state, before.runs[0].state);
        assert_eq!(after.runs[0].error_code, before.runs[0].error_code);
        assert_eq!(after.messages[1].status, before.messages[1].status);
        assert_eq!(after.attempts[0].state, "failed");
        let after_events = storage
            .with_connection(|connection| {
                connection
                    .query_row(
                        "SELECT COUNT(*) FROM run_events WHERE run_id = ?1",
                        [&run_id],
                        |row| row.get::<_, i64>(0),
                    )
                    .map_err(NativeError::from)
            })
            .unwrap();
        assert_eq!(after_events, before_events);
    }

    #[test]
    fn file_backed_startup_recovery_survives_close_and_reopen() {
        let database_path = std::env::temp_dir().join(format!(
            "omnia-native-recovery-reopen-{}.sqlite",
            Uuid::new_v4().simple()
        ));
        let (conversation_id, run_id) = {
            let storage = Storage::open(database_path.clone()).expect("file storage should open");
            let provider = create_test_provider(&storage, "Recovery reopen provider");
            let conversation = storage
                .create_conversation(None, None)
                .expect("conversation should be created");
            let conversation_id = conversation.conversation.id.clone();
            let branch_id = conversation.conversation.active_branch_id.clone();
            let (run_id, attempt_id, user_message_id, assistant_message_id) = test_run_ids('8');
            let prepared = storage
                .prepare_conversation_run(NewConversationRun {
                    conversation_id: &conversation_id,
                    branch_id: &branch_id,
                    run_id: &run_id,
                    attempt_id: &attempt_id,
                    user_message_id: &user_message_id,
                    assistant_message_id: &assistant_message_id,
                    prompt: "Recover this run after a real close and reopen",
                    provider_profile_id: &provider.id,
                    model_id: "recovery-reopen-model",
                    request_parameters_json: "{}",
                })
                .expect("run should prepare");
            storage
                .mark_prepared_attempt_dispatching(&StartPreparedAttemptRequest {
                    attempt_id: prepared.provider_input.attempt_id,
                    frozen_provider_input_id: prepared.provider_input.id,
                })
                .expect("dispatch should start");
            storage
                .append_assistant_delta(&run_id, "Persisted partial before close")
                .expect("partial text should persist");
            (conversation_id, run_id)
        };

        {
            let reopened = Storage::open(database_path.clone()).expect("database should reopen");
            let snapshot = reopened
                .get_conversation(&conversation_id)
                .expect("conversation should reconstruct after recovery");
            assert_eq!(snapshot.runs.len(), 1);
            assert_eq!(snapshot.runs[0].id, run_id);
            assert_eq!(snapshot.runs[0].state, "failed");
            assert_eq!(
                snapshot.runs[0].error_code.as_deref(),
                Some("app_restarted")
            );
            assert_eq!(snapshot.attempts.len(), 1);
            assert_eq!(snapshot.attempts[0].state, "outcome_unknown");
            assert_eq!(snapshot.attempts[0].accepted_by_provider, "unknown");
            assert_eq!(snapshot.messages[1].status, "failed");
            assert_eq!(
                snapshot.messages[1].content_text,
                "Persisted partial before close"
            );

            let journal = reopened
                .read_run_journal(&ReadRunJournalRequest {
                    run_id: run_id.clone(),
                    journal_epoch: None,
                    after_sequence: None,
                    after_event_id: None,
                    through_sequence: None,
                    through_event_id: None,
                    limit: Some(1_000),
                })
                .expect("recovered journal should replay after reopen");
            assert!(journal.complete);
            assert_eq!(
                journal
                    .events
                    .iter()
                    .filter(|event| event.event_type == "run.recovered")
                    .count(),
                1
            );
            assert_eq!(
                journal
                    .events
                    .iter()
                    .filter(|event| event.event_type == "run.failed")
                    .count(),
                1
            );
        }

        let _ = fs::remove_file(&database_path);
        let _ = fs::remove_file(database_path.with_extension("sqlite-wal"));
        let _ = fs::remove_file(database_path.with_extension("sqlite-shm"));
    }

