    #[test]
    fn conversation_branch_fork_is_durable_and_can_preserve_active_branch() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = storage
            .save_provider_profile(NewProviderProfile {
                provider_type: "openai_compatible",
                display_name: "Branch provider",
                normalized_base_url: "https://api.example.com/v1",
                auth_scheme: "bearer",
                organization_id: None,
                remote_project_id: None,
                credential_ref: Some("provider_secret_0123456789abcdef0123456789abcdef"),
                local_network_grant: false,
            })
            .expect("provider should be created");
        let root = storage
            .create_conversation(None, None)
            .expect("conversation should be created");
        let conversation_id = root.conversation.id.clone();
        let root_branch_id = root.conversation.active_branch_id.clone();
        let prepared = storage
            .prepare_conversation_run(NewConversationRun {
                conversation_id: &conversation_id,
                branch_id: &root_branch_id,
                run_id: "run_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                attempt_id: "attempt_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                user_message_id: "message_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                assistant_message_id: "message_bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
                prompt: "Root question",
                provider_profile_id: &provider.id,
                model_id: "branch-model",
                request_parameters_json: "{}",
            })
            .expect("root run should prepare");
        storage
            .fail_run("run_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", "test_complete")
            .expect("test run should terminalize");

        let forked = storage
            .fork_conversation_branch(
                &conversation_id,
                &root_branch_id,
                "message_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                Some("Investigation branch"),
                false,
            )
            .expect("branch should fork");
        assert_eq!(forked.conversation.active_branch_id, root_branch_id);
        let child = forked
            .branches
            .iter()
            .find(|branch| branch.parent_branch_id.as_deref() == Some(root_branch_id.as_str()))
            .expect("child branch should be durable");
        assert_eq!(
            child.forked_from_message_id.as_deref(),
            Some("message_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
        );
        assert_eq!(child.name.as_deref(), Some("Investigation branch"));

        let reloaded = storage
            .get_conversation(&conversation_id)
            .expect("conversation should reload");
        assert!(reloaded.branches.iter().any(|branch| branch.id == child.id));

        let activated = storage
            .fork_conversation_branch(
                &conversation_id,
                &child.id,
                "message_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                None,
                true,
            )
            .expect("inherited fork point should be accepted");
        assert_ne!(activated.conversation.active_branch_id, root_branch_id);
        assert_eq!(
            activated.conversation.active_branch_id,
            activated.branches.last().unwrap().id
        );
        assert_eq!(prepared.provider_input.model, "branch-model");
    }

