    #[test]
    fn prepared_dispatch_proof_loads_matching_profile_and_definition_without_leaking_credential() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Dispatch proof provider");
        let (_conversation_id, prepared) =
            prepare_test_run(&storage, &provider.id, '0', "Proof snapshot request");
        let request = StartPreparedAttemptRequest {
            attempt_id: prepared.provider_input.attempt_id.clone(),
            frozen_provider_input_id: prepared.provider_input.id.clone(),
        };

        let (input, proof) = storage
            .load_prepared_provider_dispatch_proof(&request)
            .expect("dispatch proof should load from one storage snapshot");
        assert_eq!(input.id, request.frozen_provider_input_id);
        assert_eq!(input.attempt_id, request.attempt_id);
        assert_eq!(proof.profile.id, provider.id);
        assert_eq!(proof.profile.provider_type, "openai_compatible");
        assert_eq!(
            proof.profile.normalized_base_url,
            "https://api.example.com/v1"
        );
        assert_eq!(
            proof.frozen_definition.provider_profile_id,
            proof.profile.id
        );
        assert_eq!(
            proof.frozen_definition.credential_ref.as_deref(),
            Some("provider_secret_0123456789abcdef0123456789abcdef")
        );

        // The renderer-safe profile is serializable, but the opaque credential
        // handle is intentionally absent. Native debug output is redacted too.
        let profile_json = serde_json::to_string(&proof.profile).expect("profile should serialize");
        assert!(!profile_json.contains("provider_secret_"));
        let definition_debug = format!("{:?}", proof.frozen_definition);
        assert!(!definition_debug.contains("provider_secret_"));
        assert!(definition_debug.contains("credential_bound: true"));
    }

