    #[test]
    fn historical_provider_lineage_read_is_owned_redacted_and_survives_profile_deletion() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Historical lineage provider");
        let (conversation_id, prepared) = prepare_test_run(
            &storage,
            &provider.id,
            '0',
            "Private prompt must stay outside the receipt",
        );
        let request = ReadProviderAttemptLineageRequest {
            conversation_id: conversation_id.clone(),
            branch_id: prepared.conversation.conversation.active_branch_id.clone(),
            run_id: prepared.provider_input.run_id.clone(),
            attempt_id: prepared.provider_input.attempt_id.clone(),
        };
        let receipt = storage
            .read_provider_attempt_lineage(&request)
            .expect("owned attempt lineage should be readable");
        assert_eq!(receipt.frozen_provider_input_id, prepared.provider_input.id);
        assert_eq!(receipt.provider_profile_id, provider.id);
        assert_eq!(receipt.model_id, "prepared-model");
        assert_eq!(receipt.created_at_ms, prepared.provider_input.created_at_ms);

        let serialized = serde_json::to_string(&receipt).expect("receipt should serialize");
        for forbidden in [
            "Private prompt must stay outside the receipt",
            "https://api.example.com",
            "provider_secret_",
            "credentialRef",
            "messagesJson",
            "parametersJson",
        ] {
            assert!(
                !serialized.contains(forbidden),
                "receipt must omit {forbidden}"
            );
        }

        storage
            .delete_provider_profile(&provider.id)
            .expect("provider deletion should revoke future dispatch");
        assert_eq!(
            storage
                .read_provider_attempt_lineage(&request)
                .expect("historical receipt must outlive provider deletion"),
            receipt,
        );
        let dispatch = StartPreparedAttemptRequest {
            attempt_id: request.attempt_id,
            frozen_provider_input_id: receipt.frozen_provider_input_id,
        };
        assert!(storage
            .load_prepared_provider_dispatch_proof(&dispatch)
            .is_err());
    }

