    #[test]
    fn prepared_lineage_persists_cache_policy_plan_and_hash_material() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Cache lineage provider");
        let parameters =
            cache_policy_parameters("cache_policy_storage_test", "cache_revision_storage_test");
        let (_conversation_id, cached) = prepare_test_run_with_parameters(
            &storage,
            &provider.id,
            'a',
            "Cache lineage request",
            &parameters,
        );
        let request = StartPreparedAttemptRequest {
            attempt_id: cached.provider_input.attempt_id.clone(),
            frozen_provider_input_id: cached.provider_input.id.clone(),
        };

        let (cache_revision, cache_plan, lineage_hash): (Option<String>, Option<String>, String) =
            storage
                .with_connection(|connection| {
                    connection
                        .query_row(
                            "SELECT cache_policy_revision_id, cache_plan_id, lineage_sha256
                         FROM provider_attempt_lineage_facts
                         WHERE frozen_provider_input_id = ?1",
                            [&request.frozen_provider_input_id],
                            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
                        )
                        .map_err(Into::into)
                })
                .expect("cache lineage columns should be readable");
        assert_eq!(
            cache_revision.as_deref(),
            Some("cache_revision_storage_test")
        );
        assert!(cache_plan
            .as_deref()
            .is_some_and(|plan| plan.starts_with("cache_plan_")));
        assert_eq!(lineage_hash.len(), 64);

        let mut cleared = storage
            .with_connection(|connection| {
                load_provider_attempt_lineage_fact(connection, &request.frozen_provider_input_id)
            })
            .expect("cache lineage fact should load");
        cleared.cache_policy_revision_id = None;
        cleared.cache_plan_id = None;
        let cleared_hash = cleared
            .compute_lineage_hash()
            .expect("cleared cache lineage should hash");
        assert_ne!(lineage_hash, cleared_hash);

        let (_conversation_id, uncached) =
            prepare_test_run(&storage, &provider.id, 'b', "No cache lineage request");
        let (uncached_revision, uncached_plan): (Option<String>, Option<String>) = storage
            .with_connection(|connection| {
                connection
                    .query_row(
                        "SELECT cache_policy_revision_id, cache_plan_id
                         FROM provider_attempt_lineage_facts
                         WHERE frozen_provider_input_id = ?1",
                        [&uncached.provider_input.id],
                        |row| Ok((row.get(0)?, row.get(1)?)),
                    )
                    .map_err(Into::into)
            })
            .expect("uncached lineage columns should be readable");
        assert_eq!(uncached_revision, None);
        assert_eq!(uncached_plan, None);
    }

