    #[test]
    fn prepared_dispatch_proof_rejects_lineage_parameter_and_effort_drift() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Lineage drift provider");
        let (_conversation_id, prepared) =
            prepare_test_run(&storage, &provider.id, '4', "Lineage drift request");
        let request = StartPreparedAttemptRequest {
            attempt_id: prepared.provider_input.attempt_id,
            frozen_provider_input_id: prepared.provider_input.id.clone(),
        };

        // A validly rehashed lineage row with a changed parameter digest must
        // still be rejected against the immutable frozen input.
        storage
            .with_connection(|connection| {
                connection.execute(
                    "DROP TRIGGER provider_attempt_lineage_facts_immutable_update",
                    [],
                )?;
                let mut fact = load_provider_attempt_lineage_fact(
                    connection,
                    &request.frozen_provider_input_id,
                )?;
                fact.resolved_parameters_sha256 = sha256_hex(b"tampered-parameters");
                fact.lineage_sha256 = fact.compute_lineage_hash()?;
                connection.execute(
                    "UPDATE provider_attempt_lineage_facts
                     SET resolved_parameters_sha256 = ?1, lineage_sha256 = ?2
                     WHERE frozen_provider_input_id = ?3",
                    params![
                        fact.resolved_parameters_sha256,
                        fact.lineage_sha256,
                        request.frozen_provider_input_id,
                    ],
                )?;
                Ok(())
            })
            .expect("test fixture should rehash a parameter-drift lineage fact");
        let parameter_error = storage
            .load_prepared_provider_dispatch_proof(&request)
            .expect_err("parameter digest drift must fail before dispatch");
        assert_eq!(
            parameter_error.code,
            "provider_attempt_lineage_parameters_changed"
        );

        // Use a fresh run so the first tamper cannot mask effort provenance.
        let (_conversation_id, effort_prepared) =
            prepare_test_run(&storage, &provider.id, '5', "Effort drift request");
        let effort_request = StartPreparedAttemptRequest {
            attempt_id: effort_prepared.provider_input.attempt_id,
            frozen_provider_input_id: effort_prepared.provider_input.id.clone(),
        };
        storage
            .with_connection(|connection| {
                let mut fact = load_provider_attempt_lineage_fact(
                    connection,
                    &effort_request.frozen_provider_input_id,
                )?;
                fact.requested_effort = Some("deep".to_owned());
                fact.lineage_sha256 = fact.compute_lineage_hash()?;
                connection.execute(
                    "UPDATE provider_attempt_lineage_facts
                     SET requested_effort = ?1, lineage_sha256 = ?2
                     WHERE frozen_provider_input_id = ?3",
                    params![
                        fact.requested_effort,
                        fact.lineage_sha256,
                        effort_request.frozen_provider_input_id,
                    ],
                )?;
                Ok(())
            })
            .expect("test fixture should rehash an effort-drift lineage fact");
        let effort_error = storage
            .load_prepared_provider_dispatch_proof(&effort_request)
            .expect_err("effort provenance drift must fail before dispatch");
        assert_eq!(
            effort_error.code,
            "provider_attempt_lineage_parameters_changed"
        );
    }

