    #[test]
    fn prepared_dispatch_binds_exact_receipt_and_rejects_replay() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Exact receipt provider");
        let (conversation_a_id, prepared_a) =
            prepare_test_run(&storage, &provider.id, '2', "First request");
        let (conversation_b_id, prepared_b) =
            prepare_test_run(&storage, &provider.id, '3', "Second request");
        let request_a = StartPreparedAttemptRequest {
            attempt_id: prepared_a.provider_input.attempt_id.clone(),
            frozen_provider_input_id: prepared_a.provider_input.id.clone(),
        };
        let mismatched = StartPreparedAttemptRequest {
            attempt_id: prepared_b.provider_input.attempt_id.clone(),
            frozen_provider_input_id: prepared_a.provider_input.id.clone(),
        };

        let error = storage
            .load_prepared_provider_input(&mismatched)
            .expect_err("cross-attempt receipt must fail closed");
        assert_eq!(error.code, "prepared_input_not_dispatchable");
        assert_eq!(
            storage.get_conversation(&conversation_a_id).unwrap().runs[0].state,
            "queued"
        );
        assert_eq!(
            storage.get_conversation(&conversation_b_id).unwrap().runs[0].state,
            "queued"
        );

        storage
            .mark_prepared_attempt_dispatching(&request_a)
            .expect("exact receipt should dispatch once");
        let first = storage.get_conversation(&conversation_a_id).unwrap();
        assert_eq!(first.runs[0].state, "running");
        assert_eq!(first.attempts[0].state, "dispatching");
        let dispatch_started: Option<i64> = storage
            .lock()
            .unwrap()
            .query_row(
                "SELECT dispatch_started_at_ms FROM frozen_provider_inputs WHERE id = ?1",
                [&request_a.frozen_provider_input_id],
                |row| row.get(0),
            )
            .unwrap();
        assert!(dispatch_started.is_some());

        let replay = storage.mark_prepared_attempt_dispatching(&request_a);
        assert!(replay.is_err());
        let after_replay = storage.get_conversation(&conversation_a_id).unwrap();
        assert_eq!(after_replay.runs[0].state, "running");
        assert_eq!(after_replay.attempts[0].state, "dispatching");
    }

