    #[test]
    fn prepared_input_omits_failed_cancelled_and_sibling_history() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Filtered history provider");
        let conversation = storage.create_conversation(None, None).unwrap();
        let conversation_id = conversation.conversation.id.clone();
        let root_branch_id = conversation.conversation.active_branch_id.clone();
        let sibling_branch_id = "branch_11111111111111111111111111111111";
        let now = now_ms();
        {
            let connection = storage.lock().unwrap();
            insert_history_message(
                &connection,
                "message_11111111111111111111111111111111",
                &conversation_id,
                &root_branch_id,
                None,
                "user",
                "complete",
                0,
                "visible root",
                now,
            );
            insert_history_message(
                &connection,
                "message_22222222222222222222222222222222",
                &conversation_id,
                &root_branch_id,
                Some("message_11111111111111111111111111111111"),
                "assistant",
                "failed",
                1,
                "failed output",
                now,
            );
            insert_history_message(
                &connection,
                "message_33333333333333333333333333333333",
                &conversation_id,
                &root_branch_id,
                Some("message_22222222222222222222222222222222"),
                "assistant",
                "cancelled",
                2,
                "cancelled output",
                now,
            );
            insert_test_branch(
                &connection,
                sibling_branch_id,
                &conversation_id,
                Some(&root_branch_id),
                Some("message_11111111111111111111111111111111"),
                now,
            );
            insert_history_message(
                &connection,
                "message_44444444444444444444444444444444",
                &conversation_id,
                sibling_branch_id,
                Some("message_11111111111111111111111111111111"),
                "user",
                "complete",
                0,
                "sibling only",
                now,
            );
        }

        let prepared = prepare_branch_run(
            &storage,
            &provider.id,
            &conversation_id,
            &root_branch_id,
            'f',
            "current prompt",
        )
        .expect("filtered branch history should prepare");
        let request = StartPreparedAttemptRequest {
            attempt_id: prepared.provider_input.attempt_id,
            frozen_provider_input_id: prepared.provider_input.id,
        };
        let frozen = storage.load_prepared_provider_input(&request).unwrap();
        let contents = frozen
            .messages
            .iter()
            .map(|message| message.content.as_str())
            .collect::<Vec<_>>();

        assert_eq!(contents, vec!["visible root", "current prompt"]);
        assert!(!contents.contains(&"failed output"));
        assert!(!contents.contains(&"cancelled output"));
        assert!(!contents.contains(&"sibling only"));
        let current_user_message = prepared
            .conversation
            .messages
            .iter()
            .find(|message| message.content_text == "current prompt")
            .expect("the prepared user message should exist");
        assert_eq!(
            current_user_message.parent_message_id.as_deref(),
            Some("message_11111111111111111111111111111111")
        );
    }

    #[test]
    fn frozen_provider_input_body_is_immutable_and_hash_is_revalidated() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Integrity provider");
        let (_conversation_id, prepared) =
            prepare_test_run(&storage, &provider.id, '5', "Integrity protected");
        let request = StartPreparedAttemptRequest {
            attempt_id: prepared.provider_input.attempt_id.clone(),
            frozen_provider_input_id: prepared.provider_input.id.clone(),
        };
        {
            let connection = storage.lock().unwrap();
            let mutation = connection.execute(
                "UPDATE frozen_provider_inputs SET parameters_json = '{\"temperature\":1}'
                 WHERE id = ?1",
                [&request.frozen_provider_input_id],
            );
            assert!(mutation.is_err());
            connection
                .execute("DROP TRIGGER frozen_provider_inputs_body_immutable", [])
                .unwrap();
            connection
                .execute(
                    "UPDATE frozen_provider_inputs SET content_sha256 = ?1 WHERE id = ?2",
                    params!["0".repeat(64), request.frozen_provider_input_id],
                )
                .unwrap();
        }

        let error = storage
            .load_prepared_provider_input(&request)
            .expect_err("hash tampering should fail closed");
        assert_eq!(error.code, "prepared_input_integrity_failed");
    }

    #[test]
    fn legacy_run_helpers_materialize_an_ordered_durable_journal() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Journal integration provider");
        let (_conversation_id, prepared) =
            prepare_test_run(&storage, &provider.id, '6', "Journal integration prompt");
        let request = StartPreparedAttemptRequest {
            attempt_id: prepared.provider_input.attempt_id.clone(),
            frozen_provider_input_id: prepared.provider_input.id.clone(),
        };

        storage
            .mark_prepared_attempt_dispatching(&request)
            .expect("dispatch transition should be durable");
        // The compatibility helper must promote the exact dispatching attempt
        // through the journal before persisting the first provider fact.
        storage
            .append_assistant_delta("run_66666666666666666666666666666666", "hello")
            .expect("assistant delta should be durable");
        storage
            .update_run_usage(
                "run_66666666666666666666666666666666",
                Some(17),
                Some(8),
                Some(3),
                Some(2),
            )
            .expect("usage should be durable");
        storage
            .complete_run("run_66666666666666666666666666666666", "stop")
            .expect("terminal transition should be durable");

        let page = storage
            .read_run_journal(&ReadRunJournalRequest {
                run_id: "run_66666666666666666666666666666666".into(),
                journal_epoch: None,
                after_sequence: None,
                after_event_id: None,
                through_sequence: None,
                through_event_id: None,
                limit: Some(1_000),
            })
            .expect("journal should replay");
        let event_types = page
            .events
            .iter()
            .map(|event| event.event_type.as_str())
            .collect::<Vec<_>>();
        assert_eq!(
            event_types,
            vec![
                "run.created",
                "attempt.created",
                "run.dispatching",
                "attempt.dispatch_started",
                "attempt.accepted",
                "run.started",
                "message.text_delta",
                "usage.updated",
                "attempt.completed",
                "run.completed",
            ]
        );
        assert!(page.complete);
        assert!(page
            .events
            .windows(2)
            .all(|events| events[1].sequence == events[0].sequence + 1));
        assert_eq!(
            page.events
                .iter()
                .filter(|event| event.event_type == "run.completed")
                .count(),
            1
        );

        let snapshot = storage
            .get_conversation(&prepared.conversation.conversation.id)
            .expect("conversation should remain readable");
        assert_eq!(snapshot.messages[1].content_text, "hello");
        assert_eq!(snapshot.messages[1].status, "complete");
        assert_eq!(snapshot.runs[0].state, "complete");
        assert_eq!(snapshot.attempts[0].state, "complete");

        let connection = storage.lock().unwrap();
        let usage: (Option<i64>, Option<i64>, Option<i64>, Option<i64>) = connection
            .query_row(
                "SELECT input_tokens, output_tokens, cached_tokens, reasoning_tokens
                 FROM messages WHERE id = ?1",
                [&prepared.conversation.messages[1].id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .expect("usage projection should be readable");
        assert_eq!(usage, (Some(17), Some(8), Some(3), Some(2)));
        drop(connection);

        // The compatibility projection is not the accounting source. Provider
        // stream usage must also have one immutable, attempt-scoped ledger row
        // and the matching lifecycle event must point back to that row.
        let ledger = storage
            .list_usage_ledger(
                "run_66666666666666666666666666666666",
                Some("attempt_66666666666666666666666666666666"),
            )
            .expect("usage ledger should be readable");
        assert_eq!(ledger.len(), 1);
        let usage_entry = &ledger[0];
        assert_eq!(usage_entry.source, "provider-incremental");
        assert!(!usage_entry.authoritative);
        assert_eq!(usage_entry.coverage, "partial");
        assert_eq!(usage_entry.sequence, 1);
        assert_eq!(usage_entry.counters.input_tokens, Some(17));
        assert_eq!(usage_entry.counters.cache_read_input_tokens, Some(3));
        assert_eq!(usage_entry.counters.cache_write_input_tokens, None);
        assert_eq!(usage_entry.counters.output_tokens, Some(8));
        assert_eq!(usage_entry.counters.reasoning_tokens, Some(2));
        assert_eq!(usage_entry.counters.visible_output_tokens, None);
        assert_eq!(
            usage_entry.response_identity_hash.as_deref().map(str::len),
            Some(64)
        );

        let usage_event = page
            .events
            .iter()
            .find(|event| event.event_type == "usage.updated")
            .expect("the ledger observation should be represented in the journal");
        assert_eq!(
            usage_event
                .payload
                .get("usageEntryId")
                .and_then(serde_json::Value::as_str),
            Some(usage_entry.id.as_str())
        );
    }

    #[test]
    fn run_telemetry_read_is_attempt_scoped_bounded_and_content_free() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Telemetry read provider");
        let (conversation_id, prepared) = prepare_test_run(
            &storage,
            &provider.id,
            '9',
            "Do not expose this telemetry prompt",
        );
        let request = StartPreparedAttemptRequest {
            attempt_id: prepared.provider_input.attempt_id.clone(),
            frozen_provider_input_id: prepared.provider_input.id.clone(),
        };
        let run_id = "run_99999999999999999999999999999999";
        let attempt_id = "attempt_99999999999999999999999999999999";

        storage
            .mark_prepared_attempt_dispatching(&request)
            .expect("dispatch transition should be durable");
        storage
            .append_assistant_delta(run_id, "Do not expose this assistant response")
            .expect("assistant delta should be durable");
        storage
            .update_run_usage(run_id, Some(21), Some(13), Some(5), Some(3))
            .expect("usage observation should be durable");
        storage
            .complete_run(run_id, "stop")
            .expect("terminal transition should be durable");

        let telemetry = storage
            .read_run_telemetry(&crate::telemetry::ReadRunTelemetryRequest {
                run_id: run_id.into(),
                attempt_id: Some(attempt_id.into()),
            })
            .expect("owned attempt telemetry should be readable");
        assert_eq!(telemetry.run_id, run_id);
        assert_eq!(telemetry.attempts.len(), 1);
        let attempt = &telemetry.attempts[0];
        assert_eq!(attempt.attempt_id, attempt_id);
        assert_eq!(attempt.model_id, "prepared-model");
        assert_eq!(attempt.state, "complete");
        assert_eq!(attempt.accepted_by_provider, "true");
        assert!(attempt.timing_observations.is_empty());
        assert_eq!(attempt.usage_ledger.len(), 1);
        let usage = &attempt.usage_ledger[0];
        assert_eq!(usage.source, "provider-incremental");
        assert!(!usage.authoritative);
        assert_eq!(usage.coverage, "partial");
        assert_eq!(usage.counters.input_tokens, Some(21));
        assert_eq!(usage.counters.cache_read_input_tokens, Some(5));
        assert_eq!(usage.counters.cache_write_input_tokens, None);
        assert_eq!(usage.counters.output_tokens, Some(13));
        assert_eq!(usage.counters.reasoning_tokens, Some(3));
        assert_eq!(usage.counters.visible_output_tokens, None);
        assert_eq!(usage.cost_statement_count, 0);

        let serialized = serde_json::to_string(&telemetry).expect("telemetry should serialize");
        for forbidden in [
            "Do not expose this telemetry prompt",
            "Do not expose this assistant response",
            "remoteRequestId",
            "responseIdentityHash",
            "journalEvent",
            "profileId",
            "providerCounters",
            "priceSnapshot",
            "formulaVersion",
            "supersedesEntryId",
        ] {
            assert!(
                !serialized.contains(forbidden),
                "renderer telemetry must structurally omit {forbidden}",
            );
        }

        let (_other_conversation_id, other_prepared) = prepare_test_run(
            &storage,
            &provider.id,
            'a',
            "Second run proves exact attempt lineage",
        );
        let mismatch = storage
            .read_run_telemetry(&crate::telemetry::ReadRunTelemetryRequest {
                run_id: run_id.into(),
                attempt_id: Some(other_prepared.provider_input.attempt_id),
            })
            .expect_err("an attempt from another run must fail closed");
        assert_eq!(mismatch.code, "telemetry_scope_denied");

        let snapshot = storage
            .get_conversation(&conversation_id)
            .expect("original conversation should remain readable");
        assert_eq!(snapshot.runs[0].id, run_id);
    }

    #[test]
    fn outcome_unknown_failure_is_distinct_and_terminal_in_the_journal() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let provider = create_test_provider(&storage, "Outcome-unknown provider");
        let (conversation_id, prepared) =
            prepare_test_run(&storage, &provider.id, '7', "Outcome unknown prompt");
        let request = StartPreparedAttemptRequest {
            attempt_id: prepared.provider_input.attempt_id.clone(),
            frozen_provider_input_id: prepared.provider_input.id.clone(),
        };

        storage
            .mark_prepared_attempt_dispatching(&request)
            .expect("dispatch transition should be durable");
        storage
            .fail_run_with_evidence(
                "run_77777777777777777777777777777777",
                "gateway_timeout",
                ProviderAttemptFailureEvidence::OutcomeUnknown {
                    acceptance: ProviderAcceptanceEvidence::Unknown,
                },
            )
            .expect("outcome-unknown terminalization should be durable");

        let page = storage
            .read_run_journal(&ReadRunJournalRequest {
                run_id: "run_77777777777777777777777777777777".into(),
                journal_epoch: None,
                after_sequence: None,
                after_event_id: None,
                through_sequence: None,
                through_event_id: None,
                limit: Some(1_000),
            })
            .expect("journal should replay");
        let event_types = page
            .events
            .iter()
            .map(|event| event.event_type.as_str())
            .collect::<Vec<_>>();
        assert_eq!(
            event_types,
            vec![
                "run.created",
                "attempt.created",
                "run.dispatching",
                "attempt.dispatch_started",
                "attempt.outcome_unknown",
                "run.failed",
            ]
        );
        assert!(page.complete);
        let terminal_count = page
            .events
            .iter()
            .filter(|event| {
                matches!(
                    event.event_type.as_str(),
                    "run.completed" | "run.cancelled" | "run.failed"
                )
            })
            .count();
        assert_eq!(terminal_count, 1);

        let snapshot = storage
            .get_conversation(&conversation_id)
            .expect("conversation should remain readable");
        assert_eq!(snapshot.runs[0].state, "failed");
        assert_eq!(
            snapshot.runs[0].error_code.as_deref(),
            Some("gateway_timeout")
        );
        assert_eq!(snapshot.attempts[0].state, "outcome_unknown");
        assert_eq!(snapshot.attempts[0].accepted_by_provider, "unknown");
    }

    #[test]
    fn state_cursor_authority_accepts_exact_branch_fact_and_rejects_later_watermark() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("State cursor authority"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let root = append_current_state_root(
            &storage,
            &conversation_id,
            &branch_id,
            "cursor-authority-root",
        );
        let sequence = root
            .journal_sequence
            .expect("the fresh state revision should have a journal sequence");
        let cursor = RunControlCursor {
            stream_kind: RunControlStreamKind::Branch,
            stream_id: root.stream_id.clone(),
            journal_epoch: root.journal_epoch.clone(),
            sequence,
            event_id: root.journal_event_id.clone(),
            payload_hash: None,
        };

        let resolved = storage
            .with_transaction(|transaction| {
                resolve_cursor_authority(
                    transaction,
                    &cursor,
                    CursorAuthorityScope {
                        conversation_id: &conversation_id,
                        branch_id: &branch_id,
                        run_id: None,
                    },
                    CursorFixedWatermark {
                        branch_sequence: Some(sequence),
                        run_sequence: None,
                    },
                )
            })
            .expect("the exact branch cursor should resolve");
        assert_eq!(resolved.stream_kind, RunControlStreamKind::Branch);
        assert_eq!(resolved.stream_id, root.stream_id);
        assert_eq!(resolved.sequence, sequence);
        assert_eq!(
            resolved.event_id,
            cursor.event_id.clone().expect("event id should exist")
        );
        assert_eq!(resolved.revision_id, root.revision_id);

        let error = storage
            .with_transaction(|transaction| {
                resolve_cursor_authority(
                    transaction,
                    &cursor,
                    CursorAuthorityScope {
                        conversation_id: &conversation_id,
                        branch_id: &branch_id,
                        run_id: None,
                    },
                    CursorFixedWatermark {
                        branch_sequence: Some(sequence - 1),
                        run_sequence: None,
                    },
                )
            })
            .expect_err("a branch cursor above the fixed watermark must fail closed");
        assert_cursor_authority_error(&error, "cursor_above_fixed_watermark");
    }

