    #[test]
    fn state_cursor_authority_rejects_wrong_scope_epoch_hash_and_unsupported_stream() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let first = storage
            .create_conversation(None, Some("Cursor scope A"))
            .expect("first conversation should be created");
        let second = storage
            .create_conversation(None, Some("Cursor scope B"))
            .expect("second conversation should be created");
        let first_conversation_id = first.conversation.id.clone();
        let first_branch_id = first.conversation.active_branch_id.clone();
        let second_conversation_id = second.conversation.id.clone();
        let second_branch_id = second.conversation.active_branch_id.clone();
        let first_root = append_current_state_root(
            &storage,
            &first_conversation_id,
            &first_branch_id,
            "cursor-scope-root-a",
        );
        let second_root = append_current_state_root(
            &storage,
            &second_conversation_id,
            &second_branch_id,
            "cursor-scope-root-b",
        );
        let sequence = first_root
            .journal_sequence
            .expect("first root should have a journal sequence");
        let event_id = first_root
            .journal_event_id
            .clone()
            .expect("first root should have a journal event");
        let epoch = first_root
            .journal_epoch
            .clone()
            .expect("first root should have a journal epoch");
        let cursor = RunControlCursor {
            stream_kind: RunControlStreamKind::Branch,
            stream_id: first_root.stream_id.clone(),
            journal_epoch: Some(epoch),
            sequence,
            event_id: Some(event_id),
            payload_hash: None,
        };

        let wrong_scope = storage
            .with_transaction(|transaction| {
                resolve_cursor_authority(
                    transaction,
                    &cursor,
                    CursorAuthorityScope {
                        conversation_id: &second_conversation_id,
                        branch_id: &second_branch_id,
                        run_id: None,
                    },
                    CursorFixedWatermark {
                        branch_sequence: second_root.journal_sequence,
                        run_sequence: None,
                    },
                )
            })
            .expect_err("a cursor from another branch must fail closed");
        assert_cursor_authority_error(&wrong_scope, "cursor_scope_conflict");

        let mut wrong_epoch_cursor = cursor.clone();
        wrong_epoch_cursor.journal_epoch = Some("wrong-epoch".to_owned());
        let wrong_epoch = storage
            .with_transaction(|transaction| {
                resolve_cursor_authority(
                    transaction,
                    &wrong_epoch_cursor,
                    CursorAuthorityScope {
                        conversation_id: &first_conversation_id,
                        branch_id: &first_branch_id,
                        run_id: None,
                    },
                    CursorFixedWatermark {
                        branch_sequence: Some(sequence),
                        run_sequence: None,
                    },
                )
            })
            .expect_err("a cursor with the wrong epoch must fail closed");
        assert_cursor_authority_error(&wrong_epoch, "cursor_epoch_mismatch");

        let mut wrong_hash_cursor = cursor.clone();
        wrong_hash_cursor.payload_hash = Some("0".repeat(64));
        let wrong_hash = storage
            .with_transaction(|transaction| {
                resolve_cursor_authority(
                    transaction,
                    &wrong_hash_cursor,
                    CursorAuthorityScope {
                        conversation_id: &first_conversation_id,
                        branch_id: &first_branch_id,
                        run_id: None,
                    },
                    CursorFixedWatermark {
                        branch_sequence: Some(sequence),
                        run_sequence: None,
                    },
                )
            })
            .expect_err("a cursor with the wrong payload hash must fail closed");
        assert_cursor_authority_error(&wrong_hash, "cursor_payload_hash_mismatch");

        let unsupported = RunControlCursor {
            stream_kind: RunControlStreamKind::Conversation,
            stream_id: first_conversation_id.clone(),
            journal_epoch: None,
            sequence: 1,
            event_id: None,
            payload_hash: None,
        };
        let unsupported_error = storage
            .with_transaction(|transaction| {
                resolve_cursor_authority(
                    transaction,
                    &unsupported,
                    CursorAuthorityScope {
                        conversation_id: &first_conversation_id,
                        branch_id: &first_branch_id,
                        run_id: None,
                    },
                    CursorFixedWatermark::default(),
                )
            })
            .expect_err("unsupported cursor streams must fail closed");
        assert_cursor_authority_error(&unsupported_error, "unsupported_cursor_stream");
    }

