        let first_root = storage
            .append_state_revision(state_revision_request(
                &first_conversation_id,
                &first_branch_id,
                "root",
                "accepted",
                None,
                "cross-stream-first-root",
                Vec::new(),
            ))
            .expect("first root should append");
        let first_root_id = first_root
            .revision_id
            .clone()
            .expect("first root id should exist");
        let second_root = storage
            .append_state_revision(state_revision_request(
                &second_conversation_id,
                &second_branch_id,
                "root",
                "accepted",
                None,
                "cross-stream-second-root",
                Vec::new(),
            ))
            .expect("second root should append");
