    #[test]
    fn state_revision_validates_parent_arity_and_root_uniqueness() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("State revision validation"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();

        let root = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "root",
                "accepted",
                None,
                "validation-root",
                Vec::new(),
            ))
            .expect("root revision should append");
        let root_id = root
            .revision_id
            .clone()
            .expect("root revision id should exist");
        let before = state_revision_counts(&storage, &root.stream_id);

        let root_with_parent = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "root",
                "accepted",
                Some(&root_id),
                "validation-root-parent",
                vec![root_id.clone()],
            ))
            .expect_err("root revisions cannot declare parents");
        assert_eq!(root_with_parent.code, "invalid_input");
        assert_eq!(state_revision_counts(&storage, &root.stream_id), before);

        let second_root = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "root",
                "accepted",
                Some(&root_id),
                "validation-second-root",
                Vec::new(),
            ))
            .expect_err("a stream can contain only one root fact");
        assert_eq!(second_root.code, "invalid_state_base");
        assert_eq!(state_revision_counts(&storage, &root.stream_id), before);

        let merge_one_parent = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "merge",
                "accepted",
                Some(&root_id),
                "validation-merge-one-parent",
                vec![root_id.clone()],
            ))
            .expect_err("a merge requires at least two parents");
        assert_eq!(merge_one_parent.code, "invalid_input");
        assert_eq!(state_revision_counts(&storage, &root.stream_id), before);
    }

    #[test]
    fn state_revision_merge_preserves_multiple_parent_lineage() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("State revision merge"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();

        let root = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "root",
                "accepted",
                None,
                "merge-root",
                Vec::new(),
            ))
            .expect("root revision should append");
        let root_id = root
            .revision_id
            .clone()
            .expect("root revision id should exist");
        let first_candidate = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "branch",
                "candidate",
                Some(&root_id),
                "merge-first-candidate",
                vec![root_id.clone()],
            ))
            .expect("first candidate should append");
        let first_id = first_candidate
            .revision_id
            .expect("first candidate id should exist");
        let second_candidate = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "branch",
                "candidate",
                Some(&root_id),
                "merge-second-candidate",
                vec![root_id.clone()],
            ))
            .expect("second candidate should append");
        let second_id = second_candidate
            .revision_id
            .expect("second candidate id should exist");

        let merge = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "merge",
                "accepted",
                // The candidates are immutable, non-accepted facts.  Their
                // creation must not move the accepted head, so the merge CAS
                // expectation remains the root accepted revision.
                Some(&root_id),
                "merge-accepted",
                vec![first_id.clone(), second_id.clone()],
            ))
            .expect("merge with two parents should append");
        let merge_id = merge.revision_id.expect("merge revision id should exist");
        assert_eq!(merge.outcome, "applied");
        assert_eq!(
            merge.accepted_head_state_revision_id.as_deref(),
            Some(merge_id.as_str())
        );
        assert_eq!(merge.branch_sequence, 3);

        let graph = storage
            .read_state_revision_graph(&conversation_id, &branch_id, None)
            .expect("merged graph should be readable");
        let merge_projection = graph
            .revisions
            .iter()
            .find(|revision| revision.id == merge_id)
            .expect("merged revision should be projected");
        assert_eq!(
            merge_projection.parent_state_revision_ids,
            vec![first_id, second_id]
        );
        assert_eq!(
            graph.accepted_head_state_revision_id.as_deref(),
            Some(merge_id.as_str())
        );
    }

