    #[test]
    fn state_revision_candidate_root_blocks_a_second_root() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("State revision candidate root"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();

        let candidate_root = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "root",
                "candidate",
                None,
                "candidate-root",
                Vec::new(),
            ))
            .expect("candidate root should append as an immutable fact");
        let candidate_root_id = candidate_root
            .revision_id
            .clone()
            .expect("candidate root revision id should be returned");
        assert_eq!(candidate_root.accepted_head_state_revision_id, None);

        let candidate_child = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "checkpoint",
                "candidate",
                None,
                "candidate-root-child",
                vec![candidate_root_id.clone()],
            ))
            .expect("candidate child should append without an accepted head");
        assert_eq!(candidate_child.branch_sequence, 1);
        assert_eq!(candidate_child.accepted_head_state_revision_id, None);
        let before = state_revision_counts(&storage, &candidate_root.stream_id);

        let second_root = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "root",
                "accepted",
                None,
                "candidate-root-second",
                Vec::new(),
            ))
            .expect_err("a candidate root still reserves the stream root slot");
        assert_eq!(second_root.code, "invalid_state_base");
        assert_eq!(
            state_revision_counts(&storage, &candidate_root.stream_id),
            before
        );

        let graph = storage
            .read_state_revision_graph(&conversation_id, &branch_id, None)
            .expect("candidate-root graph should remain readable");
        assert_eq!(graph.through_branch_sequence, 1);
        assert_eq!(graph.accepted_head_branch_sequence, 0);
        assert_eq!(graph.revisions.len(), 2);
        assert_eq!(graph.revisions[0].status, "candidate");
        assert_eq!(graph.revisions[1].status, "candidate");
        assert_eq!(
            graph.revisions[1].parent_state_revision_ids,
            vec![candidate_root_id]
        );
        assert_eq!(graph.accepted_head_state_revision_id, None);
    }

    #[test]
    fn state_revision_canonical_hash_ignores_idempotency_key_and_json_formatting() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("State revision canonical hash"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();

        let root = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "root",
                "accepted",
                None,
                "canonical-root",
                Vec::new(),
            ))
            .expect("root revision should append");
        let root_id = root
            .revision_id
            .clone()
            .expect("root revision id should exist");

        let mut first_request = state_revision_request(
            &conversation_id,
            &branch_id,
            "checkpoint",
            "candidate",
            Some(&root_id),
            "canonical-first-key",
            vec![root_id.clone()],
        );
        first_request.manifest_json = r#"{"z":2,"a":1}"#.to_owned();
        let first = storage
            .append_state_revision(first_request)
            .expect("first semantically equivalent candidate should append");

        let mut second_request = state_revision_request(
            &conversation_id,
            &branch_id,
            "checkpoint",
            "candidate",
            Some(&root_id),
            "canonical-second-key",
            vec![root_id.clone()],
        );
        second_request.manifest_json = r#"{"a":1,"z":2}"#.to_owned();
        let second = storage
            .append_state_revision(second_request)
            .expect("second semantically equivalent candidate should append");

        assert_ne!(first.revision_id, second.revision_id);
        assert_eq!(first.canonical_payload_hash, second.canonical_payload_hash);
        assert_eq!(
            state_revision_counts(&storage, &first.stream_id),
            (3, 2, 2, 3, 3)
        );
    }

    #[test]
    fn state_revision_canonical_hash_matches_effective_implicit_parent_resolution() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("State revision implicit canonical hash"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();

        let root = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "root",
                "accepted",
                None,
                "implicit-canonical-root",
                Vec::new(),
            ))
            .expect("root revision should append");
        let root_id = root
            .revision_id
            .clone()
            .expect("root revision id should exist");

        // The first request uses the convenience form. Native storage resolves
        // both the expected head and the implicit parent from the same observed
        // head before hashing. The second request spells out that effective
        // state explicitly; only the idempotency key differs and it is not part
        // of the canonical operation payload.
        let mut implicit_request = state_revision_request(
            &conversation_id,
            &branch_id,
            "checkpoint",
            "candidate",
            None,
            "implicit-canonical-convenience",
            Vec::new(),
        );
        implicit_request.manifest_json =
            r#"{"nested":{"z":2,"a":[{"y":false,"x":"value"}]}}"#.to_owned();
        let implicit = storage
            .append_state_revision(implicit_request)
            .expect("implicit-parent candidate should append");

        let mut explicit_request = state_revision_request(
            &conversation_id,
            &branch_id,
            "checkpoint",
            "candidate",
            Some(&root_id),
            "implicit-canonical-explicit",
            vec![root_id.clone()],
        );
        explicit_request.manifest_json =
            r#"{ "nested": { "a": [ { "x": "value", "y": false } ], "z": 2 } }"#.to_owned();
        let explicit = storage
            .append_state_revision(explicit_request)
            .expect("explicit effective-parent candidate should append");

        assert_eq!(
            implicit.expected_head_state_revision_id,
            explicit.expected_head_state_revision_id
        );
        assert_eq!(
            implicit.canonical_payload_hash,
            explicit.canonical_payload_hash
        );
        assert_eq!(
            state_revision_counts(&storage, &implicit.stream_id),
            (3, 2, 2, 3, 3)
        );
    }

