    #[test]
    fn state_revision_immutable_fact_tables_reject_update_and_delete() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("State revision immutable facts"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();

        let root = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "root",
                "accepted",
                None,
                "immutable-root",
                Vec::new(),
            ))
            .expect("root revision should append");
        let root_id = root
            .revision_id
            .clone()
            .expect("root revision id should exist");
        let child = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "continuation",
                "accepted",
                Some(&root_id),
                "immutable-child",
                vec![root_id.clone()],
            ))
            .expect("child revision should append");
        let child_id = child
            .revision_id
            .clone()
            .expect("child revision id should exist");
        let edge_id = storage
            .with_connection(|connection| {
                connection
                    .query_row(
                        "SELECT id FROM state_revision_edges WHERE from_revision_id = ?1",
                        [&child_id],
                        |row| row.get::<_, String>(0),
                    )
                    .map_err(NativeError::from)
            })
            .expect("child edge should exist");
        let idempotency_hash = sha256_hex("immutable-child");
        let before = state_revision_counts(&storage, &root.stream_id);

        let stream_update_error = storage
            .with_connection(|connection| {
                connection
                    .execute(
                        "UPDATE state_revision_streams SET created_at_ms = created_at_ms WHERE id = ?1",
                        [&root.stream_id],
                    )
                    .map(|_| ())
                    .map_err(NativeError::from)
            })
            .expect_err("state-revision stream update must be rejected");
        assert_eq!(stream_update_error.code, "storage_failed");

        let revision_update_error = storage
            .with_connection(|connection| {
                connection
                    .execute(
                        "UPDATE state_revisions SET status = status WHERE id = ?1",
                        [&child_id],
                    )
                    .map(|_| ())
                    .map_err(NativeError::from)
            })
            .expect_err("state-revision update must be rejected");
        assert_eq!(revision_update_error.code, "storage_failed");

        let parent_update_error = storage
            .with_connection(|connection| {
                connection
                    .execute(
                        "UPDATE state_revision_parents SET ordinal = ordinal
                         WHERE revision_id = ?1 AND parent_revision_id = ?2",
                        rusqlite::params![child_id, root_id],
                    )
                    .map(|_| ())
                    .map_err(NativeError::from)
            })
            .expect_err("state-revision parent update must be rejected");
        assert_eq!(parent_update_error.code, "storage_failed");

        let edge_update_error = storage
            .with_connection(|connection| {
                connection
                    .execute(
                        "UPDATE state_revision_edges SET kind = kind WHERE id = ?1",
                        [&edge_id],
                    )
                    .map(|_| ())
                    .map_err(NativeError::from)
            })
            .expect_err("state-revision edge update must be rejected");
        assert_eq!(edge_update_error.code, "storage_failed");

        let idempotency_update_error = storage
            .with_connection(|connection| {
                connection
                    .execute(
                        "UPDATE state_revision_idempotency SET receipt_json = receipt_json
                         WHERE stream_id = ?1 AND idempotency_key_hash = ?2",
                        rusqlite::params![root.stream_id, idempotency_hash],
                    )
                    .map(|_| ())
                    .map_err(NativeError::from)
            })
            .expect_err("idempotency receipt update must be rejected");
        assert_eq!(idempotency_update_error.code, "storage_failed");

        let stream_delete_error = storage
            .with_connection(|connection| {
                connection
                    .execute(
                        "DELETE FROM state_revision_streams WHERE id = ?1",
                        [&root.stream_id],
                    )
                    .map(|_| ())
                    .map_err(NativeError::from)
            })
            .expect_err("state-revision stream delete must be rejected");
        assert_eq!(stream_delete_error.code, "storage_failed");

        let revision_delete_error = storage
            .with_connection(|connection| {
                connection
                    .execute("DELETE FROM state_revisions WHERE id = ?1", [&child_id])
                    .map(|_| ())
                    .map_err(NativeError::from)
            })
            .expect_err("state-revision delete must be rejected");
        assert_eq!(revision_delete_error.code, "storage_failed");

        let parent_delete_error = storage
            .with_connection(|connection| {
                connection
                    .execute(
                        "DELETE FROM state_revision_parents
                         WHERE revision_id = ?1 AND parent_revision_id = ?2",
                        rusqlite::params![child_id, root_id],
                    )
                    .map(|_| ())
                    .map_err(NativeError::from)
            })
            .expect_err("state-revision parent delete must be rejected");
        assert_eq!(parent_delete_error.code, "storage_failed");

        let edge_delete_error = storage
            .with_connection(|connection| {
                connection
                    .execute("DELETE FROM state_revision_edges WHERE id = ?1", [&edge_id])
                    .map(|_| ())
                    .map_err(NativeError::from)
            })
            .expect_err("state-revision edge delete must be rejected");
        assert_eq!(edge_delete_error.code, "storage_failed");

        let idempotency_delete_error = storage
            .with_connection(|connection| {
                connection
                    .execute(
                        "DELETE FROM state_revision_idempotency
                         WHERE stream_id = ?1 AND idempotency_key_hash = ?2",
                        rusqlite::params![root.stream_id, idempotency_hash],
                    )
                    .map(|_| ())
                    .map_err(NativeError::from)
            })
            .expect_err("idempotency receipt delete must be rejected");
        assert_eq!(idempotency_delete_error.code, "storage_failed");

        assert_eq!(state_revision_counts(&storage, &root.stream_id), before);
    }

    #[test]
    fn state_revision_graph_detects_tampered_accepted_head_projection() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("State revision head tamper"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();

        let root = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "root",
                "accepted",
                None,
                "tamper-root",
                Vec::new(),
            ))
            .expect("root revision should append");
        let root_id = root
            .revision_id
            .clone()
            .expect("root revision id should exist");
        let child = storage
            .append_state_revision(state_revision_request(
                &conversation_id,
                &branch_id,
                "continuation",
                "accepted",
                Some(&root_id),
                "tamper-child",
                vec![root_id.clone()],
            ))
            .expect("child revision should append");
        let child_id = child.revision_id.expect("child revision id should exist");

        storage
            .with_connection(|connection| {
                connection.execute("DROP TRIGGER state_revision_heads_scope_guard_update", [])?;
                connection.execute(
                    "UPDATE state_revision_heads
                     SET accepted_revision_id = ?1, branch_sequence = 0
                     WHERE stream_id = ?2",
                    rusqlite::params![root_id, root.stream_id],
                )?;
                Ok(())
            })
            .expect("test-only trigger removal and tamper should succeed");

        let error = storage
            .read_state_revision_graph(&conversation_id, &branch_id, None)
            .expect_err("a head projection that disagrees with immutable facts must fail closed");
        assert_eq!(error.code, "state_revision_integrity_failed");
        assert!(error.message.contains("accepted-head"));
        assert!(!child_id.is_empty());
    }

