    #[test]
    fn state_revision_projection_serialization_excludes_sensitive_manifests() {
        let storage = Storage::in_memory().expect("storage should initialize");
        let conversation = storage
            .create_conversation(None, Some("State revision projection redaction"))
            .expect("conversation should be created");
        let conversation_id = conversation.conversation.id.clone();
        let branch_id = conversation.conversation.active_branch_id.clone();
        let mut request = state_revision_request(
            &conversation_id,
            &branch_id,
            "root",
            "accepted",
            None,
            "projection-redaction",
            Vec::new(),
        );
        request.manifest_json = r#"{
            "absolutePath":"C:\\Users\\khang\\private\\report.pdf",
            "cookie":"session-cookie-secret",
            "credentialRef":"provider_secret_0123456789abcdef0123456789abcdef"
        }"#
        .to_owned();
        request.authority_json = r#"{
            "authorization":"Bearer top-secret-token"
        }"#
        .to_owned();
        request.routing_cache_json = r#"{
            "providerHeader":"x-api-key: should-not-cross-boundary"
        }"#
        .to_owned();
        storage
            .append_state_revision(request)
            .expect("redacted state revision should append");

        let graph = storage
            .read_state_revision_graph(&conversation_id, &branch_id, None)
            .expect("projection should be readable");
        let serialized = serde_json::to_string(&graph).expect("projection should serialize");
        for sensitive in [
            "absolutePath",
            "report.pdf",
            "session-cookie-secret",
            "provider_secret_0123456789abcdef0123456789abcdef",
            "top-secret-token",
            "x-api-key",
        ] {
            assert!(
                !serialized.contains(sensitive),
                "projection must not expose sensitive value {sensitive}"
            );
        }
        assert!(serialized.contains("stateDigest"));
        assert!(serialized.contains("integrity"));
    }

